
/* === BLOCK 1 === */

/* ══════════════════════════════════════
   KARMA — 2026-05-09
   Clean app layout · Living pet · Video-first
══════════════════════════════════════ */
:root {
  --bg:   #000;
  --s1:   #0a0a0f;
  --s2:   #111118;
  --s3:   #1a1a24;
  --s4:   #242432;
  --line: rgba(255,255,255,.08);
  --t1:   #f2f2fa;
  --t2:   #888;
  --t3:   #444;
  --green:  #00ff88;
  --blue:   #4488ff;
  --pink:   #ff3377;
  --gold:   #ffcc00;
  --purple: #aa66ff;
  --red:    #ff4455;
  --orange: #ff8844;
  --teal:   #00ddcc;
  --sab: env(safe-area-inset-bottom, 0px);
  --sat: env(safe-area-inset-top, 0px);
  --ff-head: 'Syne', sans-serif;
  --ff-body: 'DM Sans', sans-serif;
}
*, *::before, *::after { margin:0; padding:0; box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
html, body {
  height: 100%; width: 100%; overflow: hidden;
  background: var(--bg); color: var(--t1);
  font-family: var(--ff-body);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

/* ── SHELL ── */
#app {
  width: 100%; height: 100%;
  max-width: 430px; margin: 0 auto;
  display: none; flex-direction: column;
  position: relative;
}

/* ── TOP BAR ── */
.topbar {
  position: absolute; top: 0; left: 0; right: 0; z-index: 200;
  height: calc(52px + var(--sat));
  padding-top: var(--sat);
  display: flex; align-items: center;
  padding-left: 16px; padding-right: 16px; gap: 10px;
  background: linear-gradient(to bottom, rgba(0,0,0,.9), transparent);
}
.logo {
  font-family: var(--ff-head);
  font-size: 22px; font-weight: 900;
  letter-spacing: -1px; flex-shrink: 0;
}
.logo span { color: var(--green); }
.pills { display: flex; gap: 5px; flex: 1; overflow: hidden; }
.pill {
  padding: 4px 10px; border-radius: 20px; font-size: 11px; font-weight: 700;
  display: flex; align-items: center; gap: 3px; white-space: nowrap;
  border: 1px solid rgba(255,255,255,.12);
  background: rgba(0,0,0,.6); backdrop-filter: blur(8px);
}
.pill-y { color: var(--gold); }
.pill-r { color: var(--red); }
.pill-g { color: var(--green); }

/* HAMBURGER */
.menu-wrap { position: relative; flex-shrink: 0; }
.ham {
  width: 36px; height: 36px;
  background: rgba(0,0,0,.6); backdrop-filter: blur(8px);
  border: 1px solid rgba(255,255,255,.12); border-radius: 10px;
  display: flex; flex-direction: column; align-items: center;
  justify-content: center; gap: 4px; cursor: pointer;
}
.ham span { display:block; width:14px; height:2px; background:var(--t1); border-radius:1px; transition:all .2s; }
.ham.open span:nth-child(1) { transform:rotate(45deg) translate(4px,4px); }
.ham.open span:nth-child(2) { opacity:0; }
.ham.open span:nth-child(3) { transform:rotate(-45deg) translate(4px,-4px); }
.dd {
  position: fixed; top: calc(58px + var(--sat)); right: 12px; z-index: 999;
  width: 224px;
  background: linear-gradient(160deg,rgba(10,4,28,.98),rgba(4,2,14,.97)); border: 1px solid rgba(255,255,255,.1);
  border-radius: 20px; box-shadow: 0 24px 64px rgba(0,0,0,.97),0 0 40px rgba(0,255,136,.04);
  overflow: hidden; opacity: 0; pointer-events: none;
  transform: translateY(-10px) scale(.95); transform-origin: top right;
  transition: all .2s cubic-bezier(.34,1.56,.64,1);
}
.dd.open { opacity:1; pointer-events:all; transform:translateY(0) scale(1); }
.dd-head { padding: 14px 16px 11px; border-bottom: 1px solid rgba(255,255,255,.06); background:rgba(0,255,136,.03); }
.dd-nm { font-family: var(--ff-head); font-size: 15px; font-weight: 900; }
.dd-sb { font-size: 11px; color: var(--t3); margin-top: 2px; }
.dd-sec { padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,.05); }
.dd-sec:last-child { border-bottom: none; }
.ddr {
  display: flex; align-items: center; gap: 10px;
  padding: 11px 16px; cursor: pointer; font-size: 13px; font-weight: 700;
  transition: background .1s; font-family: var(--ff-head); letter-spacing:.2px;
}
.ddr:active { background: rgba(255,255,255,.04); }
.ddr-i { font-size: 17px; width: 22px; text-align: center; }
.dd-search-wrap { padding:5px 10px 3px; border-bottom:1px solid rgba(255,255,255,.05); position:sticky;top:0;z-index:2;background:linear-gradient(160deg,rgba(10,4,28,.99),rgba(6,2,18,.99)); }
.dd-search { width:100%;box-sizing:border-box;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12);border-radius:8px;padding:6px 10px 6px 8px;color:#fff;font-size:12px;font-family:var(--ff-head);outline:none;transition:border-color .15s,background .15s; }
.dd-search::placeholder { color:rgba(255,255,255,.3); }
.dd-search:focus { border-color:rgba(0,255,136,.45);background:rgba(0,255,136,.06); }

/* ── VIEWS ── */
.main { flex: 1; overflow: hidden; position: relative; }
.view {
  position: absolute; inset: 0;
  overflow-y: auto; overflow-x: hidden;
  display: none; flex-direction: column;
  scrollbar-width: none; background: var(--bg);
}
.view::-webkit-scrollbar { display: none; }
.view.active { display: flex; }
.vend { height: 90px; flex-shrink: 0; }

/* ── BOTTOM NAV ── */
.bnav {
  display: flex; align-items: center;
  background: rgba(0,0,0,.97); backdrop-filter: blur(32px) saturate(1.4);
  border-top: 1px solid rgba(255,255,255,.08);
  padding: 8px 0; padding-bottom: calc(8px + var(--sab));
  flex-shrink: 0; z-index: 200; position: relative;
}
.bnav::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 1px;
  background: linear-gradient(90deg, rgba(0,255,136,0), rgba(0,255,136,.4), rgba(68,136,255,.4), rgba(255,51,119,.3), rgba(0,255,136,0));
  pointer-events: none;
}
.nb {
  flex: 1; background: none; border: none; cursor: pointer;
  display: flex; flex-direction: column; align-items: center; gap: 3px; padding: 4px;
}
.nb .ni { font-size: 22px; transition: transform .2s; }
.nb .nl { font-size: 9px; font-weight: 700; color: var(--t3); text-transform: uppercase; letter-spacing: .5px; }
.nb.on .ni { transform: scale(1.15); filter: drop-shadow(0 0 8px var(--green)); }
.nb.on .nl { color: var(--green); }
.nb-center {
  flex: 1; background: none; border: none; cursor: pointer;
  display: flex; flex-direction: column; align-items: center; gap: 3px;
}
.nb-center-ico {
  width: 54px; height: 54px; border-radius: 18px;
  background: linear-gradient(135deg, var(--pink), var(--purple));
  display: flex; align-items: center; justify-content: center;
  font-size: 26px; margin-top: -22px;
  box-shadow: 0 8px 28px rgba(255,51,119,.55), 0 0 0 1px rgba(255,51,119,.2);
  transition: all .12s;
}
.nb-center:active .nb-center-ico { transform: scale(.88); }
.nb-center .nl { font-size: 9px; font-weight: 700; color: var(--pink); text-transform: uppercase; letter-spacing: .5px; }

/* PET COMPANION FLOATING */
.pet-float {
  position: fixed; right: 14px;
  bottom: calc(90px + var(--sab));
  z-index: 50; cursor: pointer;
  display: flex; flex-direction: column; align-items: center; gap: 2px;
}
.pf-body {
  width: 54px; height: 54px; border-radius: 16px;
  background: linear-gradient(135deg,rgba(12,4,26,.92),rgba(6,2,14,.96)); border: 2.5px solid var(--green);
  display: flex; align-items: center; justify-content: center;
  font-size: 26px; position: relative;
  box-shadow: 0 0 20px rgba(0,255,136,.2);
  animation: pfloat 3s ease-in-out infinite;
}
@keyframes pfloat {
  0%,100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-8px) rotate(3deg); }
}
.pf-body.hungry { border-color: var(--red); box-shadow: 0 0 20px rgba(255,68,85,.3); animation: pshake .3s ease infinite alternate; }
@keyframes pshake { from{transform:translateX(-2px);}to{transform:translateX(2px);} }
.pf-body.happy { border-color: var(--gold); box-shadow: 0 0 20px rgba(255,204,0,.3); }
.pf-mood {
  position: absolute; bottom: -7px; left: 50%; transform: translateX(-50%);
  background: rgba(10,4,22,.88); border: 1px solid rgba(255,255,255,.1);
  border-radius: 8px; padding: 1px 6px; font-size: 10px; white-space: nowrap;
}
.pf-lv { font-size: 9px; font-weight: 800; color: var(--green); font-family: var(--ff-head); }

/* ══════════════════════
   🐾 PET VIEW — FULL REDESIGN
══════════════════════ */
#view-pet {
  background: var(--bg);
  padding-top: calc(52px + var(--sat));
}

/* BIG PET STAGE */
.pet-stage {
  width: 100%; height: 264px;
  position: relative; display: flex; align-items: center; justify-content: center;
  overflow: hidden; flex-shrink: 0;
}
.pet-stage-bg {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 70%, rgba(0,255,136,.12) 0%, transparent 70%);
  animation: bgpulse 3s ease-in-out infinite;
}
@keyframes bgpulse { 0%,100%{opacity:.7;}50%{opacity:1;} }
/* Orbiting particles */
.pet-particles {
  position: absolute; inset: 0; pointer-events: none;
}
.particle {
  position: absolute; width: 6px; height: 6px;
  border-radius: 50%; background: var(--green); opacity: 0;
  animation: orbit var(--dur) var(--delay) ease-in-out infinite;
}
@keyframes orbit {
  0%   { opacity:0; transform:translate(var(--x0),var(--y0)) scale(0); }
  20%  { opacity:.8; }
  80%  { opacity:.6; }
  100% { opacity:0; transform:translate(var(--x1),var(--y1)) scale(1.5); }
}
/* The pet itself */
.pet-main-wrap {
  position: relative; z-index: 5;
  display: flex; flex-direction: column; align-items: center; gap: 0;
}
.pet-aura {
  width: 180px; height: 180px; border-radius: 50%;
  background: radial-gradient(circle, rgba(0,255,136,.15) 0%, transparent 70%);
  position: absolute; animation: aura 2s ease-in-out infinite;
}
@keyframes aura { 0%,100%{transform:scale(1);}50%{transform:scale(1.15);} }
.pet-emoji-big {
  font-size: 90px; z-index: 2; position: relative;
  animation: petbounce 2.4s cubic-bezier(.36,.07,.19,.97) infinite, neonPulse 2s ease-in-out infinite;
  cursor: pointer; user-select: none;
  transition: filter .3s;
}
@keyframes petbounce {
  0%,100% { transform: translateY(0) scale(1); }
  40%     { transform: translateY(-18px) scale(1.05); }
  60%     { transform: translateY(-14px) scale(1.03); }
}
.pet-emoji-big:active {
  animation: petpop .3s cubic-bezier(.34,1.56,.64,1);
  filter: drop-shadow(0 0 40px rgba(0,255,136,.8));
}
@keyframes petpop {
  0%   { transform: scale(1); }
  50%  { transform: scale(1.35) rotate(8deg); }
  100% { transform: scale(1); }
}
.pet-gear-badge {
  position: absolute; bottom: 8px; right: -8px;
  font-size: 24px; z-index: 6;
  filter: drop-shadow(0 2px 6px rgba(0,0,0,.6));
}
.pet-accessory-hat {
  position: absolute; top: -28px; left: 50%; transform: translateX(-50%);
  font-size: 34px; z-index: 7; pointer-events: none;
  filter: drop-shadow(0 2px 8px rgba(0,0,0,.7));
  animation: hatFloat 3s ease-in-out infinite;
}
@keyframes hatFloat { 0%,100%{transform:translateX(-50%) translateY(0);} 50%{transform:translateX(-50%) translateY(-4px);} }
.pet-stage-name {
  font-family: var(--ff-head); font-size: 12px; font-weight: 700;
  color: var(--green); letter-spacing: 2px; text-transform: uppercase;
  z-index: 2; margin-top: 6px;
  background: rgba(0,255,136,.08); border: 1px solid rgba(0,255,136,.18);
  padding: 3px 12px; border-radius: 20px;
}
/* Vitals strip on stage */
.pet-stage-vitals {
  position: absolute; bottom: 0; left: 0; right: 0; z-index: 10;
  padding: 6px 14px 8px;
  background: linear-gradient(to top, rgba(0,0,0,.7) 0%, transparent 100%);
  display: flex; gap: 8px; align-items: flex-end;
}
.psv-item { flex: 1; }
.psv-lbl { font-size: 8px; font-weight: 800; color: rgba(255,255,255,.5); text-transform: uppercase; display: flex; justify-content: space-between; margin-bottom: 2px; }
.psv-lbl span:last-child { color: rgba(255,255,255,.8); }
.psv-bar { height: 4px; background: rgba(255,255,255,.1); border-radius: 2px; overflow: hidden; }
.psv-fill { height: 100%; border-radius: 2px; transition: width .5s; }

/* Pet info card under stage */
.pet-info-card {
  margin: 0 14px 12px;
  background: linear-gradient(160deg,rgba(12,4,28,.9),rgba(4,2,10,.95)); border: 1px solid rgba(255,255,255,.07);
  border-radius: 18px; padding: 12px 14px;
}
.pet-name-row {
  display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px;
}
.pet-name-big {
  font-family: var(--ff-head); font-size: 22px; font-weight: 900; line-height: 1;
}
.pet-lv-badge {
  background: linear-gradient(135deg, var(--green), var(--teal));
  color: var(--bg); font-family: var(--ff-head); font-size: 13px; font-weight: 800;
  padding: 5px 12px; border-radius: 10px;
}
.pet-evol { font-size: 10px; color: var(--gold); font-weight: 700; margin-top: 3px; }
/* XP bar */
.xp-wrap { margin-bottom: 10px; }
.xp-labels { display: flex; justify-content: space-between; font-size: 10px; color: var(--t3); margin-bottom: 4px; }
.xp-track { height: 7px; background: rgba(255,255,255,.06); border-radius: 100px; overflow: hidden; }
.xp-fill { height: 100%; background: linear-gradient(90deg, var(--green), var(--teal)); border-radius: 100px; transition: width .7s cubic-bezier(.34,1.56,.64,1); position: relative; }
.xp-fill::after { content:''; position:absolute; right:0; top:0; bottom:0; width:5px; background:rgba(255,255,255,.4); border-radius:100px; animation:xpshine 1.5s ease-in-out infinite; }
@keyframes xpshine { 0%,100%{opacity:0;}50%{opacity:1;} }
/* Stats 3-col */
.stats-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px; }
.stat-fill { height:100%; border-radius:2px; box-shadow:0 0 6px currentColor; }
.stat-box {
  background: linear-gradient(180deg,rgba(10,4,22,.95),rgba(4,2,12,.9)); border: 1px solid rgba(255,255,255,.07);
  border-radius: 14px; padding: 10px 6px; text-align: center; box-shadow:0 3px 12px rgba(0,0,0,.35);
}
.stat-val { font-family: var(--ff-head); font-size: 22px; font-weight: 900; line-height: 1; }
.stat-bar { height: 5px; background: rgba(255,255,255,.06); border-radius: 2px; overflow: hidden; margin-top: 5px; }
.stat-lbl { font-size: 8px; color: var(--t3); text-transform: uppercase; letter-spacing: .8px; margin-top: 3px; font-weight:800; }

/* Vitals — now a compact inline card */
.vitals-card {
  display: none; /* replaced by stage overlay vitals */
  margin: 0 14px 12px;
  background: linear-gradient(160deg,rgba(12,4,28,.9),rgba(4,2,10,.95)); border: 1px solid rgba(255,255,255,.07);
  border-radius: 18px; padding: 14px;
}
.vitals-title { font-size: 10px; font-weight: 700; color: var(--t3); text-transform: uppercase; letter-spacing: .8px; margin-bottom: 14px; }
.vital-row { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }
.vital-row:last-child { margin-bottom: 0; }
.vital-icon { font-size: 18px; width: 24px; text-align: center; flex-shrink: 0; }
.vital-name { font-size: 11px; font-weight: 700; color: var(--t2); width: 52px; flex-shrink: 0; text-transform: uppercase; }
.vital-track { flex: 1; height: 7px; background: rgba(255,255,255,.06); border-radius: 100px; overflow: hidden; }
.vital-fill { height: 100%; border-radius: 100px; transition: width .5s ease; }
.vital-val { font-size: 12px; font-weight: 700; width: 28px; text-align: right; flex-shrink: 0; }

/* Care buttons — 4-col grid */
.care-grid {
  display: grid; grid-template-columns: repeat(4,1fr);
  gap: 8px; margin: 0 14px 14px;
}
.care-btn {
  background: linear-gradient(180deg,rgba(10,4,22,.95),rgba(4,2,12,.9)); border: 1.5px solid rgba(255,255,255,.08);
  border-radius: 16px; padding: 13px 4px 10px; text-align: center;
  cursor: pointer; transition: all .15s; -webkit-user-select: none;
  position: relative; overflow: hidden; box-shadow:0 4px 14px rgba(0,0,0,.4);
}
.care-btn:active { transform: scale(.89); }
.care-btn:active::after { content:''; position:absolute; inset:0; border-radius:inherit; background:rgba(255,255,255,.06); animation:careTapRipple .35s ease-out forwards; pointer-events:none; }
@keyframes careTapRipple { from{transform:scale(1);opacity:1} to{transform:scale(1.12);opacity:0} }
.care-btn.warn { border-color: var(--red) !important; animation: careWarn 1s ease-in-out infinite; }
@keyframes careWarn { 0%,100%{box-shadow:0 0 0 rgba(255,68,85,0)} 50%{box-shadow:0 0 14px rgba(255,68,85,.45)} }
.care-ico { font-size: 28px; display: block; margin-bottom: 5px; }
.care-lbl { font-size: 9px; font-weight: 900; display: block; letter-spacing: .3px; text-transform: uppercase; }
.care-cost { font-size: 7.5px; color: var(--t3); display: block; margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Minigame */
.minigame-card {
  margin: 0 16px 16px;
  background: linear-gradient(160deg,rgba(10,4,22,.92),rgba(4,2,10,.97)); border: 1px solid rgba(255,255,255,.07);
  border-radius: 20px; padding: 20px; text-align: center;
}
.mg-title { font-family: var(--ff-head); font-size: 16px; margin-bottom: 4px; }
.mg-sub { font-size: 12px; color: var(--t2); margin-bottom: 14px; }
.mg-score { font-family: var(--ff-head); font-size: 52px; font-weight: 900; color: var(--green); line-height: 1; margin-bottom: 16px; }
.mg-tap {
  width: 100px; height: 100px; border-radius: 50%; border: none;
  background: linear-gradient(135deg, var(--green), var(--teal));
  display: flex; align-items: center; justify-content: center;
  font-size: 44px; cursor: pointer; margin: 0 auto;
  box-shadow: 0 0 0 0 rgba(0,255,136,.4);
  animation: mgpulse 2s ease-in-out infinite;
  transition: all .1s;
}
.mg-tap:active { transform: scale(.8); animation: none; }
@keyframes mgpulse {
  0%,100% { box-shadow: 0 0 0 0 rgba(0,255,136,.4); }
  50%     { box-shadow: 0 0 0 16px rgba(0,255,136,0); }
}
.mg-rec { font-size: 12px; color: var(--t3); margin-top: 14px; }

/* ══════════════════════
   ⚡ FLASH (Video Feed) — Full-screen TikTok style
══════════════════════ */
#view-flash { padding: 0; }

/* Flash top bar - minimal, overlaid on video */
.flash-topbar {
  position: absolute; top: 0; left: 0; right: 0; z-index: 100;
  padding: calc(var(--sat) + 10px) 16px 10px;
  display: flex; align-items: center; gap: 10px;
  background: linear-gradient(to bottom, rgba(0,0,0,.85) 0%, rgba(0,0,0,.5) 60%, transparent 100%);
  pointer-events: none;
}
.flash-title {
  font-family: var(--ff-head); font-size: 20px; font-weight: 900; flex: 1; pointer-events: all;
  background: linear-gradient(135deg, var(--pink) 0%, var(--purple) 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;
  filter: drop-shadow(0 0 8px rgba(255,51,119,.35));
}
.flash-tabs {
  display: flex; gap: 16px; font-size: 14px; font-weight: 700;
  pointer-events: all;
}
.ftab { color: rgba(255,255,255,.45); cursor: pointer; transition: all .2s; padding-bottom: 3px; letter-spacing:.3px; }
.ftab.on {
  color: var(--pink);
  border-bottom: 2px solid var(--pink);
  text-shadow: 0 0 14px rgba(255,51,119,.6);
}

/* Streak bar */
.streak-bar {
  position: absolute; top: calc(var(--sat) + 54px); left: 0; right: 0; z-index: 100;
  display: flex; gap: 10px; overflow-x: auto; scrollbar-width: none; padding: 0 14px 8px;
  pointer-events: all;
}
.streak-bar::-webkit-scrollbar { display: none; }
.sb-item { display: flex; flex-direction: column; align-items: center; gap: 4px; cursor: pointer; flex-shrink: 0; }
.sb-ring {
  width: 56px; height: 56px; border-radius: 50%; padding: 2.5px;
  display: flex; align-items: center; justify-content: center; transition: transform .15s;
}
.sb-ring:active { transform: scale(.9); }
.sb-ring.has-flash { background: conic-gradient(var(--pink), var(--purple), var(--green), var(--pink)); }
.sb-ring.no-flash  { background: conic-gradient(rgba(255,255,255,.08),rgba(255,255,255,.08)); }
.sb-ring.live      { background: conic-gradient(var(--red), var(--gold), var(--red)); animation: livering 1.5s infinite; }
@keyframes livering { 0%,100%{box-shadow:0 0 0 0 rgba(255,68,85,.5);}50%{box-shadow:0 0 0 5px rgba(255,68,85,0);} }
.sb-inner {
  width: 49px; height: 49px; border-radius: 50%;
  background: linear-gradient(160deg,rgba(14,6,30,.9),rgba(6,2,14,.95)); display: flex; align-items: center; justify-content: center; font-size: 24px;
}
.sb-name  { font-size: 9px; color: rgba(255,255,255,.6); max-width: 60px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: center; }
.sb-streak { font-size: 9px; color: var(--red); font-weight: 800; text-align: center; }

/* Video scroll feed */
.video-feed {
  flex: 1; overflow-y: scroll; scroll-snap-type: y mandatory; scrollbar-width: none;
}
.video-feed::-webkit-scrollbar { display: none; }
.video-card {
  scroll-snap-align: start; height: 100svh;
  display: flex; flex-direction: column; position: relative;
  background: var(--bg);
}
/* The "video" area */
.vc-media {
  flex: 1; position: relative; overflow: hidden;
  background: linear-gradient(180deg,rgba(8,3,18,.98),rgba(2,0,8,.99));
  display: flex; align-items: center; justify-content: center;
}
.vc-bg-emoji { font-size: 210px; opacity: .07; user-select: none; animation:bgEmoPulse 9s ease-in-out infinite; filter:blur(1px); }
@keyframes bgEmoPulse { 0%,100%{transform:scale(1) rotate(-4deg);opacity:.07} 50%{transform:scale(1.12) rotate(4deg);opacity:.1} }
/* Gradient overlay on video */
.vc-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(0,0,0,.15) 0%,
    transparent 28%,
    rgba(0,0,0,.15) 60%,
    rgba(0,0,0,.88) 100%
  );
  pointer-events: none;
}
.vc-media::before {
  content:''; position:absolute; inset:0; pointer-events:none;
  background:radial-gradient(ellipse 60% 50% at 50% 45%,rgba(255,255,255,.06),transparent 70%);
  z-index:1;
}
/* Right-side TikTok actions */
.vc-actions {
  position: absolute; right: 12px; bottom: 80px;
  display: flex; flex-direction: column; gap: 18px; align-items: center; z-index: 10;
}
.vca {
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  cursor: pointer;
}
.vca-ico {
  width: 46px; height: 46px; border-radius: 50%;
  background: rgba(0,0,0,.55); backdrop-filter: blur(12px) saturate(1.4);
  border: 1px solid rgba(255,255,255,.18);
  display: flex; align-items: center; justify-content: center; font-size: 22px;
  transition: transform .15s, box-shadow .15s;
  box-shadow: 0 4px 20px rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.08);
}
.vca:active .vca-ico { transform: scale(.78); }
.vca:hover .vca-ico { box-shadow: 0 4px 24px rgba(0,0,0,.7), 0 0 14px rgba(255,255,255,.12); }
.vca-ico.liked { background: rgba(255,51,119,.35); border-color: rgba(255,51,119,.6); box-shadow:0 0 18px rgba(255,51,119,.3); }
.vca-cnt { font-size: 11px; font-weight: 800; color: #fff; text-shadow: 0 1px 6px rgba(0,0,0,.9); letter-spacing:.3px; }
/* Bottom info overlay */
.vc-info {
  position: absolute; bottom: 0; left: 0; right: 60px; padding: 16px 14px 20px;
  z-index: 5;
}
.vc-user { display: flex; align-items: center; gap: 9px; margin-bottom: 8px; }
.vc-ava {
  width: 38px; height: 38px; border-radius: 50%;
  border: 2px solid rgba(255,255,255,.9); background: linear-gradient(135deg,rgba(16,6,32,.9),rgba(6,2,14,.95));
  display: flex; align-items: center; justify-content: center; font-size: 20px; flex-shrink: 0;
  box-shadow: 0 0 12px rgba(255,255,255,.25), 0 2px 8px rgba(0,0,0,.6);
}
.vc-uname { font-weight: 900; font-size: 15px; text-shadow: 0 1px 6px rgba(0,0,0,.9); letter-spacing:.3px; }
.vc-sub { font-size: 11px; color: rgba(255,255,255,.65); font-weight:600; }
.vc-caption { font-size: 14px; line-height: 1.65; text-shadow: 0 1px 6px rgba(0,0,0,.9); margin-bottom: 9px; font-weight:500; }
.vc-tags { display: flex; gap: 6px; flex-wrap: wrap; }
/* Flash stamp - replaces POIDH */
