/* ══════════════════════
   👤 PROFILE
══════════════════════ */
#view-profile { padding-top: calc(52px + var(--sat)); }
.prof-cover { height:110px;background:linear-gradient(135deg,color-mix(in srgb,var(--pet-col,#00ff88) 18%,transparent),rgba(68,136,255,.08));position:relative;overflow:hidden;flex-shrink:0; }
.prof-cover-pat { position:absolute;inset:0;background:repeating-linear-gradient(135deg,transparent,transparent 24px,rgba(255,255,255,.015) 24px,rgba(255,255,255,.015) 25px); }
.prof-cover-glow { position:absolute;inset:0;background:radial-gradient(ellipse at 50% 50%,color-mix(in srgb,var(--pet-col,#00ff88) 12%,transparent),transparent 70%); animation:bgpulse 4s ease-in-out infinite; }
.prof-ava-wr { position:absolute;bottom:-36px;left:16px; }
.prof-ava { width:82px;height:82px;border-radius:24px;background:linear-gradient(180deg,rgba(14,6,30,.9),rgba(6,2,14,.95));border:4px solid var(--bg);display:flex;align-items:center;justify-content:center;font-size:42px;position:relative;box-shadow:0 8px 30px rgba(0,0,0,.7),0 0 0 2px rgba(255,255,255,.08); }
.prof-trust { position:absolute;bottom:-3px;right:-3px;background:var(--green);border:2px solid var(--bg);border-radius:8px;padding:2px 7px;font-size:9px;font-weight:800;color:var(--bg); }
.prof-content { padding:46px 16px 14px;flex-shrink:0; }
.prof-name { font-family:var(--ff-head);font-size:26px;font-weight:900;background:linear-gradient(135deg,#fff,rgba(255,255,255,.8));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text; }
.prof-handle { font-size:13px;color:var(--t3);margin-bottom:4px;font-weight:600;letter-spacing:.3px; }
.prof-bio { font-size:12px;color:var(--t2);margin-bottom:12px;min-height:18px;cursor:pointer;border-bottom:1px dashed rgba(255,255,255,.07);padding-bottom:4px; }
.prof-stats { display:grid;grid-template-columns:repeat(4,1fr);background:linear-gradient(180deg,rgba(0,4,22,.96),rgba(0,2,12,.9));border:1px solid rgba(0,255,136,.1);border-radius:18px;overflow:hidden;margin-bottom:6px; }
.ps { flex:1;text-align:center;padding:13px 6px;border-right:1px solid rgba(255,255,255,.04);border-bottom:1px solid rgba(255,255,255,.04); transition:background .15s; }
.ps:active { background:rgba(255,255,255,.03); }
.ps:nth-child(4),.ps:nth-child(8) { border-right:none; }
.ps:nth-child(5),.ps:nth-child(6),.ps:nth-child(7),.ps:nth-child(8) { border-bottom:none; }
.ps-v { font-family:var(--ff-head);font-size:20px;font-weight:900; }
.ps-l { font-size:8px;color:var(--t3);text-transform:uppercase;letter-spacing:.7px;margin-top:3px;font-weight:800; }
.ps-ico { font-size:14px;margin-bottom:3px; }
/* Activity chart */
.act-chart-wrap { padding:12px 16px 6px; }
.act-chart-hdr { font-size:10px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.8px;margin-bottom:8px; }
.act-chart { display:flex;align-items:flex-end;gap:4px;height:48px; }
.act-bar { flex:1;border-radius:3px 3px 0 0;min-height:3px;transition:height .6s ease; }
.act-days { display:flex;gap:4px;margin-top:3px; }
.act-day { flex:1;text-align:center;font-size:8px;font-weight:700;color:var(--t3); }
.trust-card {
  margin: 0 16px 14px;
  background: rgba(0,255,136,.04); border: 1px solid rgba(0,255,136,.18);
  border-radius: 20px; padding: 16px;
}
.trust-big { font-family:var(--ff-head);font-size:56px;font-weight:900;color:var(--green);line-height:1; }
.tr-row { display:flex;align-items:center;gap:10px;margin-bottom:7px; }
.tr-lbl { font-size:11px;color:var(--t3);width:90px;flex-shrink:0; }
.tr-track { flex:1;height:5px;background:rgba(255,255,255,.06);border-radius:100px;overflow:hidden; }
.tr-fill { height:100%;border-radius:100px;background:linear-gradient(90deg,var(--green),var(--teal));transition:width .7s; }
.tr-val { font-size:11px;font-weight:700;color:var(--green);width:30px;text-align:right;flex-shrink:0; }
.badge-grid { display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:0 16px; }
/* Global game stats grid */
.global-stats-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; padding:0 14px 14px; }
.gstat-box { background:linear-gradient(180deg,rgba(10,4,22,.96),rgba(4,2,12,.94)); border:1.5px solid rgba(255,255,255,.07); border-radius:16px; padding:12px 6px; text-align:center; transition:all .15s; box-shadow:0 4px 12px rgba(0,0,0,.4); }
.gstat-box:active { transform:scale(.93); }
.gstat-ico { font-size:22px; margin-bottom:4px; filter:drop-shadow(0 2px 6px rgba(255,255,255,.15)); }
.gstat-val { font-family:var(--ff-head); font-size:22px; font-weight:900; line-height:1; }
.gstat-lbl { font-size:8px; color:var(--t3); font-weight:800; text-transform:uppercase; letter-spacing:.6px; margin-top:4px; }
/* Achievement rarity colors */
.ach-r-common { color:var(--t2); }
.ach-r-uncommon { color:var(--green); }
.ach-r-rare { color:var(--blue); }
.ach-r-epic { color:var(--purple); }
.ach-r-legendary { color:var(--gold); }
.badge { background:linear-gradient(180deg,rgba(10,4,22,.95),rgba(4,2,12,.9));border:1px solid rgba(255,255,255,.06);border-radius:16px;padding:13px 6px;text-align:center;cursor:pointer;transition:all .15s;box-shadow:0 3px 12px rgba(0,0,0,.35); }
.badge:active { transform:scale(.93); }
.badge.earned { border-color:rgba(255,204,0,.35);background:linear-gradient(180deg,rgba(20,14,0,.95),rgba(10,6,0,.9));box-shadow:0 4px 18px rgba(255,204,0,.1); }
.badge-e { font-size:26px;margin-bottom:5px;filter:drop-shadow(0 2px 8px rgba(255,255,255,.15)); }
.badge-l { font-size:8px;font-weight:800;color:var(--t3);letter-spacing:.3px; }
.badge.earned .badge-l { color:var(--gold); }
.hist-item { display:flex;align-items:center;gap:10px;padding:11px 14px;border-bottom:1px solid var(--line); }
.hist-item:last-child { border-bottom:none; }
.hdot { width:7px;height:7px;border-radius:50%;flex-shrink:0; }
.htxt { flex:1;font-size:13px;line-height:1.4; }
.htime { font-size:10px;color:var(--t3); }

/* ══════════════════════
   ATOMS / SHARED
══════════════════════ */
.card { background:linear-gradient(180deg,rgba(10,4,22,.97),rgba(4,2,12,.95));border:1px solid rgba(255,255,255,.07);border-radius:20px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,.4); }
.sh { display:flex;align-items:center;justify-content:space-between;padding:14px 16px 8px; }
.sh-t { font-size:11px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.8px; }
.sh-a { font-size:12px;font-weight:700;color:var(--green);cursor:pointer; }
.tag { display:inline-flex;align-items:center;gap:3px;padding:3px 9px;border-radius:20px;font-size:10px;font-weight:800;border:1px solid; }
.tg { background:rgba(0,255,136,.09);border-color:rgba(0,255,136,.28);color:var(--green); }
.tb { background:rgba(68,136,255,.09);border-color:rgba(68,136,255,.28);color:var(--blue); }
.tp { background:rgba(170,102,255,.09);border-color:rgba(170,102,255,.28);color:var(--purple); }
.ty { background:rgba(255,204,0,.09);border-color:rgba(255,204,0,.28);color:var(--gold); }
.tr { background:rgba(255,68,85,.09);border-color:rgba(255,68,85,.28);color:var(--red); }
.to { background:rgba(255,136,68,.09);border-color:rgba(255,136,68,.28);color:var(--orange); }
.btn { font-family:var(--ff-body);font-weight:700;border-radius:12px;cursor:pointer;border:none;transition:all .12s;display:inline-flex;align-items:center;justify-content:center;gap:5px;font-size:13px; }
.btn:active { transform:scale(.94); }
.btn-g { background:linear-gradient(135deg,var(--green),var(--teal));color:var(--bg);font-weight:800; }
.btn-pk { background:linear-gradient(135deg,var(--pink),var(--purple));color:#fff;font-weight:800; }
.btn-y { background:var(--gold);color:var(--bg);font-weight:800; }
.btn-b { background:var(--blue);color:#fff; }
.btn-ghost { background:rgba(255,255,255,.06);color:var(--t1);border:1px solid rgba(255,255,255,.1); }
.btn-sm { padding:7px 14px;font-size:12px; }
.btn-md { padding:11px 20px;font-size:14px; }
.btn-lg { padding:14px 24px;font-size:14px;font-weight:800; }
.btn-full { width:100%; }
.inp { width:100%;background:rgba(12,5,26,.8);border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:12px 14px;color:var(--t1);font-family:var(--ff-body);font-size:14px;outline:none;margin-bottom:11px;transition:border-color .18s,box-shadow .18s; }
.inp:focus { border-color:rgba(0,255,136,.45);box-shadow:0 0 14px rgba(0,255,136,.08); }
.inp::placeholder { color:var(--t3); }
textarea.inp { resize:none;min-height:72px; }
.lbl { font-size:10px;font-weight:800;color:var(--t3);letter-spacing:1px;text-transform:uppercase;margin-bottom:5px;display:block;font-family:var(--ff-head); }
.r2 { display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:11px; }
.r2 .inp { margin-bottom:0; }
.trow { display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px; }
.topt { padding:7px 14px;border-radius:20px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.09);font-size:12px;font-weight:700;cursor:pointer;color:var(--t2);white-space:nowrap;transition:all .15s; }
.topt.on { background:var(--green);color:var(--bg);border-color:var(--green);box-shadow:0 0 12px rgba(0,255,136,.2); }

/* MODALS */
.modal { position:fixed;inset:0;z-index:800;background:rgba(0,0,0,.8);backdrop-filter:blur(10px);display:flex;align-items:flex-end;opacity:0;pointer-events:none;transition:opacity .2s; }
.modal.open { opacity:1;pointer-events:all; }
.ms { width:100%;max-width:430px;margin:0 auto;background:linear-gradient(180deg,rgba(12,5,28,.99),rgba(4,2,12,.98));border-radius:24px 24px 0 0;border:1px solid rgba(255,255,255,.1);border-bottom:none;padding:14px 16px calc(30px + var(--sab));max-height:92svh;overflow-y:auto;scrollbar-width:none;transform:translateY(100%);transition:transform .3s cubic-bezier(.32,.72,0,1); }
.ms::-webkit-scrollbar { display:none; }
.modal.open .ms { transform:translateY(0); }
.mh { width:40px;height:4px;background:rgba(255,255,255,.15);border-radius:2px;margin:0 auto 16px; }
.mt { font-family:var(--ff-head);font-size:18px;font-weight:900;margin-bottom:16px;display:flex;align-items:center;justify-content:space-between; }
.mx { width:30px;height:30px;background:rgba(255,255,255,.07);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px;cursor:pointer;color:var(--t2);border:1px solid rgba(255,255,255,.08);transition:background .12s; }
.mx:active { background:rgba(255,255,255,.12); }

/* FULLSCREEN SLIDE */
.fsw { position:fixed;inset:0;z-index:700;background:var(--bg);display:flex;flex-direction:column;transform:translateX(100%);transition:transform .28s cubic-bezier(.32,.72,0,1); }
.fsw.open { transform:translateX(0); }
.fsh { height:calc(52px + var(--sat));padding-top:var(--sat);display:flex;align-items:center;padding:0 14px;padding-top:var(--sat);gap:10px;border-bottom:1px solid rgba(255,255,255,.06);flex-shrink:0;background:linear-gradient(180deg,rgba(8,2,22,.98),rgba(4,1,14,.96));box-shadow:0 2px 16px rgba(0,0,0,.4); }
.fbk { background:none;border:none;color:var(--t2);font-size:24px;cursor:pointer; }
.ftl { font-family:var(--ff-head);font-size:16px;font-weight:900;flex:1; }
.fbd { flex:1;overflow-y:auto;scrollbar-width:none; }
.fbd::-webkit-scrollbar { display:none; }

/* SPLASH */
.splash { position:fixed;inset:0;z-index:900;background:rgba(0,0,0,.97);display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px;opacity:0;pointer-events:none;transition:opacity .2s; }
.splash.show { opacity:1;pointer-events:all; }
@keyframes spop { from{transform:scale(.15) rotate(-12deg);}to{transform:scale(1) rotate(0);} }
.sp-ico { font-size:80px;margin-bottom:14px;animation:spop .45s cubic-bezier(.34,1.56,.64,1); }
.sp-title { font-family:var(--ff-head);font-size:34px;font-weight:900;text-align:center;margin-bottom:8px; }
.sp-sub { font-size:15px;color:var(--t2);text-align:center;margin-bottom:14px; }
.sp-row { display:flex;gap:12px;flex-wrap:wrap;justify-content:center;margin:12px 0 22px; }
.sp-r { background:linear-gradient(180deg,rgba(10,4,22,.95),rgba(4,2,12,.9));border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:12px 18px;text-align:center;min-width:78px;box-shadow:0 4px 14px rgba(0,0,0,.4); }
.sp-rv { font-family:var(--ff-head);font-size:22px;font-weight:900; }
.sp-rl { font-size:10px;color:var(--t3);margin-top:3px; }

/* TOAST */
.toast { position:fixed;bottom:90px;left:50%;transform:translateX(-50%) translateY(12px) scale(.95);background:rgba(8,10,20,.92);backdrop-filter:blur(18px);border:1px solid rgba(255,255,255,.1);border-radius:16px;padding:11px 22px;font-size:13px;font-weight:800;letter-spacing:.3px;z-index:9999;white-space:nowrap;opacity:0;transition:all .25s cubic-bezier(.34,1.56,.64,1);pointer-events:none;max-width:calc(100vw - 28px);text-align:center;font-family:var(--ff-head); }
.toast.show { opacity:1;transform:translateX(-50%) translateY(0) scale(1); }
.toast.g { border-color:rgba(0,255,136,.4);color:var(--green);box-shadow:0 0 20px rgba(0,255,136,.15),0 8px 32px rgba(0,0,0,.6); }
.toast.r { border-color:rgba(255,68,85,.4);color:var(--red);box-shadow:0 0 20px rgba(255,68,85,.15),0 8px 32px rgba(0,0,0,.6); }
.toast.y { border-color:rgba(255,204,0,.4);color:var(--gold);box-shadow:0 0 20px rgba(255,204,0,.15),0 8px 32px rgba(0,0,0,.6); }
.toast.pk { border-color:rgba(255,51,119,.4);color:var(--pink);box-shadow:0 0 20px rgba(255,51,119,.15),0 8px 32px rgba(0,0,0,.6); }
.toast.p  { border-color:rgba(255,51,119,.4);color:var(--pink);box-shadow:0 0 20px rgba(255,51,119,.15),0 8px 32px rgba(0,0,0,.6); }
@keyframes cpop { 0%{opacity:1;transform:translateY(0);}100%{opacity:0;transform:translateY(-50px);} }
.cpop { position:fixed;pointer-events:none;z-index:9999;font-size:14px;font-weight:800;color:var(--gold);animation:cpop .7s ease-out forwards; }

/* ══ FETASTE ADDITIONS ══ */
@keyframes neonPulse {
  0%,100% { filter:drop-shadow(0 0 12px var(--pet-col,#00ff88)) drop-shadow(0 8px 24px rgba(0,0,0,.4)); }
  50%     { filter:drop-shadow(0 0 32px var(--pet-col,#00ff88)) drop-shadow(0 0 64px var(--pet-col,#00ff88)); }
}
@keyframes confettiFall {
  0%   { transform:translateY(0) rotate(0deg) scale(1); opacity:1; }
  100% { transform:translateY(105vh) rotate(720deg) scale(.2); opacity:0; }
}
@keyframes floatUp {
  0%   { opacity:1; transform:translateX(-50%) translateY(0) scale(1); }
  55%  { opacity:1; transform:translateX(-50%) translateY(-42px) scale(1.35); }
  100% { opacity:0; transform:translateX(-50%) translateY(-84px) scale(.7); }
}
.fltxt {
  position:fixed; pointer-events:none; z-index:9999;
  font-family:var(--ff-head); font-size:20px; font-weight:900;
  animation:floatUp .85s ease-out forwards; white-space:nowrap; text-align:center;
}
@keyframes comboPop {
  0%   { transform:translate(-50%,-60%) scale(0) rotate(-10deg); opacity:0; }
  45%  { transform:translate(-50%,-60%) scale(1.45) rotate(5deg); opacity:1; }
  100% { transform:translate(-50%,-60%) scale(1) rotate(0deg); opacity:1; }
}
@keyframes comboGlow {
  0%,100% { text-shadow:0 0 10px currentColor; }
  50%     { text-shadow:0 0 30px currentColor, 0 0 60px currentColor; }
}
.combo-badge {
  position:absolute; top:50%; left:50%;
  transform:translate(-50%,-60%);
  z-index:20; pointer-events:none;
  font-family:var(--ff-head); font-weight:900; text-align:center; line-height:1.15;
  animation:comboPop .32s cubic-bezier(.34,1.56,.64,1) both, comboGlow 1s ease-in-out infinite;
}
@keyframes screenShake {
  0%,100% { transform:translate(0); }
  15%     { transform:translate(-7px,-2px) rotate(-.5deg); }
  30%     { transform:translate(7px,2px) rotate(.5deg); }
  45%     { transform:translate(-4px,-1px); }
  60%     { transform:translate(4px,1px); }
  75%     { transform:translate(-2px); }
}
.shake { animation:screenShake .38s ease both; }
@keyframes staggerIn { from{opacity:0;transform:translateY(20px);} to{opacity:1;transform:translateY(0);} }
.stagger>* { animation:staggerIn .3s ease both; }
.stagger>*:nth-child(1){animation-delay:.04s;}.stagger>*:nth-child(2){animation-delay:.09s;}
.stagger>*:nth-child(3){animation-delay:.14s;}.stagger>*:nth-child(4){animation-delay:.19s;}
.stagger>*:nth-child(5){animation-delay:.24s;}.stagger>*:nth-child(6){animation-delay:.29s;}
.stagger>*:nth-child(7){animation-delay:.34s;}.stagger>*:nth-child(8){animation-delay:.39s;}
/* Dynamic pet color tokens */
.pf-body { border-color:var(--pet-col,var(--green)) !important; box-shadow:0 0 24px color-mix(in srgb,var(--pet-col,#00ff88) 40%,transparent) !important; }
.pet-aura { background:radial-gradient(circle,color-mix(in srgb,var(--pet-col,#00ff88) 20%,transparent) 0%,transparent 70%) !important; }
.pet-stage-bg { background:radial-gradient(ellipse at 50% 70%,color-mix(in srgb,var(--pet-col,#00ff88) 14%,transparent) 0%,transparent 70%) !important; }
.xp-fill { background:linear-gradient(90deg,var(--pet-col,var(--green)),var(--teal)) !important; }
.pet-lv-badge { background:linear-gradient(135deg,var(--pet-col,var(--green)),var(--teal)) !important; }
/* Level badge glow */
.pet-lv-badge { box-shadow:0 4px 18px color-mix(in srgb,var(--pet-col,#00ff88) 45%,transparent); }
/* Care button hover + accent colors */
.care-btn { transition:all .15s; }
.care-btn:hover { background:rgba(20,8,44,.92); border-color:rgba(255,255,255,.22); transform:translateY(-2px); box-shadow:0 6px 20px rgba(0,0,0,.4); }
.care-btn[data-accent="orange"] { border-color:rgba(255,136,0,.3); }
.care-btn[data-accent="orange"]:hover { border-color:rgba(255,136,0,.7); box-shadow:0 6px 20px rgba(255,136,0,.2); }
.care-btn[data-accent="red"] { border-color:rgba(255,68,85,.3); }
.care-btn[data-accent="red"]:hover { border-color:rgba(255,68,85,.7); box-shadow:0 6px 20px rgba(255,68,85,.2); }
.care-btn[data-accent="blue"] { border-color:rgba(68,136,255,.3); }
.care-btn[data-accent="blue"]:hover { border-color:rgba(68,136,255,.7); box-shadow:0 6px 20px rgba(68,136,255,.2); }
.care-btn[data-accent="purple"] { border-color:rgba(170,102,255,.3); }
.care-btn[data-accent="purple"]:hover { border-color:rgba(170,102,255,.7); box-shadow:0 6px 20px rgba(170,102,255,.2); }
.care-btn[data-accent="gold"] { border-color:rgba(255,204,0,.3); }
.care-btn[data-accent="gold"]:hover { border-color:rgba(255,204,0,.7); box-shadow:0 6px 20px rgba(255,204,0,.2); }
.care-btn[data-accent="green"] { border-color:rgba(0,255,136,.3); }
.care-btn[data-accent="green"]:hover { border-color:rgba(0,255,136,.7); box-shadow:0 6px 20px rgba(0,255,136,.2); }
.care-btn[data-accent="pink"] { border-color:rgba(255,51,119,.3); }
.care-btn[data-accent="pink"]:hover { border-color:rgba(255,51,119,.7); box-shadow:0 6px 20px rgba(255,51,119,.2); }
.care-btn[data-accent="teal"] { border-color:rgba(0,221,204,.3); }
.care-btn[data-accent="teal"]:hover { border-color:rgba(0,221,204,.7); box-shadow:0 6px 20px rgba(0,221,204,.2); }
/* Flash card stagger */
.video-card { animation:staggerIn .35s ease both; }
/* ══════════════════════
   🎮 GAMES VIEW
══════════════════════ */
#view-games { padding-top:calc(52px + var(--sat)); background:radial-gradient(ellipse at 50% 0%,rgba(68,136,255,.1) 0%,transparent 60%),var(--bg); }
.games-hdr { padding:16px; display:flex; align-items:center; justify-content:space-between; flex-shrink:0; background:linear-gradient(180deg,rgba(68,136,255,.06),transparent); }
.games-title { font-family:var(--ff-head); font-size:30px; font-weight:900; background:linear-gradient(135deg,#00ccff,var(--blue),var(--purple)); -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text; }
.game-tabs { display:flex; gap:8px; padding:0 14px 14px; flex-shrink:0; }
.gtab { padding:8px 18px; border-radius:20px; background:rgba(10,6,28,.8); border:1px solid rgba(255,255,255,.08); font-size:13px; font-weight:700; cursor:pointer; color:var(--t2); transition:all .15s; flex-shrink:0; font-family:var(--ff-head); letter-spacing:.2px; }
.gtab:active { transform:scale(.94); }
.gtab.on { background:linear-gradient(135deg,var(--blue),#2266cc); color:#fff; border-color:rgba(68,136,255,.5); box-shadow:0 4px 20px rgba(68,136,255,.35),0 0 0 1px rgba(68,136,255,.2); }

/* Game Card Container */
.game-panel { display:none; padding:0 14px; }
.game-panel.active { display:block; }

/* ── BATTLE GAME ── */
.battle-arena {
  background:linear-gradient(180deg,rgba(10,2,20,.98),rgba(4,1,10,.96)); border:1px solid rgba(255,51,119,.14); border-radius:24px;
  padding:20px 16px; margin-bottom:14px; position:relative; overflow:hidden;
  box-shadow:0 8px 40px rgba(0,0,0,.6),0 0 60px rgba(255,51,119,.04);
}
.battle-arena::before { content:''; position:absolute; inset:0; background:radial-gradient(ellipse at 50% 0%,rgba(255,51,119,.1) 0%,transparent 55%); pointer-events:none; }
.battle-fighters { display:flex; align-items:center; justify-content:space-between; margin-bottom:16px; }
.fighter { text-align:center; }
.fighter-em { font-size:72px; display:block; filter:drop-shadow(0 0 20px var(--pet-col,#00ff88)); animation:petbounce 2.4s ease-in-out infinite; }
.fighter.enemy .fighter-em { animation-direction:reverse; filter:drop-shadow(0 0 20px var(--pink)); }
.fighter-name { font-family:var(--ff-head); font-size:13px; font-weight:800; margin-top:6px; }
.fighter-lv { font-size:10px; color:var(--t3); }
.hp-wrap { margin-bottom:10px; }
.hp-label { display:flex; justify-content:space-between; font-size:10px; font-weight:700; color:var(--t3); margin-bottom:4px; }
.hp-track { height:10px; background:rgba(255,255,255,.06); border-radius:100px; overflow:hidden; }
.hp-fill { height:100%; border-radius:100px; transition:width .4s cubic-bezier(.34,1.56,.64,1); }
.hp-fill.you { background:linear-gradient(90deg,var(--green),var(--teal)); }
.hp-fill.enemy { background:linear-gradient(90deg,var(--red),var(--pink)); }
.vs-badge { width:44px; height:44px; border-radius:50%; background:linear-gradient(135deg,var(--pink),var(--purple)); display:flex; align-items:center; justify-content:center; font-family:var(--ff-head); font-size:14px; font-weight:900; color:#fff; box-shadow:0 0 20px rgba(255,51,119,.4); flex-shrink:0; }
.battle-moves { display:grid; grid-template-columns:1fr 1fr 1fr; gap:10px; margin-top:6px; }
.move-btn {
  background:linear-gradient(180deg,rgba(30,8,50,.95),rgba(14,3,24,.9)); border:1.5px solid rgba(255,51,119,.2); border-radius:16px;
  padding:14px 8px; text-align:center; cursor:pointer; transition:all .15s;
  box-shadow:0 4px 16px rgba(0,0,0,.4);
}
.move-btn:active { transform:scale(.88); box-shadow:0 0 20px rgba(255,51,119,.25); border-color:rgba(255,51,119,.5); }
.move-ico { font-size:28px; display:block; margin-bottom:5px; filter:drop-shadow(0 0 6px rgba(255,255,255,.2)); }
.move-name { font-size:11px; font-weight:800; font-family:var(--ff-head); }
.move-cost { font-size:9px; color:var(--t3); margin-top:2px; }
.battle-log { background:linear-gradient(180deg,rgba(10,2,20,.9),rgba(4,1,10,.85)); border:1px solid rgba(255,51,119,.1); border-radius:14px; padding:12px 14px; font-size:12px; color:var(--t2); line-height:1.6; margin-top:10px; min-height:44px; font-style:italic; }
@keyframes hitShake { 0%,100%{transform:translateX(0);}25%{transform:translateX(-10px);}75%{transform:translateX(10px);} }
.fighter.hit { animation:hitShake .25s ease; }

/* ── SPEED TAP GAME ── */
.speed-arena {
  position:relative; height:360px; background:linear-gradient(180deg,rgba(0,6,18,.98),rgba(0,2,10,.96)); border:1px solid rgba(0,255,136,.12);
  border-radius:24px; overflow:hidden; margin-bottom:14px; touch-action:none;
  box-shadow:0 8px 40px rgba(0,0,0,.6),0 0 40px rgba(0,255,136,.03);
}
.speed-arena-bg { position:absolute; inset:0; background:radial-gradient(ellipse at 50% 50%,rgba(0,255,136,.06) 0%,transparent 65%); }
.speed-hud { display:flex; justify-content:space-between; align-items:center; padding:12px 16px; }
.speed-score-big { font-family:var(--ff-head); font-size:48px; font-weight:900; color:var(--green); line-height:1; }
.speed-timer-ring { width:56px; height:56px; position:relative; }
.speed-tap-target {
  position:absolute; border-radius:50%; cursor:pointer; display:flex; align-items:center; justify-content:center;
  font-size:28px; border:3px solid; animation:targetPop .15s cubic-bezier(.34,1.56,.64,1) both;
  box-shadow:0 0 16px currentColor; transition:transform .1s;
}
.speed-tap-target:active { transform:scale(.7); }
@keyframes targetPop { from{transform:scale(0);}to{transform:scale(1);} }
@keyframes targetShrink { from{transform:scale(1);}to{transform:scale(0) rotate(180deg);opacity:0;} }
.target-timer { position:absolute; bottom:-6px; left:50%; transform:translateX(-50%); width:100%; height:3px; background:rgba(255,255,255,.2); border-radius:2px; overflow:hidden; }
.target-timer-fill { height:100%; background:currentColor; transition:none; }
.speed-start-btn { display:flex; align-items:center; justify-content:center; height:100%; }

/* ── MEMORY GAME ── */
.memory-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:8px; padding:14px; margin-bottom:14px; }
.mem-card {
  aspect-ratio:1; border-radius:14px; background:rgba(10,4,22,.9); border:2px solid rgba(255,255,255,.08);
  display:flex; align-items:center; justify-content:center; font-size:28px;
  cursor:pointer; transition:all .22s cubic-bezier(.34,1.56,.64,1);
  perspective:200px; user-select:none; box-shadow:0 4px 12px rgba(0,0,0,.4);
}
.mem-card.flipped { background:rgba(0,10,22,.95); border-color:var(--green); transform:rotateY(180deg); box-shadow:0 0 16px rgba(0,255,136,.2); }
.mem-card.matched { border-color:var(--gold); background:rgba(255,204,0,.06); animation:matchPop .35s cubic-bezier(.34,1.56,.64,1); box-shadow:0 0 20px rgba(255,204,0,.25); }
.mem-card.back { color:transparent; background:linear-gradient(135deg,rgba(30,10,60,.9),rgba(10,4,30,.95)); }
@keyframes matchPop { 0%{transform:scale(1);}50%{transform:scale(1.18);}100%{transform:scale(1);} }
.mem-stats { display:flex; justify-content:space-around; background:linear-gradient(180deg,rgba(0,4,22,.96),rgba(0,2,12,.9)); border:1px solid rgba(0,255,136,.1); border-radius:18px; padding:12px 16px; margin:0 14px 14px; box-shadow:0 4px 20px rgba(0,0,0,.4); }
.mem-stat { text-align:center; }
.mem-stat-v { font-family:var(--ff-head); font-size:24px; font-weight:900; }
.mem-stat-l { font-size:9px; color:var(--t3); text-transform:uppercase; letter-spacing:.8px; }

/* ══════════════════════
   📅 DAILY MISSIONS
══════════════════════ */
.missions-card {
  margin:0 16px 16px; background:linear-gradient(180deg,rgba(10,8,2,.97),rgba(4,3,0,.95)); border:1px solid rgba(255,204,0,.12);
  border-radius:20px; overflow:hidden; box-shadow:0 4px 24px rgba(0,0,0,.5);
}
.missions-hdr { display:flex; align-items:center; justify-content:space-between; padding:14px 16px 10px; background:rgba(255,204,0,.03); border-bottom:1px solid rgba(255,204,0,.08); }
.missions-title { font-size:11px; font-weight:900; color:var(--gold); text-transform:uppercase; letter-spacing:1.2px; font-family:var(--ff-head); }
.missions-refresh { font-size:10px; color:var(--t3); }
.mission-row { padding:10px 16px; border-top:1px solid rgba(255,255,255,.04); display:flex; align-items:center; gap:12px; cursor:pointer; transition:background .12s; }
.mission-row:active { background:rgba(255,255,255,.03); }
.mission-row.done { opacity:.45; }
.m-ico { font-size:24px; width:32px; text-align:center; flex-shrink:0; }
.m-info { flex:1; min-width:0; }
.m-name { font-size:13px; font-weight:700; }
.m-prog-wrap { height:5px; background:rgba(255,255,255,.06); border-radius:3px; margin-top:6px; overflow:hidden; }
.m-prog { height:100%; background:linear-gradient(90deg,var(--green),var(--teal)); border-radius:3px; transition:width .5s ease; box-shadow:0 0 6px rgba(0,255,136,.4); }
.m-rwd { font-size:12px; font-weight:900; color:var(--gold); flex-shrink:0; }
.mission-row.done .m-rwd::before { content:'✓ '; color:var(--green); }

/* ══════════════════════
   🎰 SPIN WHEEL
══════════════════════ */
.spin-wrap { display:flex; flex-direction:column; align-items:center; padding:20px; }
.spin-outer { position:relative; width:260px; height:260px; margin-bottom:20px; }
.spin-canvas { width:260px; height:260px; border-radius:50%; position:relative; overflow:hidden; border:4px solid rgba(255,255,255,.15); box-shadow:0 0 40px rgba(0,255,136,.2); transition:transform 3s cubic-bezier(.17,.67,.12,1); }
.spin-pointer { position:absolute; top:-12px; left:50%; transform:translateX(-50%); font-size:26px; z-index:10; filter:drop-shadow(0 2px 6px rgba(0,0,0,.8)); }
.spin-segment { position:absolute; width:50%; height:50%; transform-origin:100% 100%; display:flex; align-items:center; justify-content:flex-start; padding:18px 0 0 10px; font-size:20px; }
.spin-won { font-family:var(--ff-head); font-size:22px; font-weight:900; color:var(--green); text-align:center; margin-bottom:16px; }

/* ══════════════════════
   ⚡ STORIES
══════════════════════ */
.stories-bar { display:flex; gap:10px; overflow-x:auto; scrollbar-width:none; padding:8px 14px 4px; }
.stories-bar::-webkit-scrollbar { display:none; }
.story-item { display:flex; flex-direction:column; align-items:center; gap:4px; cursor:pointer; flex-shrink:0; }
.story-ring-wrap { position:relative; }
.story-ring {
  width:58px; height:58px; border-radius:50%; padding:3px;
  background:conic-gradient(var(--pink),var(--purple),var(--blue),var(--pink));
  display:flex; align-items:center; justify-content:center;
  transition:transform .15s;
}
.story-ring:active { transform:scale(.9); }
.story-ring.seen { background:conic-gradient(rgba(255,255,255,.12),rgba(255,255,255,.12)); }
.story-ring.add-btn { background:rgba(10,4,22,.8); border:2px dashed rgba(255,255,255,.18); }
.story-inner { width:50px; height:50px; border-radius:50%; background:rgba(10,4,22,.85); display:flex; align-items:center; justify-content:center; font-size:24px; }
.story-name { font-size:9px; color:rgba(255,255,255,.6); max-width:62px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; text-align:center; }
/* Story overlay */
.story-overlay { position:fixed; inset:0; z-index:950; background:#000; display:flex; flex-direction:column; transform:translateY(100%); transition:transform .28s cubic-bezier(.32,.72,0,1); }
.story-overlay.open { transform:translateY(0); }
.story-ov-bar { display:flex; gap:3px; padding:12px 12px 8px; }
.story-seg { flex:1; height:3px; background:rgba(255,255,255,.25); border-radius:2px; overflow:hidden; }
.story-seg-fill { height:100%; background:#fff; width:0%; transition:width linear; }
.story-ov-hdr { display:flex; align-items:center; gap:10px; padding:0 14px 10px; }
.story-ov-content { flex:1; display:flex; align-items:center; justify-content:center; font-size:100px; position:relative; }
.story-close { position:absolute; top:14px; right:14px; width:34px; height:34px; background:rgba(0,0,0,.5); border-radius:50%; display:flex; align-items:center; justify-content:center; cursor:pointer; font-size:16px; z-index:10; }

/* ══════════════════════
   🏰 TERRITORY ZONES
══════════════════════ */
.world-view { display:none; flex-direction:column; height:100%; }
.world-view.active { display:flex; }
.zone-grid { display:grid; grid-template-columns:repeat(5,1fr); gap:4px; padding:10px 12px; flex:1; }
.zone { aspect-ratio:1; border-radius:10px; display:flex; align-items:center; justify-content:center; font-size:18px; cursor:pointer; transition:all .15s; position:relative; border:2px solid transparent; }
.zone:active { transform:scale(.88); }
.zone.mine { border-color:var(--pet-col,var(--green)) !important; box-shadow:0 0 12px color-mix(in srgb,var(--pet-col,#00ff88) 50%,transparent); }
.zone.friend { opacity:.75; }
.zone.unclaimed { background:rgba(10,4,22,.8); border-color:rgba(255,255,255,.06); }
.zone-lv { position:absolute; bottom:-2px; right:-2px; background:rgba(0,0,0,.8); border-radius:4px; font-size:8px; font-weight:800; padding:1px 4px; }
.world-hud { display:flex; align-items:center; justify-content:space-between; padding:10px 14px; background:linear-gradient(180deg,rgba(6,2,16,.98),rgba(2,1,8,.97)); border-top:1px solid rgba(255,255,255,.05); flex-shrink:0; }

/* ══════════════════════
   🎯 SEASON PASS
══════════════════════ */
.sp-card { margin:0 16px 14px; background:linear-gradient(135deg,rgba(170,102,255,.08),rgba(68,136,255,.05)); border:1px solid rgba(170,102,255,.25); border-radius:20px; padding:16px; overflow:hidden; position:relative; }
.sp-card::before { content:'SEASON 1'; position:absolute; right:16px; top:12px; font-size:9px; font-weight:800; color:rgba(170,102,255,.6); letter-spacing:2px; }
.sp-track { display:flex; gap:0; margin:12px 0 6px; }
.sp-node { width:32px; height:32px; border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:14px; border:2px solid; flex-shrink:0; position:relative; cursor:pointer; transition:all .15s; }
.sp-node:active { transform:scale(.88); }
.sp-node.done { background:var(--purple); border-color:var(--purple); box-shadow:0 0 12px rgba(170,102,255,.5); }
.sp-node.current { background:rgba(170,102,255,.2); border-color:var(--purple); animation:spPulse 1.5s ease-in-out infinite; }
.sp-node.locked { background:rgba(10,4,22,.8); border-color:rgba(255,255,255,.08); opacity:.45; }
@keyframes spPulse { 0%,100%{box-shadow:0 0 8px rgba(170,102,255,.3);}50%{box-shadow:0 0 20px rgba(170,102,255,.7);} }
.sp-line { flex:1; height:2px; background:rgba(255,255,255,.06); align-self:center; }
.sp-line.done { background:linear-gradient(90deg,var(--purple),var(--blue)); }
.sp-label { font-size:10px; color:var(--t3); }

/* VIEW BACKGROUNDS */
#view-pet   { background:radial-gradient(ellipse at 50% 0%,rgba(0,255,136,.05) 0%,transparent 50%),var(--bg); }
#view-flash { background:var(--bg); }
#view-lb    { background:radial-gradient(ellipse at 50% 0%,rgba(255,204,0,.05) 0%,transparent 50%),var(--bg); }
#view-profile { background:var(--bg); }
#view-map   { background:var(--bg); }
#view-uppdrag { background:radial-gradient(ellipse at 80% 0%,rgba(255,204,0,.04) 0%,transparent 50%),var(--bg); }

/* GLASS effect */
.glass { background:rgba(255,255,255,.04) !important; backdrop-filter:blur(16px); }

/* ══ ASTRAL RIFT ══ */
.ar { position:fixed;inset:0;z-index:850;background:#000;display:flex;flex-direction:column;transform:translateY(100%);transition:transform .38s cubic-bezier(.32,.72,0,1);overflow:hidden; }
.ar.open { transform:translateY(0); }
.ar-canvas { position:absolute;inset:0;width:100%;height:100%;z-index:0; }
.ar-hdr { height:calc(56px + var(--sat));padding-top:var(--sat);display:flex;align-items:center;justify-content:space-between;padding-left:14px;padding-right:14px;flex-shrink:0;position:relative;z-index:2; }
.ar-title { font-family:var(--ff-head);font-size:19px;font-weight:900;background:linear-gradient(135deg,#cc88ff,#4488ff,#00ddcc);-webkit-background-clip:text;-webkit-text-fill-color:transparent;filter:drop-shadow(0 0 14px rgba(170,102,255,.45)); }
.ar-back { background:none;border:none;color:rgba(255,255,255,.45);font-size:24px;cursor:pointer;padding:8px;line-height:1; }
.ar-body { flex:1;overflow-y:auto;scrollbar-width:none;padding:0 16px calc(30px + var(--sab));display:flex;flex-direction:column;align-items:center;position:relative;z-index:2; }
.ar-body::-webkit-scrollbar { display:none; }
.ar-pet { font-size:94px;margin:8px 0 4px;animation:arFloat 3s ease-in-out infinite;filter:drop-shadow(0 0 30px rgba(170,102,255,.55)); }
@keyframes arFloat { 0%,100%{transform:translateY(0) rotate(-3deg);}50%{transform:translateY(-18px) rotate(3deg);} }
.ar-sub { font-size:10px;color:rgba(170,102,255,.6);font-family:var(--ff-head);letter-spacing:2.5px;text-transform:uppercase;margin-bottom:18px;text-align:center; }
.ar-bless { width:100%;background:linear-gradient(160deg,rgba(40,8,80,.88),rgba(16,4,40,.94));border:1px solid rgba(170,102,255,.28);border-radius:20px;padding:14px 16px;margin-bottom:14px;box-shadow:0 0 32px rgba(170,102,255,.07),inset 0 1px 0 rgba(255,255,255,.05); }
.ar-bless-lbl { font-size:9px;font-family:var(--ff-head);font-weight:900;color:rgba(170,102,255,.55);letter-spacing:1.5px;text-transform:uppercase;margin-bottom:8px; }
.ar-bless-txt { font-size:13px;font-weight:800;color:#cc88ff;text-shadow:0 0 10px rgba(170,102,255,.4);line-height:1.55; }
.ar-bless-empty { font-size:13px;color:rgba(255,255,255,.28);font-style:italic; }
.ar-acts { display:flex;flex-direction:column;gap:10px;width:100%; }
.ar-act { background:linear-gradient(135deg,rgba(28,6,58,.92),rgba(12,2,28,.95));border:1px solid rgba(170,102,255,.18);border-radius:18px;padding:15px 17px;cursor:pointer;transition:all .18s;display:flex;align-items:center;gap:14px; }
.ar-act:active { transform:scale(.97);border-color:rgba(170,102,255,.5);box-shadow:0 0 22px rgba(170,102,255,.14); }
.ar-act.cooling { opacity:.55;cursor:default;border-color:rgba(255,255,255,.07); }
.ar-act-ico { font-size:34px;flex-shrink:0; }
.ar-act-name { font-family:var(--ff-head);font-size:14px;font-weight:900;color:#fff;margin-bottom:2px; }
.ar-act-desc { font-size:11px;color:rgba(255,255,255,.42); }
.ar-act-cd { font-size:10px;font-weight:700;margin-top:3px; }
.ar-reveal { position:absolute;inset:0;z-index:10;background:rgba(0,0,0,.88);backdrop-filter:blur(22px);display:flex;align-items:center;justify-content:center;opacity:0;pointer-events:none;transition:opacity .28s; }
.ar-reveal.show { opacity:1;pointer-events:all; }
.ar-card { width:290px;text-align:center;background:linear-gradient(160deg,rgba(56,10,110,.95),rgba(20,4,50,.97));border:2px solid rgba(170,102,255,.45);border-radius:28px;padding:32px 24px 28px;box-shadow:0 0 80px rgba(170,102,255,.22),0 40px 80px rgba(0,0,0,.85);animation:arCardIn .42s cubic-bezier(.34,1.56,.64,1) both; }
@keyframes arCardIn { from{transform:scale(.55) translateY(50px) rotate(-10deg);opacity:0;}to{transform:none;opacity:1;} }
