.drhnt-title{font:700 20px var(--ff-head);background:linear-gradient(90deg,#8866ff,#cc88ff,#88aaff,#8866ff);background-size:300% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;animation:drhntShim 5s linear infinite}
@keyframes drhntShim{0%{background-position:0%}100%{background-position:300%}}
.drhnt-scroll{flex:1;overflow-y:auto;padding:10px 14px 28px}
