.drhnt-dream-icon{font-size:52px;margin-bottom:8px;display:block}
.drhnt-dream-name{font:800 16px var(--ff-head);color:rgba(200,180,255,.9);margin-bottom:3px}
.drhnt-dream-desc{font:600 9px var(--ff-body);color:rgba(160,140,220,.4);margin-bottom:8px}
.drhnt-catch-btn{background:linear-gradient(135deg,#100028,#200050);border:2px solid rgba(136,102,255,.4);border-radius:14px;padding:11px;font:900 12px var(--ff-head);color:#aa88ff;cursor:pointer;width:100%}
