.drhnt-dreams-caught{display:flex;flex-direction:column;gap:5px;margin-top:10px}
.drhnt-caught{background:rgba(136,102,255,.05);border:1px solid rgba(136,102,255,.15);border-radius:10px;padding:8px 12px;display:flex;align-items:center;gap:8px}
.drhnt-caught-icon{font-size:22px;flex-shrink:0}
.drhnt-caught-info{flex:1}
.drhnt-caught-name{font:700 9px var(--ff-head);color:rgba(200,180,255,.7)}
.drhnt-caught-eff{font:600 7px var(--ff-body);color:rgba(160,140,220,.4)}
.drhnt-caught-use{background:rgba(136,102,255,.1);border:1px solid rgba(136,102,255,.25);border-radius:7px;padding:4px 9px;font:700 7px var(--ff-head);color:#aa88ff;cursor:pointer;flex-shrink:0}
.drhnt-caught-use:disabled{opacity:.3;cursor:default}
.drhnt-dreamcount{font:700 9px var(--ff-head);color:rgba(136,102,255,.4);text-align:center;margin-bottom:6px}

/* ══ TOWER ASCENSION ══ */
.towr-panel{position:fixed;inset:0;background:#040208;z-index:1121;display:none;flex-direction:column;overflow:hidden}
.towr-panel.open{display:flex}
