.towr-climb-btn{background:linear-gradient(135deg,#1a0030,#3a0060);border:2px solid rgba(170,68,255,.4);border-radius:14px;padding:11px;font:900 12px var(--ff-head);color:#cc88ff;cursor:pointer;width:100%;margin-bottom:8px}
