.towr-best{font:600 8px var(--ff-body);color:rgba(170,100,255,.35);text-align:center;margin-bottom:8px}
.towr-milestone-lbl{font:700 8px var(--ff-head);color:rgba(170,100,255,.35);letter-spacing:1px;margin-bottom:6px}
.towr-milestones{display:flex;flex-direction:column;gap:4px}
.towr-ms{background:rgba(170,68,255,.04);border:1px solid rgba(170,68,255,.1);border-radius:10px;padding:7px 12px;display:flex;align-items:center;gap:8px}
