.towr-ms-floor{font:700 11px var(--ff-head);color:rgba(200,150,255,.7);flex-shrink:0;width:50px}
.towr-ms-rew{flex:1;font:600 8px var(--ff-body);color:rgba(170,120,220,.4)}

