.cbnk-dep-field{flex:1;background:rgba(68,255,136,.06);border:1.5px solid rgba(68,255,136,.2);border-radius:10px;padding:8px 12px;font:700 12px var(--ff-head);color:#44ffaa;outline:none}
.cbnk-dep-btn{background:rgba(68,255,136,.1);border:1.5px solid rgba(68,255,136,.3);border-radius:10px;padding:8px 14px;font:700 9px var(--ff-head);color:#44ffaa;cursor:pointer}

