/* ══ BESTIARY 2 ══ */
.bes-panel{position:fixed;inset:0;background:#020a04;z-index:1067;display:none;flex-direction:column;overflow:hidden}
.bes-panel.open{display:flex}
.bes-header{display:flex;align-items:center;justify-content:space-between;padding:var(--sat) 16px 12px;background:linear-gradient(135deg,#030e06,#020a04)}
.bes-title{font:700 20px var(--ff-head);background:linear-gradient(90deg,#ff8844,#ffcc22,#88ff44,#ff8844);background-size:300% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;animation:besShim 2.5s linear infinite}
@keyframes besShim{0%{background-position:0%}100%{background-position:300%}}
.bes-scroll{flex:1;overflow-y:auto;padding:10px 14px 28px}
/* Progress bar */
.bes-progress{background:rgba(255,200,0,.04);border:1.5px solid rgba(255,200,0,.15);border-radius:14px;padding:12px 14px;margin-bottom:12px;display:flex;align-items:center;gap:12px}
.bes-prog-body{flex:1}
.bes-prog-bar{background:rgba(255,255,255,.06);border-radius:5px;height:7px;overflow:hidden;margin-bottom:3px}
.bes-prog-fill{height:100%;background:linear-gradient(90deg,#ff8844,#ffcc22);border-radius:5px;transition:width .4s}
.bes-prog-txt{font:600 8px var(--ff-body);color:rgba(255,200,0,.5)}
.bes-total{text-align:center}
.bes-total-v{font:900 24px var(--ff-head);color:#ffcc22}
.bes-total-l{font:600 7px var(--ff-body);color:rgba(255,200,0,.4)}
/* Monster cards grid */
.bes-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-bottom:10px}
.bes-card{border-radius:14px;padding:10px 6px;text-align:center;border:1.5px solid rgba(255,255,255,.08);background:rgba(255,255,255,.02);cursor:pointer;transition:all .15s;position:relative}
.bes-card.caught{border-color:var(--mc)}
.bes-card.locked{filter:grayscale(0.9);opacity:.35}
.bes-card-icon{font-size:26px;margin-bottom:3px}
.bes-card-name{font:700 7px var(--ff-head);color:#fff;word-break:break-word;line-height:1.1;margin-bottom:2px}
.bes-card-rarity{font:600 6px var(--ff-body);color:var(--mc);margin-bottom:2px}
.bes-card-power{font:700 8px var(--ff-head);color:rgba(255,255,255,.5)}
.bes-card-badge{position:absolute;top:4px;right:4px;font-size:10px}
/* Hunt modal */
.bes-hunt-wrap{background:rgba(255,255,255,.03);border:2px solid rgba(255,136,68,.2);border-radius:18px;padding:14px;margin-bottom:10px}
.bes-hunt-lbl{font:700 8px var(--ff-head);color:rgba(255,136,68,.5);letter-spacing:1px;margin-bottom:6px}
.bes-hunt-info{font:600 9px var(--ff-body);color:rgba(255,255,255,.4);margin-bottom:8px}
.bes-hunt-btn{background:linear-gradient(135deg,#2a0e00,#5a2000);border:1.5px solid rgba(255,136,68,.4);border-radius:12px;padding:10px;font:800 11px var(--ff-head);color:#fff;cursor:pointer;width:100%}
.bes-hunt-btn:disabled{opacity:.3;cursor:default}
.bes-info{font:600 9px var(--ff-body);color:rgba(255,255,255,.3);text-align:center}

/* ══ GUILD HALL ══ */
.guild-panel{position:fixed;inset:0;background:#030208;z-index:1066;display:none;flex-direction:column;overflow:hidden}
