.dng-hp-bar{height:100%;border-radius:6px;background:linear-gradient(90deg,#ff4444,#ff8800);transition:width .3s}
/* Room display */
.dng-room{background:rgba(255,255,255,.02);border:2px solid rgba(255,68,68,.15);border-radius:18px;padding:14px;margin-bottom:8px;text-align:center;min-height:110px;display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative}
