.dng-room-name{font:800 14px var(--ff-head);color:#fff;margin-bottom:4px}
.dng-room-desc{font:600 9px var(--ff-body);color:rgba(255,255,255,.4)}
.dng-enemy-hp{display:flex;flex-direction:column;align-items:center;gap:3px;margin-top:6px;width:100%}
