.dng-act{background:rgba(255,255,255,.05);border:1.5px solid rgba(255,255,255,.1);border-radius:12px;padding:10px;font:800 11px var(--ff-head);color:#fff;cursor:pointer;-webkit-tap-highlight-color:transparent}
.dng-act:active{transform:scale(.95)}
.dng-act.attack{background:rgba(255,68,68,.1);border-color:rgba(255,68,68,.3);color:#ff6666}
.dng-act.special{background:rgba(255,200,0,.08);border-color:rgba(255,200,0,.25);color:#ffcc00}
.dng-act.run{background:rgba(68,255,136,.08);border-color:rgba(68,255,136,.2);color:#44ff88}
.dng-act.item{background:rgba(68,136,255,.08);border-color:rgba(68,136,255,.2);color:#4488ff}
