/* Result overlay */
.dng-over{display:none;flex-direction:column;align-items:center;gap:5px;padding:12px;background:rgba(0,0,0,.8);border:2px solid rgba(255,200,0,.3);border-radius:16px;margin-bottom:8px;text-align:center}
