.dng-over-icon{font-size:36px}
.dng-over-title{font:900 18px var(--ff-head);color:#ffcc00}
.dng-over-rw{font:700 12px var(--ff-head);color:#44ff88}
.dng-start-btn{width:100%;background:linear-gradient(135deg,#300808,#600000);border:none;border-radius:14px;padding:13px;font:900 14px var(--ff-head);color:#fff;cursor:pointer;margin-bottom:8px}
.dng-start-btn:disabled{opacity:.4;cursor:default;background:rgba(255,255,255,.06)}
.dng-info{font:600 9px var(--ff-body);color:rgba(255,255,255,.3);text-align:center}

