/* HUD */
.tmap-hud{display:flex;gap:8px;margin-bottom:10px}
.tmap-hud-box{flex:1;background:rgba(255,255,255,.02);border:1px solid rgba(200,150,0,.1);border-radius:10px;padding:7px;text-align:center}
.tmap-hud-v{font:900 15px var(--ff-head);color:#cc8800}
.tmap-hud-l{font:500 7px var(--ff-body);color:rgba(255,255,255,.3)}
/* Map */
.tmap-map-box{background:linear-gradient(180deg,rgba(40,30,0,.6),rgba(20,15,0,.4));border:2px solid rgba(200,150,0,.2);border-radius:18px;padding:12px;margin-bottom:12px}
.tmap-map-lbl{font:700 8px var(--ff-head);color:rgba(200,150,0,.4);letter-spacing:1px;text-align:center;margin-bottom:8px}
.tmap-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;max-width:320px;margin:0 auto}
.tmap-cell{aspect-ratio:1;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:22px;cursor:pointer;position:relative;border:1px solid rgba(255,255,255,.06);transition:all .2s;user-select:none}
.tmap-cell.fog{background:rgba(255,255,255,.04);filter:blur(1px)}
.tmap-cell.fog::after{content:'?';position:absolute;font:700 12px var(--ff-head);color:rgba(255,255,255,.2)}
.tmap-cell.revealed{cursor:default}
.tmap-cell.treasure{border-color:rgba(255,200,0,.35);background:rgba(255,200,0,.06)}
.tmap-cell.empty{opacity:.4;cursor:default}
.tmap-cell:not(.revealed):not(.fog):hover{border-color:rgba(255,200,0,.3);transform:scale(1.05)}
.tmap-cell.dig-anim{animation:tmapDig .3s ease}
@keyframes tmapDig{0%{transform:scale(1)}50%{transform:scale(1.2)}100%{transform:scale(1)}}
/* Result flash */
.tmap-flash{text-align:center;font:700 11px var(--ff-head);color:#ffcc00;min-height:24px;margin-bottom:8px}
/* Legend */
.tmap-legend{display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-bottom:10px}
.tmap-leg-item{font:600 8px var(--ff-body);color:rgba(255,255,255,.4);display:flex;align-items:center;gap:3px}
/* Completion */
.tmap-complete-btn{width:100%;background:linear-gradient(135deg,#332200,#886600);border:none;border-radius:14px;padding:12px;font:900 12px var(--ff-head);color:#fff;cursor:pointer;margin-bottom:8px;box-shadow:0 0 14px rgba(200,150,0,.2)}
.tmap-complete-btn:disabled{opacity:.3;cursor:default;background:rgba(255,255,255,.06);box-shadow:none}
/* Stats */
.tmap-stats{display:flex;gap:8px;margin-bottom:10px}
.tmap-stat{flex:1;background:rgba(255,255,255,.02);border:1px solid rgba(200,150,0,.08);border-radius:10px;padding:7px;text-align:center}
.tmap-stat-v{font:900 14px var(--ff-head);color:#aa7700}
.tmap-stat-l{font:500 7px var(--ff-body);color:rgba(255,255,255,.3)}
.tmap-info{font:600 9px var(--ff-body);color:rgba(255,255,255,.3);text-align:center}

/* ══ WORD SCRAMBLE ══ */
.wscr-panel{position:fixed;inset:0;background:#010205;z-index:1023;display:none;flex-direction:column;overflow:hidden}
.wscr-panel.open{display:flex}
.wscr-header{display:flex;align-items:center;justify-content:space-between;padding:var(--sat) 16px 12px;background:linear-gradient(135deg,#030818,#010205)}
.wscr-title{font:700 20px var(--ff-head);background:linear-gradient(90deg,#44aaff,#aa88ff,#ff88aa,#44aaff);background-size:300% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;animation:wscrShim 3s linear infinite}
@keyframes wscrShim{0%{background-position:0%}100%{background-position:300%}}
.wscr-scroll{flex:1;overflow-y:auto;padding:10px 14px 28px}
/* HUD */
.wscr-hud{display:flex;gap:8px;margin-bottom:10px}
.wscr-hud-box{flex:1;background:rgba(255,255,255,.02);border:1px solid rgba(100,170,255,.12);border-radius:10px;padding:7px;text-align:center}
.wscr-hud-v{font:900 16px var(--ff-head);color:#44aaff}
.wscr-hud-l{font:500 7px var(--ff-body);color:rgba(255,255,255,.3)}
/* Timer */
.wscr-timer-bar{background:rgba(255,255,255,.06);border-radius:20px;height:8px;margin-bottom:10px;overflow:hidden}
.wscr-timer-fill{height:100%;background:linear-gradient(90deg,#44aaff,#aa66ff);border-radius:20px;transition:width .3s linear}
.wscr-timer-fill.warn{background:linear-gradient(90deg,#ff8800,#ff3300)}
/* Animal display */
.wscr-animal{text-align:center;margin-bottom:14px}
.wscr-animal-emoji{font-size:56px;display:block;margin-bottom:4px}
.wscr-animal-hint{font:600 9px var(--ff-body);color:rgba(255,255,255,.3)}
/* Answer area */
.wscr-answer-area{display:flex;justify-content:center;gap:6px;flex-wrap:wrap;margin-bottom:12px;min-height:54px;background:rgba(255,255,255,.02);border:1.5px dashed rgba(100,170,255,.2);border-radius:14px;padding:10px 8px;align-items:center}
.wscr-letter{width:44px;height:44px;background:rgba(255,255,255,.08);border:1.5px solid rgba(255,255,255,.15);border-radius:10px;display:flex;align-items:center;justify-content:center;font:900 18px var(--ff-head);color:#fff;cursor:pointer;transition:all .15s;user-select:none}
.wscr-letter:active{transform:scale(.9)}
.wscr-letter.answer{background:rgba(100,170,255,.15);border-color:rgba(100,170,255,.4);color:#88ccff}
.wscr-letter.correct{background:rgba(68,255,136,.15);border-color:rgba(68,255,136,.4);color:#44ff88}
.wscr-letter.wrong{background:rgba(255,50,50,.15);border-color:rgba(255,50,50,.3);color:#ff4444;animation:wscrShake .3s ease}
@keyframes wscrShake{0%,100%{transform:translateX(0)}25%{transform:translateX(-4px)}75%{transform:translateX(4px)}}
/* Scramble pool */
.wscr-pool-lbl{font:700 7px var(--ff-head);color:rgba(255,255,255,.3);letter-spacing:1px;text-align:center;margin-bottom:6px}
.wscr-pool{display:flex;justify-content:center;gap:6px;flex-wrap:wrap;margin-bottom:14px;min-height:54px;padding:8px}
/* Buttons */
.wscr-btns{display:flex;gap:8px;margin-bottom:10px}
.wscr-clear-btn{flex:1;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:10px;font:800 10px var(--ff-head);color:rgba(255,255,255,.5);cursor:pointer}
.wscr-skip-btn{flex:1;background:rgba(255,100,100,.08);border:1px solid rgba(255,100,100,.15);border-radius:12px;padding:10px;font:800 10px var(--ff-head);color:rgba(255,100,100,.6);cursor:pointer}
.wscr-start-btn{width:100%;background:linear-gradient(135deg,#001133,#003399);border:none;border-radius:14px;padding:13px;font:900 13px var(--ff-head);color:#fff;cursor:pointer;margin-bottom:8px;box-shadow:0 0 16px rgba(50,100,255,.2)}
.wscr-start-btn:disabled{opacity:.3;cursor:default;background:rgba(255,255,255,.06);box-shadow:none}
/* Message */
.wscr-msg{text-align:center;font:700 12px var(--ff-head);color:#ffcc00;min-height:26px;margin-bottom:6px}
/* Stats */
.wscr-stats{display:flex;gap:8px;margin-bottom:10px}
.wscr-stat{flex:1;background:rgba(255,255,255,.02);border:1px solid rgba(100,150,255,.1);border-radius:10px;padding:7px;text-align:center}
.wscr-stat-v{font:900 14px var(--ff-head);color:#6699ff}
.wscr-stat-l{font:500 7px var(--ff-body);color:rgba(255,255,255,.3)}
.wscr-info{font:600 9px var(--ff-body);color:rgba(255,255,255,.3);text-align:center}

/* ══ SLOT MACHINE ══ */
.slot-panel{position:fixed;inset:0;background:#020100;z-index:1022;display:none;flex-direction:column;overflow:hidden}
.slot-panel.open{display:flex}
.slot-header{display:flex;align-items:center;justify-content:space-between;padding:var(--sat) 16px 12px;background:linear-gradient(135deg,#150a00,#020100)}
.slot-title{font:700 20px var(--ff-head);background:linear-gradient(90deg,#ff4400,#ffcc00,#ff8800,#ff4400);background-size:300% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;animation:slotShim 1.5s linear infinite}
@keyframes slotShim{0%{background-position:0%}100%{background-position:300%}}
.slot-scroll{flex:1;overflow-y:auto;padding:10px 14px 28px}
/* Machine */
.slot-machine{background:linear-gradient(180deg,#1a0800,#0a0300);border:3px solid rgba(255,150,0,.3);border-radius:22px;padding:16px;margin-bottom:12px;box-shadow:0 0 30px rgba(255,100,0,.1),inset 0 2px 0 rgba(255,200,100,.1)}
.slot-machine-top{text-align:center;margin-bottom:14px}
.slot-lights{display:flex;justify-content:center;gap:6px;margin-bottom:8px}
.slot-light{width:8px;height:8px;border-radius:50%;background:#ff4400;animation:slotLightBlink var(--d,0.5s) ease-in-out infinite alternate;opacity:.8}
@keyframes slotLightBlink{0%{opacity:.3}100%{opacity:1}}
.slot-balance{font:900 20px var(--ff-head);color:#ffcc00;text-shadow:0 0 10px rgba(255,200,0,.4)}
.slot-balance-lbl{font:600 7px var(--ff-body);color:rgba(255,200,100,.5)}
/* Reels */
.slot-reels{display:flex;gap:8px;justify-content:center;margin-bottom:14px;position:relative}
.slot-reel-wrap{width:80px;height:90px;overflow:hidden;border-radius:12px;border:2px solid rgba(255,150,0,.25);background:rgba(0,0,0,.4);position:relative}
.slot-reel-wrap::before,.slot-reel-wrap::after{content:'';position:absolute;left:0;right:0;height:20px;z-index:2;pointer-events:none}
.slot-reel-wrap::before{top:0;background:linear-gradient(180deg,rgba(10,3,0,.9),transparent)}
.slot-reel-wrap::after{bottom:0;background:linear-gradient(0deg,rgba(10,3,0,.9),transparent)}
.slot-win-line{position:absolute;left:0;right:0;top:50%;transform:translateY(-50%);height:2px;background:rgba(255,200,0,.3);z-index:1;pointer-events:none}
.slot-reel{display:flex;flex-direction:column;align-items:center;transition:transform .7s cubic-bezier(.15,.6,.3,1);will-change:transform}
.slot-reel.spinning{transition:none;animation:slotSpin .1s linear infinite}
@keyframes slotSpin{0%{transform:translateY(0)}100%{transform:translateY(-90px)}}
.slot-sym{width:80px;height:90px;display:flex;align-items:center;justify-content:center;font-size:44px;flex-shrink:0;line-height:1}
/* Bet */
.slot-bet-row{display:flex;align-items:center;gap:6px;justify-content:center;margin-bottom:10px}
.slot-bet-lbl{font:700 9px var(--ff-head);color:rgba(255,200,100,.6)}
.slot-bet-btn{background:rgba(255,150,0,.1);border:1px solid rgba(255,150,0,.2);border-radius:8px;padding:5px 10px;font:800 10px var(--ff-head);color:#ff8800;cursor:pointer}
.slot-bet-btn.active{background:rgba(255,150,0,.25);border-color:rgba(255,150,0,.6);color:#ffcc00}
/* Spin buttons */
.slot-spin-btn{width:100%;background:linear-gradient(135deg,#550000,#cc3300);border:none;border-radius:14px;padding:14px;font:900 15px var(--ff-head);color:#fff;cursor:pointer;margin-bottom:8px;box-shadow:0 4px 20px rgba(255,80,0,.3);letter-spacing:1px}
.slot-spin-btn:disabled{opacity:.3;cursor:default;background:rgba(255,255,255,.06);box-shadow:none}
.slot-free-btn{width:100%;background:rgba(255,200,0,.08);border:1px solid rgba(255,200,0,.2);border-radius:12px;padding:10px;font:800 11px var(--ff-head);color:#ffcc00;cursor:pointer;margin-bottom:10px}
.slot-free-btn:disabled{opacity:.3;cursor:default}
/* Result */
.slot-result{text-align:center;min-height:36px;font:900 13px var(--ff-head);color:#ffcc00;margin-bottom:8px}
/* Stats */
.slot-stats{display:flex;gap:8px;margin-bottom:10px}
.slot-stat{flex:1;background:rgba(255,255,255,.02);border:1px solid rgba(255,100,0,.1);border-radius:10px;padding:7px;text-align:center}
.slot-stat-v{font:900 14px var(--ff-head);color:#ff6600}
.slot-stat-l{font:500 7px var(--ff-body);color:rgba(255,255,255,.3)}
/* Paytable */
.slot-pay{background:rgba(255,255,255,.02);border:1px solid rgba(255,100,0,.08);border-radius:12px;padding:10px;margin-bottom:10px}
.slot-pay-lbl{font:700 7px var(--ff-head);color:rgba(255,100,0,.4);letter-spacing:1px;margin-bottom:6px}
.slot-pay-grid{display:grid;grid-template-columns:1fr 1fr;gap:4px}
.slot-pay-row{display:flex;justify-content:space-between;font:700 9px var(--ff-body);color:rgba(255,255,255,.5)}
.slot-pay-mult{color:#ffcc00}
.slot-info{font:600 9px var(--ff-body);color:rgba(255,255,255,.3);text-align:center}

/* ══ RAID BOSS ══ */
.raid-panel{position:fixed;inset:0;background:#010000;z-index:1020;display:none;flex-direction:column;overflow:hidden}
.raid-panel.open{display:flex}
.raid-header{display:flex;align-items:center;justify-content:space-between;padding:var(--sat) 16px 12px;background:linear-gradient(135deg,#200000,#010000)}
.raid-title{font:700 20px var(--ff-head);background:linear-gradient(90deg,#ff0000,#ff6600,#ffcc00,#ff0000);background-size:300% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;animation:raidShim 1.5s linear infinite}
@keyframes raidShim{0%{background-position:0%}100%{background-position:300%}}
.raid-scroll{flex:1;overflow-y:auto;padding:10px 14px 28px}
/* Boss arena */
.raid-arena{background:radial-gradient(ellipse at 50% 30%,rgba(255,0,0,.08),rgba(0,0,0,0));border:2px solid rgba(255,0,0,.2);border-radius:22px;padding:16px;margin-bottom:12px;text-align:center}
.raid-boss-emoji{font-size:72px;display:block;margin-bottom:4px;animation:raidBreath 3s ease-in-out infinite}
@keyframes raidBreath{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}
.raid-boss-emoji.hurt{animation:raidHurt .3s ease}
@keyframes raidHurt{0%,100%{transform:scale(1)}50%{transform:scale(.9) translateX(5px)}}
.raid-boss-name{font:900 18px var(--ff-head);color:#fff;margin-bottom:3px}
.raid-boss-week{font:600 8px var(--ff-body);color:rgba(255,0,0,.5);margin-bottom:10px}
.raid-hp-bar{background:rgba(255,255,255,.06);border-radius:20px;height:16px;overflow:hidden;border:1px solid rgba(255,0,0,.2);margin-bottom:6px}
.raid-hp-fill{height:100%;background:linear-gradient(90deg,#ff4400,#ff0000);border-radius:20px;transition:width .5s ease}
.raid-hp-fill.low{background:linear-gradient(90deg,#880000,#440000)}
.raid-hp-text{font:700 10px var(--ff-head);color:rgba(255,255,255,.6);margin-bottom:10px}
/* Damage flash */
.raid-dmg-flash{font:900 20px var(--ff-head);color:#ff4400;min-height:28px;text-align:center;margin-bottom:4px}
/* Stats */
.raid-stats{display:flex;gap:8px;margin-bottom:12px}
.raid-stat{flex:1;background:rgba(255,255,255,.02);border:1px solid rgba(255,50,0,.1);border-radius:10px;padding:7px;text-align:center}
.raid-stat-v{font:900 14px var(--ff-head);color:#ff4400}
.raid-stat-l{font:500 7px var(--ff-body);color:rgba(255,255,255,.3)}
/* Attack btn */
.raid-atk-btn{width:100%;background:linear-gradient(135deg,#440000,#990000);border:none;border-radius:14px;padding:16px;font:900 16px var(--ff-head);color:#fff;cursor:pointer;margin-bottom:8px;box-shadow:0 0 24px rgba(255,0,0,.3)}
.raid-atk-btn:disabled{opacity:.3;cursor:default;background:rgba(255,255,255,.06);box-shadow:none}
.raid-atk-pips{display:flex;gap:5px;justify-content:center;flex-wrap:wrap;margin-bottom:10px}
.raid-atk-pip{width:10px;height:10px;border-radius:50%;background:rgba(255,80,0,.8)}
.raid-atk-pip.used{background:rgba(255,255,255,.08)}
/* Claim */
.raid-claim-btn{width:100%;background:linear-gradient(135deg,#550000,#aa2200);border:none;border-radius:14px;padding:14px;font:900 14px var(--ff-head);color:#ffcc00;cursor:pointer;margin-bottom:10px;box-shadow:0 0 20px rgba(255,100,0,.2);animation:raidGlow 1.5s ease-in-out infinite}
@keyframes raidGlow{0%,100%{box-shadow:0 0 20px rgba(255,100,0,.2)}50%{box-shadow:0 0 40px rgba(255,150,0,.5)}}
/* Damage log */
.raid-log{background:rgba(255,255,255,.02);border:1px solid rgba(255,0,0,.08);border-radius:12px;padding:10px 14px;margin-bottom:10px;max-height:100px;overflow-y:auto}
.raid-log-lbl{font:700 7px var(--ff-head);color:rgba(255,0,0,.3);letter-spacing:1px;margin-bottom:6px}
.raid-log-item{font:600 8px var(--ff-body);color:rgba(255,180,180,.6);margin-bottom:3px}
.raid-reward-box{background:rgba(255,100,0,.05);border:1px solid rgba(255,100,0,.2);border-radius:12px;padding:10px;text-align:center;margin-bottom:10px}
.raid-reward-lbl{font:700 8px var(--ff-head);color:rgba(255,150,0,.5);letter-spacing:1px;margin-bottom:4px}
.raid-reward-val{font:900 13px var(--ff-head);color:#ffcc00}
.raid-info{font:600 9px var(--ff-body);color:rgba(255,255,255,.3);text-align:center}

/* ══ PET HATCHERY ══ */
.htch-panel{position:fixed;inset:0;background:#020108;z-index:1019;display:none;flex-direction:column;overflow:hidden}
.htch-panel.open{display:flex}
.htch-header{display:flex;align-items:center;justify-content:space-between;padding:var(--sat) 16px 12px;background:linear-gradient(135deg,#060220,#020108)}
.htch-title{font:700 20px var(--ff-head);background:linear-gradient(90deg,#ff8844,#ffcc00,#44ff88,#4488ff,#cc44ff,#ff8844);background-size:400% auto;-webkit-background-clip:text;-webkit-text-fill-color:transparent;animation:htchShim 4s linear infinite}
@keyframes htchShim{0%{background-position:0%}100%{background-position:400%}}
.htch-scroll{flex:1;overflow-y:auto;padding:10px 14px 28px}
/* Team */
.htch-team{display:flex;gap:8px;margin-bottom:14px}
.htch-slot{flex:1;background:rgba(255,255,255,.02);border:1.5px dashed rgba(255,255,255,.12);border-radius:14px;padding:10px;text-align:center;min-height:80px;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer}
.htch-slot.filled{border-style:solid;border-color:rgba(255,255,255,.2);background:rgba(255,255,255,.03)}
.htch-slot-emoji{font-size:30px;margin-bottom:3px}
.htch-slot-name{font:700 8px var(--ff-head);color:#fff;margin-bottom:2px}
.htch-slot-bonus{font:600 7px var(--ff-body);color:rgba(255,200,100,.7)}
.htch-slot-empty{font:600 8px var(--ff-body);color:rgba(255,255,255,.2)}
.htch-slot-remove{font:600 7px var(--ff-body);color:rgba(255,80,80,.5);margin-top:2px}
/* Incubator */
.htch-incubator{background:rgba(255,255,255,.02);border:2px solid rgba(255,200,0,.15);border-radius:18px;padding:14px;margin-bottom:12px;text-align:center}
.htch-inc-lbl{font:700 8px var(--ff-head);color:rgba(255,200,0,.5);letter-spacing:1px;margin-bottom:10px}
.htch-inc-egg{font-size:56px;display:block;margin-bottom:6px;animation:htchWobble 2s ease-in-out infinite}
@keyframes htchWobble{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}}
.htch-inc-egg.idle{animation:none;opacity:.3}
.htch-inc-name{font:800 12px var(--ff-head);color:#fff;margin-bottom:2px}
.htch-inc-timer{font:700 11px var(--ff-head);color:#ffcc00;margin-bottom:6px}
.htch-inc-bar{background:rgba(255,255,255,.06);border-radius:20px;height:8px;overflow:hidden;margin-bottom:8px}
.htch-inc-fill{height:100%;background:linear-gradient(90deg,#ffcc00,#ff8844);border-radius:20px;transition:width .5s}
.htch-hatch-btn{background:linear-gradient(135deg,#442200,#886600);border:none;border-radius:12px;padding:10px 20px;font:900 12px var(--ff-head);color:#fff;cursor:pointer;box-shadow:0 0 14px rgba(255,150,0,.2)}
.htch-hatch-btn:disabled{opacity:.3;cursor:default;background:rgba(255,255,255,.06);box-shadow:none}
/* Collection */
.htch-coll-lbl{font:700 8px var(--ff-head);color:rgba(255,255,255,.3);letter-spacing:1px;margin-bottom:8px}
.htch-coll-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:7px;margin-bottom:12px}
.htch-egg-card{background:rgba(255,255,255,.02);border:1.5px solid rgba(255,255,255,.07);border-radius:14px;padding:10px;cursor:pointer;transition:border-color .2s}
.htch-egg-card.hatched{border-color:rgba(255,200,0,.25);background:rgba(255,200,0,.03)}
.htch-egg-card:hover{border-color:rgba(255,255,255,.15)}
.htch-egg-card.incubating{border-color:rgba(255,150,0,.4);background:rgba(255,150,0,.04)}
.htch-egg-top{display:flex;align-items:center;gap:8px;margin-bottom:4px}
.htch-egg-ico{font-size:28px}
.htch-egg-info{flex:1}
.htch-egg-name{font:800 10px var(--ff-head);color:#fff;margin-bottom:1px}
.htch-egg-dur{font:600 7px var(--ff-body);color:rgba(255,255,255,.35)}
.htch-egg-bonus{font:600 7px var(--ff-body);color:rgba(255,200,100,.7);margin-bottom:4px}
.htch-egg-cost{font:700 8px var(--ff-head);color:rgba(255,255,255,.4)}
.htch-egg-cost.free{color:#44ff88}
/* Stats */
.htch-stats{display:flex;gap:8px;margin-bottom:10px}
