.spin-free-btn:disabled{opacity:.4;cursor:default}
.spin-kc-btn{flex:1;background:rgba(255,200,0,.1);border:1.5px solid rgba(255,200,0,.35);border-radius:16px;padding:14px;font:800 11px var(--ff-head);color:#ffcc00;cursor:pointer}
/* Result */
.spin-result{font:800 16px var(--ff-head);color:#fff;text-align:center;min-height:28px;width:100%;max-width:320px;margin-bottom:12px}
