/* Dynamic theme CSS variables */
body[data-theme="galaxy"]{--bg:#04020d;--theme-grad:radial-gradient(ellipse at 20% 50%,rgba(50,0,100,.4),transparent 60%),radial-gradient(ellipse at 80% 20%,rgba(0,20,80,.5),transparent 60%)}
body[data-theme="neon"]{--bg:#020408;--theme-grad:repeating-linear-gradient(0deg,transparent,transparent 60px,rgba(0,255,136,.03) 61px),repeating-linear-gradient(90deg,transparent,transparent 60px,rgba(0,255,136,.03) 61px)}
body[data-theme="ocean"]{--bg:#010d18;--theme-grad:radial-gradient(ellipse at 50% 100%,rgba(0,100,200,.3),transparent 70%)}
body[data-theme="volcanic"]{--bg:#0d0400;--theme-grad:radial-gradient(ellipse at 50% 100%,rgba(200,50,0,.25),transparent 60%)}
body[data-theme="sakura"]{--bg:#0d0508;--theme-grad:radial-gradient(ellipse at 30% 0%,rgba(255,100,150,.15),transparent 50%),radial-gradient(ellipse at 70% 100%,rgba(255,150,200,.1),transparent 50%)}
body[data-theme="moonlit"]{--bg:#020a06;--theme-grad:radial-gradient(ellipse at 20% 20%,rgba(80,0,120,.3),transparent 50%),radial-gradient(ellipse at 80% 80%,rgba(0,80,50,.2),transparent 50%)}
body[data-theme="default"]{--bg:#000;--theme-grad:none}
body::before{content:'';position:fixed;inset:0;background:var(--theme-grad,none);pointer-events:none;z-index:0}

