/* ══ PET MICRO-ANIMATIONS ══ */
.pf-body.bounce { animation:petBounce .5s cubic-bezier(.34,1.56,.64,1); }
.pf-body.shake  { animation:petShake .4s ease-in-out; }
.pf-body.spin   { animation:petSpin .6s cubic-bezier(.34,1.56,.64,1); }
.pf-body.float  { animation:petFloat 2s ease-in-out infinite alternate; }
.pf-body.sleep  { animation:petSleep 3s ease-in-out infinite alternate; }
.pf-body.rage   { animation:petRage .15s ease-in-out infinite alternate; }
@keyframes petBounce { 0%{transform:scale(1)} 40%{transform:scale(1.25) translateY(-12px)} 70%{transform:scale(.95)} 100%{transform:scale(1)} }
@keyframes petShake  { 0%,100%{transform:translateX(0)} 20%{transform:translateX(-8px)} 40%{transform:translateX(8px)} 60%{transform:translateX(-6px)} 80%{transform:translateX(6px)} }
@keyframes petSpin   { 0%{transform:rotate(0)} 100%{transform:rotate(360deg)} }
@keyframes petFloat  { from{transform:translateY(0)} to{transform:translateY(-8px)} }
@keyframes petSleep  { from{transform:scale(1) rotate(-2deg)} to{transform:scale(1.04) rotate(2deg)} }
@keyframes petRage   { from{transform:scale(1.08) rotate(-3deg)} to{transform:scale(1.12) rotate(3deg)} }
/* mood overlays on pet area */
.pet-mood-glow { position:absolute;inset:0;border-radius:50%;pointer-events:none;transition:opacity .5s;opacity:0; }
.pet-mood-glow.hungry  { background:radial-gradient(circle,rgba(255,68,85,.12),transparent 70%);opacity:1; }
.pet-mood-glow.happy   { background:radial-gradient(circle,rgba(0,255,136,.08),transparent 70%);opacity:1; }
.pet-mood-glow.sleepy  { background:radial-gradient(circle,rgba(68,136,255,.1),transparent 70%);opacity:1; }
.pet-mood-glow.excited { background:radial-gradient(circle,rgba(255,204,0,.12),transparent 70%);opacity:1; }
/* emote pop floating */
.pet-emote-pop { position:fixed;z-index:700;font-size:28px;line-height:1;animation:emotePop 1.8s ease-out both;pointer-events:none; }
@keyframes emotePop { 0%{opacity:1;transform:translateY(0) scale(1)} 100%{opacity:0;transform:translateY(-60px) scale(1.4)} }

