/* ══════════════════════════════════════
   MEGA-UPGRADE 2.0
══════════════════════════════════════ */

/* ── View transitions ── */
.view { transition:opacity .22s cubic-bezier(.4,0,.2,1),transform .22s cubic-bezier(.4,0,.2,1); transform:translateY(10px) scale(.99); opacity:0; pointer-events:none; will-change:transform,opacity; }
.view.active { opacity:1; transform:translateY(0) scale(1); pointer-events:all; }

/* ── Trending strip ── */
.trend-strip { display:flex; gap:7px; padding:6px 12px 4px; overflow-x:auto; scrollbar-width:none; flex-shrink:0; }
.trend-chip { padding:3px 10px; border-radius:16px; font-size:11px; font-weight:700; background:rgba(255,255,255,.05); border:1px solid rgba(255,255,255,.1); white-space:nowrap; cursor:pointer; color:var(--t2); transition:all .15s; }
.trend-chip:active { transform:scale(.92); }
.trend-chip.hot { color:var(--orange); border-color:rgba(255,136,68,.35); background:rgba(255,136,68,.07); }
.trend-chip.new { color:var(--green); border-color:rgba(0,255,136,.35); background:rgba(0,255,136,.07); }

/* ── Enhanced video card bottom ── */
.vc-live-row { display:flex; gap:8px; align-items:center; padding:4px 12px 8px; font-size:11px; }
.live-dot { width:6px; height:6px; border-radius:50%; background:var(--red); animation:viewPulse 1.4s infinite; flex-shrink:0; }
@keyframes viewPulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.3;transform:scale(.6)} }
.vc-views { color:var(--t3); font-weight:700; }
.vc-hot { color:var(--orange); font-weight:800; }
.vc-follow { padding:4px 11px; border-radius:16px; border:1.5px solid var(--green); font-size:11px; font-weight:800; color:var(--green); cursor:pointer; background:rgba(0,255,136,.07); flex-shrink:0; transition:all .15s; }
.vc-follow.on { border-color:var(--t3); color:var(--t3); background:none; }
.vc-user { align-items:center; }

/* ── Daily login bonus ── */
.daily-days { display:flex; gap:5px; justify-content:center; margin:12px 0; }
.day-item { width:38px; height:54px; border-radius:14px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:2px; background:rgba(10,4,22,.85); border:2px solid rgba(255,255,255,.07); font-size:10px; font-weight:700; color:var(--t3); box-shadow:0 3px 10px rgba(0,0,0,.4); }
.day-item.done { background:rgba(0,10,4,.9); border-color:rgba(0,255,136,.4); color:var(--green); }
.day-item.today { background:rgba(20,14,0,.9); border-color:var(--gold); color:var(--gold); animation:todayGlow 1.6s ease-in-out infinite; box-shadow:0 4px 20px rgba(255,204,0,.2); }
@keyframes todayGlow { 0%,100%{box-shadow:0 0 0 0 rgba(255,204,0,.3)} 50%{box-shadow:0 0 0 8px rgba(255,204,0,0)} }
.day-ico { font-size:20px; line-height:1; }
.day-lbl { font-size:8px; letter-spacing:.5px; text-transform:uppercase; }
.bonus-bigico { font-size:64px; text-align:center; animation:bonusPop .5s cubic-bezier(.17,.67,.3,1.3) both; margin:10px 0 4px; display:block; }
@keyframes bonusPop { 0%{transform:scale(0) rotate(-15deg);opacity:0} 100%{transform:scale(1) rotate(0);opacity:1} }

/* ── Achievement unlock overlay ── */
#achieveOverlay { position:fixed; inset:0; z-index:9998; background:rgba(0,0,0,.9); backdrop-filter:blur(20px); display:flex; flex-direction:column; align-items:center; justify-content:center; opacity:0; pointer-events:none; transition:opacity .3s; }
#achieveOverlay.open { opacity:1; pointer-events:all; }
.ach-big { font-size:88px; animation:achDrop .6s cubic-bezier(.17,.67,.3,1.3) .1s both; filter:drop-shadow(0 0 40px var(--gold)); }
@keyframes achDrop { 0%{transform:translateY(-80px) scale(0) rotate(-20deg);opacity:0} 100%{transform:translateY(0) scale(1) rotate(0);opacity:1} }
.ach-unlocked { font-size:10px; color:var(--gold); font-weight:700; letter-spacing:3px; text-transform:uppercase; margin-bottom:8px; opacity:0; animation:fadeInUp .4s ease .5s both; }
.ach-name { font-family:var(--ff-head); font-size:26px; font-weight:900; color:var(--t1); opacity:0; animation:fadeInUp .4s ease .65s both; margin-bottom:6px; text-align:center; }
.ach-desc { font-size:13px; color:var(--t2); opacity:0; animation:fadeInUp .4s ease .8s both; margin-bottom:28px; text-align:center; }
@keyframes fadeInUp { 0%{opacity:0;transform:translateY(14px)} 100%{opacity:1;transform:translateY(0)} }
.ach-tap { padding:12px 36px; background:var(--gold); color:#000; font-family:var(--ff-head); font-size:16px; font-weight:900; border-radius:24px; cursor:pointer; opacity:0; animation:fadeInUp .4s ease .95s both; }

/* ── Activity ticker ── */
#actTicker { position:fixed; bottom:calc(72px + var(--sab)); left:50%; transform:translateX(-50%) translateY(16px); z-index:500; max-width:290px; background:rgba(8,8,18,.94); backdrop-filter:blur(16px); border:1px solid rgba(255,255,255,.12); border-radius:24px; padding:8px 14px; font-size:12px; font-weight:700; display:flex; gap:8px; align-items:center; opacity:0; transition:all .35s cubic-bezier(.4,0,.2,1); pointer-events:none; }
#actTicker.on { opacity:1; transform:translateX(-50%) translateY(0); }
.at-dot { width:7px; height:7px; border-radius:50%; background:var(--green); flex-shrink:0; animation:viewPulse 1.4s infinite; }

/* ── Notification bell ── */
.notif-wrap { position:relative; flex-shrink:0; }
.notif-btn { width:36px; height:36px; border-radius:10px; background:rgba(0,0,0,.6); backdrop-filter:blur(8px); border:1px solid rgba(255,255,255,.12); display:flex; align-items:center; justify-content:center; cursor:pointer; font-size:16px; flex-shrink:0; }
.notif-badge { position:absolute; top:-3px; right:-3px; width:16px; height:16px; border-radius:50%; background:var(--red); color:#fff; font-size:9px; font-weight:900; display:flex; align-items:center; justify-content:center; border:2px solid var(--bg); animation:wiggleBadge .4s ease; }
@keyframes wiggleBadge { 0%,100%{transform:rotate(0)} 25%{transform:rotate(-10deg)} 75%{transform:rotate(10deg)} }
.notif-panel { position:fixed; top:calc(56px + var(--sat)); right:12px; z-index:998; width:272px; background:linear-gradient(180deg,rgba(10,4,28,.97),rgba(4,2,14,.96)); border:1px solid rgba(170,102,255,.18); border-radius:20px; box-shadow:0 24px 64px rgba(0,0,0,.97),0 0 40px rgba(170,102,255,.06); overflow:hidden; opacity:0; pointer-events:none; transform:translateY(-10px) scale(.96); transition:all .22s cubic-bezier(.34,1.56,.64,1); max-height:320px; overflow-y:auto; }
.notif-panel.open { opacity:1; pointer-events:all; transform:translateY(0) scale(1); }
.notif-hdr { padding:11px 14px; border-bottom:1px solid rgba(170,102,255,.12); font-size:12px; font-weight:800; color:var(--t1); display:flex; justify-content:space-between; align-items:center; background:rgba(170,102,255,.04); font-family:var(--ff-head); }
.notif-row { padding:9px 14px; border-bottom:1px solid var(--line); display:flex; gap:9px; align-items:flex-start; font-size:12px; cursor:pointer; transition:background .15s; }
.notif-row:hover { background:rgba(255,255,255,.03); }
.notif-row:last-child { border-bottom:none; }
.nr-ico { font-size:18px; flex-shrink:0; line-height:1.3; }
.nr-txt { flex:1; color:var(--t2); line-height:1.5; }
.nr-txt b { color:var(--t1); }
.nr-t { font-size:10px; color:var(--t3); flex-shrink:0; margin-top:2px; }

/* ── Level ring ── */
.lv-ring-wrap { position:relative; width:52px; height:52px; flex-shrink:0; }
.lv-ring { width:100%; height:100%; transform:rotate(-90deg); overflow:visible; }
.lr-bg { fill:none; stroke:rgba(255,255,255,.07); stroke-width:3.5; }
.lr-fill { fill:none; stroke-width:3.5; stroke-linecap:round; stroke:var(--pet-col,var(--green)); transition:stroke-dashoffset .7s cubic-bezier(.4,0,.2,1); }
.lv-num { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; }
.lv-n { font-family:var(--ff-head); font-size:15px; font-weight:900; line-height:1; }
.lv-l { font-size:8px; color:var(--t3); font-weight:700; letter-spacing:.3px; }

/* ── XP multiplier chip ── */
#xpMultChip { position:fixed; top:calc(62px + var(--sat)); right:12px; z-index:400; background:linear-gradient(135deg,var(--gold),var(--orange)); color:#000; font-family:var(--ff-head); font-size:12px; font-weight:900; padding:4px 10px; border-radius:16px; opacity:0; transition:opacity .3s; pointer-events:none; box-shadow:0 2px 14px rgba(255,204,0,.5); }
#xpMultChip.show { opacity:1; }

/* ── Territory strip ── */
.terr-strip { display:flex; gap:7px; padding:8px 14px; overflow-x:auto; scrollbar-width:none; border-top:1px solid var(--line); background:rgba(0,0,0,.5); flex-shrink:0; }
.terr-pill { display:flex; align-items:center; gap:5px; padding:5px 11px; border-radius:20px; white-space:nowrap; border:1px solid rgba(255,255,255,.08); font-size:11px; font-weight:700; background:rgba(10,4,22,.8); cursor:pointer; transition:all .15s; }
.terr-pill.mine { border-color:var(--green); color:var(--green); background:rgba(0,255,136,.07); }
.terr-pill.rival { border-color:var(--red); color:var(--red); background:rgba(255,68,85,.07); }
.terr-pill:active { transform:scale(.94); }

/* ── Battle hit animations ── */
.battle-hit-r { animation:hitR .3s ease both; }
.battle-hit-b { animation:hitB .3s ease both; }
@keyframes hitR { 0%,100%{filter:none;transform:scale(1)} 40%{filter:drop-shadow(0 0 16px var(--red)) brightness(1.8);transform:scale(1.18)} }
@keyframes hitB { 0%,100%{filter:none;transform:scale(1)} 40%{filter:drop-shadow(0 0 16px var(--blue)) brightness(1.8);transform:scale(1.18)} }

/* ── Nav improvements ── */
.nb .ni { transition:transform .22s cubic-bezier(.17,.67,.3,1.3),filter .22s,font-size .22s; display:block; font-size:22px; }
.nb.on .ni { transform:scale(1.22) translateY(-2px); filter:drop-shadow(0 0 12px var(--green)); font-size:24px; }
.nb.on .nl { font-weight:900!important; letter-spacing:.8px!important; }
.nb.on::after { content:''; position:absolute; bottom:0; left:50%; transform:translateX(-50%); width:22px; height:2.5px; background:var(--green); border-radius:2px; box-shadow:0 0 8px var(--green); }
.nb { position:relative; transition:opacity .15s; }
.nb:active { opacity:.7; }
.nb[data-v="pet"].on .ni,.nb[data-v="pet"].on::after { filter:drop-shadow(0 0 12px var(--green)); background:var(--green); box-shadow:0 0 8px var(--green); }
.nb[data-v="flash"].on .ni { filter:drop-shadow(0 0 12px var(--pink))!important; }
.nb[data-v="flash"].on .nl { color:var(--pink)!important; }
.nb[data-v="flash"].on::after { background:var(--pink)!important; box-shadow:0 0 8px var(--pink)!important; }
.nb[data-v="games"].on .ni { filter:drop-shadow(0 0 12px var(--blue))!important; }
.nb[data-v="games"].on .nl { color:var(--blue)!important; }
.nb[data-v="games"].on::after { background:var(--blue)!important; box-shadow:0 0 8px var(--blue)!important; }
.nb[data-v="profile"].on .ni { filter:drop-shadow(0 0 12px var(--purple))!important; }
.nb[data-v="profile"].on .nl { color:var(--purple)!important; }
.nb[data-v="profile"].on::after { background:var(--purple)!important; box-shadow:0 0 8px var(--purple)!important; }

/* ── Online indicator ── */
.online-pip { display:inline-block; width:7px; height:7px; border-radius:50%; background:var(--green); animation:viewPulse 2s infinite; margin-right:3px; }
.away-pip { display:inline-block; width:7px; height:7px; border-radius:50%; background:var(--gold); margin-right:3px; }

/* ── Follow count in profile ── */
.follow-row { display:flex; gap:20px; margin:10px 0; }
.follow-stat { text-align:center; cursor:pointer; }
.follow-stat-n { font-family:var(--ff-head); font-size:22px; font-weight:900; }
.follow-stat-l { font-size:10px; color:var(--t3); text-transform:uppercase; letter-spacing:.5px; }

/* ── Real-time XP gauge ── */
.xp-gauge-wrap { display:flex; align-items:center; gap:6px; margin:6px 0; }
.xp-gauge { flex:1; height:6px; background:rgba(255,255,255,.06); border-radius:3px; overflow:hidden; }
.xp-gauge-fill { height:100%; background:linear-gradient(90deg,var(--pet-col,var(--green)),color-mix(in srgb,var(--pet-col,var(--green)) 60%,#fff 40%)); border-radius:3px; transition:width .5s cubic-bezier(.4,0,.2,1); }

/* ── Combo badge upgrade ── */
.combo-badge { box-shadow:0 4px 24px rgba(255,204,0,.5) !important; }

/* ── shimmer loading ── */
@keyframes shimmer { 0%{background-position:-200% 0} 100%{background-position:200% 0} }
.shimmer { background:linear-gradient(90deg,rgba(14,6,30,.9) 25%,rgba(22,10,44,.95) 50%,rgba(14,6,30,.9) 75%); background-size:200% 100%; animation:shimmer 1.5s infinite; border-radius:8px; }

/* ════ ROUND 3 UPGRADES ════ */

/* Fix live avatar ring */
.vc-ava-live { border-color:var(--red) !important; animation:liveAvaRing 1.3s ease-in-out infinite; }
@keyframes liveAvaRing { 0%,100%{box-shadow:0 0 0 0 rgba(255,68,85,.5)} 60%{box-shadow:0 0 0 5px rgba(255,68,85,0)} }

