.heart-burst { position:fixed; font-size:72px; animation:heartBurst .8s cubic-bezier(.17,.67,.3,1.3) both; pointer-events:none; z-index:700; transform:translate(-50%,-50%); }
@keyframes heartBurst { 0%{transform:translate(-50%,-50%) scale(0);opacity:1} 60%{transform:translate(-50%,-100%) scale(1.3);opacity:1} 100%{transform:translate(-50%,-150%) scale(1);opacity:0} }

/* ── SHOP WINDOW ── */
.shop-tabs { display:flex; gap:6px; padding:10px 16px 6px; }
.stab { flex:1; padding:7px 4px; border-radius:12px; background:rgba(10,6,24,.8); border:1px solid rgba(255,255,255,.07); font-size:11px; font-weight:800; cursor:pointer; text-align:center; transition:all .15s; color:var(--t2); font-family:var(--ff-head); }
.stab:active { transform:scale(.95); }
.stab.on { background:rgba(0,255,136,.1); border-color:var(--pet-col,var(--green)); color:var(--pet-col,var(--green)); box-shadow:0 0 14px rgba(0,255,136,.1); }
.shop-panel { display:none; padding:0 16px; }
