.boss-att-btn:active { transform:scale(.87); }
.event-banner { background:linear-gradient(135deg,rgba(255,204,0,.12),rgba(255,136,68,.07)); border:1.5px solid rgba(255,204,0,.4); border-radius:14px; padding:9px 13px; margin:0 14px 8px; display:flex; align-items:center; gap:10px; }
.ev-ico { font-size:26px; animation:evBounce 1.4s ease-in-out infinite; flex-shrink:0; }
