.ev-name { font-family:var(--ff-head); font-size:13px; font-weight:900; color:var(--gold); }
.ev-timer { font-size:10px; color:var(--t2); font-weight:700; margin-top:2px; }
.ev-pill { background:linear-gradient(135deg,var(--gold),var(--orange)); color:#000; font-family:var(--ff-head); font-size:13px; font-weight:900; padding:6px 12px; border-radius:20px; flex-shrink:0; }
/* Featured game of the day */
.feat-game-card { margin:0 14px 8px; background:linear-gradient(135deg,rgba(0,255,136,.1),rgba(68,136,255,.06)); border:1.5px solid rgba(0,255,136,.32); border-radius:18px; padding:11px 14px; display:flex; align-items:center; gap:12px; position:relative; overflow:hidden; cursor:pointer; transition:all .15s; box-shadow:0 4px 24px rgba(0,255,136,.08); }
