.feat-game-card::before { content:''; position:absolute; inset:0; background:linear-gradient(90deg,transparent,rgba(0,255,136,.08),transparent); animation:bossShine 2.5s linear infinite; pointer-events:none; }
.feat-game-card::after { content:''; position:absolute; top:0; left:0; right:0; height:1px; background:linear-gradient(90deg,transparent,rgba(0,255,136,.5),transparent); pointer-events:none; }
.feat-game-ico { font-size:42px; flex-shrink:0; animation:evBounce 2.2s ease-in-out infinite; filter:drop-shadow(0 0 12px rgba(0,255,136,.4)); }
.feat-game-info { flex:1; }
.feat-game-badge { font-size:8px; font-weight:900; letter-spacing:2px; color:var(--green); text-transform:uppercase; margin-bottom:2px; }
.feat-game-name { font-family:var(--ff-head); font-size:17px; font-weight:900; line-height:1.2; }
