.feat-play-btn { background:linear-gradient(135deg,var(--green),var(--teal)); color:#000; font-family:var(--ff-head); font-size:11px; font-weight:900; padding:8px 13px; border-radius:12px; border:none; cursor:pointer; flex-shrink:0; white-space:nowrap; }
/* Session XP chips */
.sess-xp-row { display:flex; gap:6px; padding:0 14px 10px; overflow-x:auto; scrollbar-width:none; }
.sess-xp-row::-webkit-scrollbar { display:none; }
.sess-xp-chip { flex-shrink:0; background:rgba(10,4,22,.8); border:1px solid rgba(255,255,255,.07); border-radius:10px; padding:4px 9px; font-size:9px; font-weight:700; color:var(--t3); transition:all .2s; white-space:nowrap; }
.sess-xp-chip.active { border-color:rgba(0,255,136,.35); color:var(--green); background:rgba(0,255,136,.06); }
/* Runner difficulty */
.runner-diff-row { display:flex; gap:8px; padding:6px 0 8px; justify-content:center; }
.runner-diff-btn { padding:8px 18px; border-radius:12px; font-family:var(--ff-head); font-size:12px; font-weight:900; border:1.5px solid rgba(255,255,255,.08); background:rgba(10,4,22,.8); color:var(--t3); cursor:pointer; transition:all .12s; }
.runner-diff-btn.on { border-color:var(--green); color:var(--green); background:rgba(0,255,136,.08); }
.lucky-box-ico { font-size:80px; display:block; text-align:center; cursor:pointer; animation:luckyBob 1.8s ease-in-out infinite; filter:drop-shadow(0 0 24px var(--gold)); margin:10px 0 6px; }
@keyframes luckyBob { 0%,100%{transform:translateY(0) rotate(-8deg)} 50%{transform:translateY(-14px) rotate(8deg)} }
.lucky-box-ico.pop { animation:luckyPop .6s cubic-bezier(.17,.67,.3,1.3) both; }
@keyframes luckyPop { 0%{transform:scale(1)} 30%{transform:scale(1.5) rotate(-20deg)} 65%{transform:scale(.85) rotate(15deg)} 100%{transform:scale(1.1)} }
.lucky-reveal { font-size:56px; display:block; text-align:center; animation:revealDrop .5s cubic-bezier(.17,.67,.3,1.3) .1s both; opacity:0; }
@keyframes revealDrop { 0%{transform:scale(0) rotate(-30deg);opacity:0} 100%{transform:scale(1) rotate(0);opacity:1} }
.lucky-prize-n { font-family:var(--ff-head); font-size:22px; font-weight:900; color:var(--gold); text-align:center; animation:fadeInUp .4s ease .4s both; opacity:0; }
.lucky-prize-d { font-size:13px; color:var(--t2); text-align:center; margin:4px 0 16px; animation:fadeInUp .4s ease .6s both; opacity:0; }
#luckyDropBar { position:fixed; bottom:calc(82px + var(--sab)); right:12px; z-index:601; transform:translateX(140%); transition:transform .4s cubic-bezier(.17,.67,.3,1.3); cursor:pointer; }
#luckyDropBar.show { transform:translateX(0); }
.ldb-inner { background:linear-gradient(135deg,var(--gold),var(--orange)); color:#000; font-family:var(--ff-head); font-size:13px; font-weight:900; padding:11px 16px; border-radius:22px; box-shadow:0 4px 28px rgba(255,204,0,.65); display:flex; align-items:center; gap:7px; }
.ldi-ico { font-size:24px; animation:luckyBob .9s ease-in-out infinite; }
.prestige-card { background:linear-gradient(135deg,rgba(255,204,0,.1),rgba(255,136,68,.07)); border:2px solid rgba(255,204,0,.45); border-radius:18px; padding:16px; position:relative; overflow:hidden; margin-bottom:12px; }
.prestige-card::before { content:'★'; position:absolute; top:-10px; right:12px; font-size:80px; opacity:.04; font-family:var(--ff-head); pointer-events:none; }
.prestige-btn { width:100%; padding:14px; background:linear-gradient(135deg,rgba(255,204,0,.18),rgba(255,136,68,.12)); border:2px solid rgba(255,204,0,.55); border-radius:14px; cursor:pointer; font-family:var(--ff-head); font-size:15px; font-weight:900; color:var(--gold); display:flex; align-items:center; justify-content:center; gap:8px; transition:all .2s; }
.prestige-btn:active { transform:scale(.96); }
.prestige-btn:disabled { opacity:.3; cursor:not-allowed; transform:none; }
.p-star { display:inline-block; animation:starSpin 2s linear infinite; }
@keyframes starSpin { 0%{transform:rotate(0)} 100%{transform:rotate(360deg)} }
.prestige-badge-pill { display:inline-flex; align-items:center; background:linear-gradient(135deg,var(--gold),var(--orange)); color:#000; font-size:10px; font-weight:900; padding:2px 8px; border-radius:10px; }
.radio-btn { width:36px; height:36px; border-radius:10px; background:rgba(0,0,0,.6); backdrop-filter:blur(8px); border:1px solid rgba(255,255,255,.12); display:flex; align-items:center; justify-content:center; cursor:pointer; font-size:18px; flex-shrink:0; transition:all .25s; }
.radio-btn.on { border-color:var(--green); box-shadow:0 0 14px rgba(0,255,136,.35); animation:radioPulse 1.5s ease-in-out infinite; }
@keyframes radioPulse { 0%,100%{box-shadow:0 0 0 0 rgba(0,255,136,.3)} 50%{box-shadow:0 0 0 8px rgba(0,255,136,0)} }
.radio-note { position:fixed; pointer-events:none; z-index:350; font-size:16px; animation:noteRise 2.5s ease both; }
@keyframes noteRise { 0%{opacity:.9;transform:translateY(0) rotate(-10deg)} 100%{opacity:0;transform:translateY(-100px) rotate(20deg) scale(.4)} }
.raid-boss-card { text-align:center; padding:16px 14px 12px; background:radial-gradient(ellipse at 50% 0%,rgba(255,34,85,.2) 0%,transparent 70%); border:1px solid rgba(255,34,85,.3); border-radius:18px; margin-bottom:10px; }
.raid-boss-em { font-size:68px; display:block; margin-bottom:4px; filter:drop-shadow(0 0 30px rgba(255,34,85,.8)); animation:bossHover 2.5s ease-in-out infinite; }
@keyframes bossHover { 0%,100%{transform:translateY(0) scale(1)} 50%{transform:translateY(-10px) scale(1.06)} }
.raid-phase-badge { font-size:9px; font-weight:900; letter-spacing:2px; text-transform:uppercase; padding:3px 9px; border-radius:10px; display:inline-block; margin-bottom:8px; }
.raid-phase-badge.p1 { background:rgba(255,34,85,.2); color:var(--red); }
.raid-phase-badge.p2 { background:rgba(255,136,0,.2); color:var(--orange); }
.raid-phase-badge.p3 { background:rgba(170,102,255,.2); color:var(--purple); }
.raid-phase-badge.p4 { background:rgba(255,204,0,.2); color:var(--gold); }
.raid-hp-bar { height:8px; background:rgba(255,255,255,.08); border-radius:4px; overflow:hidden; margin-bottom:4px; }
.raid-hp-inner { height:100%; border-radius:4px; transition:width .7s cubic-bezier(.4,0,.2,1); }
.raid-hp-inner.p1 { background:linear-gradient(90deg,#ff1144,#ff6644); }
.raid-hp-inner.p2 { background:linear-gradient(90deg,#ff6600,#ffcc00); }
.raid-hp-inner.p3 { background:linear-gradient(90deg,var(--purple),var(--blue)); }
.raid-hp-inner.p4 { background:linear-gradient(90deg,var(--gold),var(--green)); }
.raid-dmg-row { display:flex; justify-content:space-between; font-size:11px; color:var(--t3); font-weight:700; margin-bottom:10px; }
.raid-you-hp { display:flex; align-items:center; gap:8px; margin-bottom:10px; font-size:11px; color:var(--t2); font-weight:700; }
.raid-you-hp-bar { flex:1; height:6px; background:rgba(255,255,255,.07); border-radius:3px; overflow:hidden; }
.raid-you-hp-fill { height:100%; background:linear-gradient(90deg,var(--green),#00ffaa); border-radius:3px; transition:width .4s; }
.raid-grid { display:grid; grid-template-columns:1fr 1fr; gap:8px; margin-bottom:8px; }
.raid-btn { padding:12px 6px; border-radius:14px; border:1px solid rgba(255,255,255,.1); background:linear-gradient(160deg,rgba(20,6,40,.9),rgba(8,2,16,.95)); cursor:pointer; text-align:center; font-size:12px; font-weight:800; transition:all .15s; line-height:1.4; }
.raid-btn:active { transform:scale(.9); }
.raid-btn.sp { border-color:rgba(255,34,85,.45); background:rgba(255,34,85,.08); color:var(--red); }
.raid-btn.def { border-color:rgba(68,136,255,.45); background:rgba(68,136,255,.08); color:var(--blue); }
.raid-btn.heal { border-color:rgba(0,255,136,.45); background:rgba(0,255,136,.08); color:var(--green); }
.raid-btn.ult { border-color:rgba(255,204,0,.45); background:rgba(255,204,0,.08); color:var(--gold); }
.raid-log { font-size:12px; color:var(--t2); text-align:center; padding:4px 0; min-height:20px; }
.raid-reward-txt { font-size:12px; color:var(--gold); font-weight:800; text-align:center; margin-top:4px; }
#featToast { position:fixed; top:calc(62px + var(--sat)); left:50%; transform:translateX(-50%) translateY(-20px); z-index:800; background:linear-gradient(135deg,rgba(255,204,0,.95),rgba(255,136,68,.95)); color:#000; font-family:var(--ff-head); font-size:13px; font-weight:900; padding:9px 22px; border-radius:22px; opacity:0; transition:all .4s cubic-bezier(.4,0,.2,1); pointer-events:none; box-shadow:0 4px 24px rgba(255,204,0,.55); white-space:nowrap; }
#featToast.on { opacity:1; transform:translateX(-50%) translateY(0); }
/* ══════════════════════════════════════════
   ROUND 6 — NEO-BRUTALISM · BATTLE2 · DNA · KC
══════════════════════════════════════════ */
:root {
  --green: #39FF14;
  --pink: #FF007F;
  --blue: #0066FF;
  --neon-pink: #FF007F;
  --elec-blue: #0066FF;
  --kc-col: #FF007F;
}

/* GLOBAL NEO-BRUTALISM */
.card,.game-panel.active,.battle-arena,.vitals-card,.pet-info-card,
.trust-card,.raid-boss-card,.pott-tier,.challenge-card,.evol-node {
  border:2.5px solid rgba(255,255,255,.25) !important;
  box-shadow:4px 4px 0 rgba(255,255,255,.08) !important;
}
.btn { transition:transform .08s,box-shadow .08s !important; }
.btn:active { transform:translate(3px,3px) !important; box-shadow:0 0 0 transparent !important; }
.care-btn { transition:transform .08s,box-shadow .08s; }
.care-btn:active { transform:translate(3px,3px) !important; box-shadow:0 0 0 !important; }
.move-btn { border:2px solid rgba(255,255,255,.2) !important; }
.move-btn:active { transform:translate(3px,3px) !important; box-shadow:none !important; }
.raid-btn:active,.boss-att-btn:active,.pott-claim-btn:active,.fish-cast-btn:active,.prestige-btn:active { transform:translate(3px,3px) !important; }

/* TOPBAR FIX — smaller, works on all screens */
.topbar { gap:6px !important; }
.pills { gap:4px !important; }
.pill { padding:3px 7px !important; font-size:10px !important; }
.pott-chip { padding:3px 7px !important; }
.pott-chip-lbl { font-size:9px !important; }
.pott-chip-val { font-size:10px !important; }

/* KC CURRENCY */
.kc-pill { color:var(--neon-pink); border-color:rgba(255,0,127,.3) !important; }
.kc-pill b { color:var(--neon-pink); }

/* FLASH FEED FIX */
.video-card { max-height:100svh !important; }
.video-feed { scroll-snap-type:y mandatory !important; }

/* ══ BATTLE 2.0 — JUDGMENT RING ══ */
.battle2-wrap { padding:0 14px 14px; }
.b2-fighters { display:flex; align-items:center; justify-content:space-between; padding:10px 0 6px; }
.b2-fighter { text-align:center; flex:1; }
.b2-em { font-size:44px; display:block; filter:drop-shadow(0 0 14px var(--neon-pink)); transition:all .2s; }
.b2-em.hit { animation:b2Hit .35s ease; }
@keyframes b2Hit { 0%,100%{transform:scale(1)} 30%{transform:scale(1.4) rotate(-15deg)} 60%{transform:scale(.8)} }
.b2-name { font-family:var(--ff-head); font-size:12px; font-weight:900; }
.b2-lv { font-size:10px; color:var(--t3); }
.b2-vs { font-family:var(--ff-head); font-size:22px; font-weight:900; color:var(--red); text-shadow:0 0 12px var(--red); }
.b2-hp-row { display:flex; align-items:center; gap:8px; margin-bottom:4px; }
.b2-hp-lbl { font-size:10px; font-weight:900; min-width:24px; color:var(--t2); }
.b2-hp-track { flex:1; height:8px; background:rgba(255,255,255,.07); border-radius:4px; overflow:hidden; }
.b2-hp-fill { height:100%; border-radius:4px; transition:width .4s; }
.b2-hp-fill.you { background:linear-gradient(90deg,var(--green),#00ff88); box-shadow:0 0 8px var(--green); }
.b2-hp-fill.enemy { background:linear-gradient(90deg,var(--red),#ff6644); box-shadow:0 0 8px var(--red); }
.b2-hp-val { font-size:10px; font-weight:900; min-width:32px; text-align:right; }
.b2-elem-row { display:flex; justify-content:center; gap:8px; margin:6px 0; }
.b2-elem { padding:4px 12px; border-radius:20px; font-size:11px; font-weight:900; border:2px solid currentColor; cursor:pointer; transition:all .15s; background:rgba(0,0,0,.4); }
.b2-elem:active { transform:scale(.88); filter:brightness(1.4); box-shadow:0 0 16px currentColor; }
.b2-elem.fire { color:#ff6644; } .b2-elem.water { color:#4488ff; }
.b2-elem.nature { color:#44ff88; } .b2-elem.electric { color:#ffcc00; }
.b2-elem.disabled { opacity:.2; pointer-events:none; }
#judgmentCanvas { display:block; margin:8px auto; border-radius:50%; cursor:pointer; filter:drop-shadow(0 0 18px rgba(255,51,119,.3)); }
.b2-log { font-family:var(--ff-head); font-size:13px; font-weight:900; text-align:center; min-height:22px; padding:5px 0; color:var(--t1); text-shadow:0 0 8px rgba(255,255,255,.2); letter-spacing:.3px; }
.b2-cd-row { display:flex; gap:6px; justify-content:center; margin-top:6px; font-size:10px; color:var(--t3); }
.b2-cd-item { padding:2px 10px; background:rgba(10,4,22,.8); border-radius:8px; border:1px solid rgba(255,255,255,.08); }

/* ══ DNA MIXER ══ */
.dna-modal-body { padding:16px; }
.dna-parents { display:flex; align-items:center; justify-content:center; gap:14px; margin-bottom:16px; }
.dna-parent { text-align:center; padding:12px 16px; background:linear-gradient(160deg,rgba(14,6,30,.9),rgba(6,2,14,.95)); border:2px solid rgba(255,255,255,.09); border-radius:16px; cursor:pointer; transition:all .2s; flex:1; }
.dna-parent.selected { border-color:var(--green); box-shadow:0 0 16px rgba(57,255,20,.3); }
.dna-parent:active { transform:scale(.93); }
.dna-parent-em { font-size:38px; display:block; }
.dna-parent-nm { font-size:11px; font-weight:800; margin-top:4px; }
.dna-plus { font-family:var(--ff-head); font-size:28px; font-weight:900; color:var(--neon-pink); flex-shrink:0; }
.dna-result-wrap { text-align:center; padding:16px; background:linear-gradient(160deg,rgba(16,8,36,.92),rgba(6,2,14,.96)); border:2px solid rgba(255,255,255,.09); border-radius:16px; margin-bottom:14px; }
.dna-result-em { font-size:56px; display:block; margin-bottom:4px; }
.dna-result-name { font-family:var(--ff-head); font-size:18px; font-weight:900; color:var(--gold); margin-bottom:4px; }
.dna-result-rarity { display:inline-block; padding:3px 12px; border-radius:12px; font-size:10px; font-weight:900; letter-spacing:1px; text-transform:uppercase; }
.rarity-common { background:rgba(136,136,136,.2); color:#888; border:1px solid #888; }
.rarity-rare { background:rgba(68,136,255,.2); color:var(--blue); border:1px solid var(--blue); }
.rarity-epic { background:rgba(170,102,255,.2); color:var(--purple); border:1px solid var(--purple); }
.rarity-legendary { background:rgba(255,204,0,.2); color:var(--gold); border:1px solid var(--gold); }
.dna-anim { animation:dnaSplice .8s ease both; }
@keyframes dnaSplice { 0%{transform:scale(0) rotate(-180deg);opacity:0} 60%{transform:scale(1.3) rotate(10deg)} 100%{transform:scale(1) rotate(0);opacity:1} }
.dna-stat-row { display:flex; justify-content:space-between; font-size:11px; margin-top:8px; gap:6px; }
.dna-stat { flex:1; text-align:center; padding:6px; background:rgba(255,255,255,.04); border-radius:8px; }
.dna-splice-btn { width:100%; padding:14px; border-radius:14px; font-family:var(--ff-head); font-size:16px; font-weight:900; border:none; cursor:pointer; color:#000; transition:all .15s; position:relative; overflow:hidden; }
.dna-splice-btn:active { transform:translate(3px,3px) !important; }
.dna-lab-bg { background:linear-gradient(135deg,rgba(57,255,20,.12),rgba(255,0,127,.08)); }

/* ══ FLOATING PET COMPANION ══ */
#floatPet { position:fixed; bottom:calc(90px + var(--sab)); right:12px; z-index:500; cursor:pointer; user-select:none; transition:all .3s cubic-bezier(.34,1.56,.64,1); }
#floatPet:active { transform:scale(.85); }
.fp-bubble { position:absolute; bottom:100%; right:0; background:rgba(10,4,22,.92); border:2px solid var(--green); border-radius:14px 14px 0 14px; padding:6px 10px; font-size:11px; font-weight:800; white-space:nowrap; opacity:0; transition:opacity .3s; pointer-events:none; color:var(--green); margin-bottom:4px; }
.fp-bubble.type-good    { border-color:var(--green);color:var(--green); }
.fp-bubble.type-gold    { border-color:var(--gold);color:var(--gold); }
.fp-bubble.type-magic   { border-color:var(--purple);color:var(--purple); }
.fp-bubble.type-info    { border-color:var(--blue);color:var(--blue); }
.fp-bubble.type-danger  { border-color:var(--red);color:var(--red); }
.fp-bubble.type-warm    { border-color:var(--orange);color:var(--orange); }
.fp-bubble { animation:none; }
.fp-bubble.show { animation:fpPop .25s cubic-bezier(.34,1.56,.64,1) both; }
@keyframes fpPop { 0%{transform:scale(0) translateY(8px);opacity:0} 100%{transform:scale(1) translateY(0);opacity:1} }

.fp-bubble.show { opacity:1; }
#fpEm { font-size:30px; display:block; filter:drop-shadow(0 0 8px var(--green)); animation:fpBob 2.5s ease-in-out infinite; }
@keyframes fpBob { 0%,100%{transform:translateY(0) rotate(-5deg)} 50%{transform:translateY(-6px) rotate(5deg)} }

/* ══ FISHING TIMING BAR ══ */
.fish-timing-wrap { padding:8px 0; }
.fish-bar-track { height:28px; background:rgba(255,255,255,.05); border-radius:14px; position:relative; overflow:hidden; border:2px solid rgba(255,255,255,.1); margin-bottom:8px; }
.fish-bar-zone { position:absolute; top:0; height:100%; border-radius:12px; }
.fish-bar-zone.hit { background:rgba(57,255,20,.35); }
.fish-bar-zone.perfect { background:rgba(255,204,0,.55); }
.fish-bar-cursor { position:absolute; top:0; width:5px; height:100%; background:#fff; border-radius:3px; box-shadow:0 0 10px #fff; transition:left .016s linear; }
.fish-bar-lbl { display:flex; justify-content:space-between; font-size:10px; color:var(--t3); font-weight:800; }
.fish-catch-result { text-align:center; min-height:44px; display:flex; align-items:center; justify-content:center; flex-direction:column; }
.fish-result-em { font-size:36px; display:block; animation:fishPop .4s cubic-bezier(.17,.67,.3,1.3) both; }
@keyframes fishPop { 0%{transform:scale(0)} 70%{transform:scale(1.3)} 100%{transform:scale(1)} }

/* ══ SPIN WHEEL FIX ══ */
#spinCanvasNew { display:block; margin:0 auto; border-radius:50%; cursor:pointer; }
.spin-new-wrap { text-align:center; padding:12px 0; }
/* ══ RIPPLE ══ */
.ripple-circle { position:fixed; pointer-events:none; border-radius:50%; background:rgba(0,255,136,.35); transform:scale(0); animation:rippleExp .6s ease-out both; z-index:9999; }
@keyframes rippleExp { 0%{transform:scale(0);opacity:1} 100%{transform:scale(4);opacity:0} }

/* ══ POTT ══ */
.pott-chip { display:flex; align-items:center; gap:5px; background:linear-gradient(135deg,rgba(255,204,0,.15),rgba(255,136,0,.1)); border:1px solid rgba(255,204,0,.4); border-radius:20px; padding:4px 10px; cursor:pointer; animation:pottPulse 2s ease-in-out infinite; }
@keyframes pottPulse { 0%,100%{border-color:rgba(255,204,0,.4)} 50%{border-color:rgba(255,204,0,.9);box-shadow:0 0 12px rgba(255,204,0,.4)} }
.pott-chip-lbl { font-size:10px; font-weight:900; color:var(--gold); font-family:var(--ff-head); }
.pott-chip-val { font-size:11px; font-weight:900; color:var(--gold); }
.pott-modal-inner { padding:16px; }
.pott-tier { background:linear-gradient(180deg,rgba(10,6,0,.97),rgba(4,2,0,.95)); border:1px solid rgba(255,204,0,.1); border-radius:18px; padding:14px; margin-bottom:10px; position:relative; overflow:hidden; box-shadow:0 4px 20px rgba(0,0,0,.5); }
.pott-tier.hot { border-color:rgba(255,204,0,.45); background:linear-gradient(135deg,rgba(22,14,0,.97),rgba(10,6,0,.95)); box-shadow:0 4px 28px rgba(255,204,0,.08); }
.pott-tier-hdr { display:flex; align-items:center; justify-content:space-between; margin-bottom:8px; }
.pott-tier-name { font-family:var(--ff-head); font-size:15px; font-weight:900; }
.pott-tier-amt { font-family:var(--ff-head); font-size:18px; font-weight:900; color:var(--gold); }
.pott-cd { font-size:10px; color:var(--t3); font-weight:700; }
.pott-tickets { font-size:11px; color:var(--green); font-weight:800; margin-bottom:8px; }
.pott-bar { height:4px; background:rgba(255,255,255,.06); border-radius:2px; overflow:hidden; margin-bottom:10px; }
.pott-bar-fill { height:100%; background:linear-gradient(90deg,var(--gold),var(--orange)); border-radius:2px; transition:width .5s; }
.pott-claim-btn { width:100%; padding:10px; background:linear-gradient(135deg,var(--gold),var(--orange)); color:#000; font-family:var(--ff-head); font-size:13px; font-weight:900; border-radius:12px; border:none; cursor:pointer; transition:all .2s; }
.pott-claim-btn:disabled { opacity:.3; cursor:not-allowed; }
@keyframes pottGlow { from{opacity:.03;} to{opacity:.12;} }
.pott-winner-row { font-size:11px; color:var(--t2); padding:4px 0; border-top:1px solid var(--line); margin-top:8px; }
.pott-jackpot-badge { position:absolute; top:10px; right:10px; background:linear-gradient(135deg,var(--gold),var(--orange)); color:#000; font-size:9px; font-weight:900; padding:2px 8px; border-radius:10px; }

/* ══ KARMA RUNNER ══ */
#runnerCanvas { width:100%; height:220px; display:block; border-radius:16px; background:linear-gradient(180deg,#0a0014 0%,#000 60%,#0a0028 100%); }
.runner-hud { display:flex; justify-content:space-between; padding:8px 12px; }
.runner-stat { text-align:center; }
.runner-stat-v { font-family:var(--ff-head); font-size:20px; font-weight:900; color:var(--green); }
.runner-stat-l { font-size:9px; color:var(--t3); font-weight:700; }
.runner-start-overlay { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; border-radius:16px; background:rgba(0,0,0,.65); backdrop-filter:blur(4px); }
.runner-wrap { position:relative; }

/* ══ BOUNTY VERIFY ══ */
.verify-step { text-align:center; padding:20px 16px; }
.verify-big-ico { font-size:56px; display:block; margin-bottom:12px; }
.verify-code-display { font-family:var(--ff-head); font-size:36px; font-weight:900; letter-spacing:8px; color:var(--green); text-align:center; padding:16px; background:rgba(0,255,136,.06); border:1px solid rgba(0,255,136,.2); border-radius:14px; margin:12px 0; }
.verify-steps-row { display:flex; gap:6px; justify-content:center; margin-bottom:16px; }
.verify-dot { width:32px; height:6px; border-radius:3px; background:var(--line); transition:all .3s; }
.verify-dot.done { background:var(--green); }
.step-counter-ring { width:100px; height:100px; margin:0 auto 12px; position:relative; }
.scr-svg { width:100%; height:100%; }
.friend-verify-row { display:flex; align-items:center; gap:10px; padding:12px; background:rgba(10,4,22,.8); border-radius:12px; margin:8px 0; cursor:pointer; border:1px solid rgba(255,255,255,.08); transition:all .2s; }
.friend-verify-row:active { transform:scale(.96); }
.friend-verify-row.confirmed { border-color:var(--green); background:rgba(0,255,136,.06); }

/* ══ SOCIAL PETS ══ */
.friends-pets-row { display:flex; gap:10px; overflow-x:auto; padding:12px 16px 4px; scrollbar-width:none; }
.friend-pet-card { flex-shrink:0; text-align:center; background:linear-gradient(180deg,rgba(0,255,136,.05),rgba(0,0,0,.1)); border:1px solid rgba(0,255,136,.12); border-radius:16px; padding:11px 12px; min-width:76px; cursor:pointer; transition:all .2s; box-shadow:0 2px 10px rgba(0,0,0,.3); }
.friend-pet-card:active { transform:scale(.91); }
.friend-pet-card:hover { border-color:rgba(0,255,136,.3); box-shadow:0 4px 18px rgba(0,255,136,.12); }
.fp-em { font-size:30px; display:block; }
.fp-name { font-size:9px; font-weight:800; color:var(--t2); margin-top:5px; white-space:nowrap; }
.fp-lv { font-size:10px; color:var(--green); font-weight:900; }
.fp-online { width:8px; height:8px; border-radius:50%; background:var(--green); margin:2px auto 0; animation:onlinePing 1.5s ease-in-out infinite; }
.fp-offline { width:8px; height:8px; border-radius:50%; background:var(--t3); margin:2px auto 0; }
@keyframes onlinePing { 0%,100%{box-shadow:0 0 0 0 rgba(0,255,136,.4)} 50%{box-shadow:0 0 0 4px rgba(0,255,136,0)} }
.friend-streak-banner { margin:8px 14px; padding:13px 14px; background:linear-gradient(135deg,rgba(255,204,0,.14),rgba(255,136,0,.08)); border:1px solid rgba(255,204,0,.4); border-radius:16px; display:flex; align-items:center; gap:12px; cursor:pointer; box-shadow:0 4px 24px rgba(255,180,0,.12); animation:streakBannerGlow 3s ease-in-out infinite; }
@keyframes streakBannerGlow { 0%,100%{box-shadow:0 4px 24px rgba(255,180,0,.1)} 50%{box-shadow:0 4px 32px rgba(255,180,0,.25)} }
.fsb-fire { font-size:34px; animation:fireShake .45s ease-in-out infinite alternate; }
@keyframes fireShake { 0%{transform:rotate(-5deg) scale(1)} 100%{transform:rotate(5deg) scale(1.1)} }
.fsb-txt { flex:1; }
.fsb-title { font-family:var(--ff-head); font-size:13px; font-weight:900; color:var(--gold); }
.fsb-sub { font-size:11px; color:var(--t2); margin-top:2px; }
.daily-streak-popup { position:fixed; inset:0; z-index:700; display:flex; align-items:center; justify-content:center; background:rgba(0,0,0,.8); backdrop-filter:blur(8px); }
.dsp-card { background:linear-gradient(180deg,rgba(20,14,0,.98),rgba(8,5,0,.97)); border:2px solid rgba(255,204,0,.55); border-radius:24px; padding:28px 24px; text-align:center; max-width:320px; width:90%; box-shadow:0 0 40px rgba(255,204,0,.12),0 24px 64px rgba(0,0,0,.8); }
.dsp-fire { font-size:64px; animation:fireShake .4s ease-in-out infinite alternate; display:block; margin-bottom:8px; }
.dsp-days { font-family:var(--ff-head); font-size:56px; font-weight:900; color:var(--gold); line-height:1; }
.dsp-lbl { font-size:14px; color:var(--t2); font-weight:700; margin-bottom:20px; }

/* ══ PET ROOM THEMES ══ */
.theme-row { display:flex; gap:7px; padding:6px 14px 8px; overflow-x:auto; scrollbar-width:none; }
.theme-row::-webkit-scrollbar { display:none; }
.theme-chip { flex-shrink:0; padding:5px 13px; border-radius:20px; font-size:10px; font-weight:800; cursor:pointer; border:1.5px solid rgba(255,255,255,.1); color:var(--t3); transition:all .14s; white-space:nowrap; }
.theme-chip.on { border-color:var(--green); color:var(--green); background:rgba(0,255,136,.08); }
.theme-chip:active { transform:scale(.9); }
.t-dark .pet-stage-bg { background:radial-gradient(ellipse at 50% 70%,rgba(0,255,136,.12),transparent 70%) !important; }
.t-space .pet-stage-bg { background:radial-gradient(ellipse at 50% 50%,rgba(100,60,220,.35),rgba(0,0,20,.95) 75%) !important; }
.t-space { background:radial-gradient(ellipse at 50% 0%,rgba(60,0,140,.2),var(--bg)) !important; }
.t-beach .pet-stage-bg { background:linear-gradient(180deg,rgba(20,120,220,.25),rgba(255,180,60,.18)) !important; }
.t-beach { background:linear-gradient(180deg,rgba(0,100,200,.07),rgba(255,200,0,.04),var(--bg)) !important; }
.t-forest .pet-stage-bg { background:radial-gradient(ellipse at 50% 80%,rgba(0,140,50,.35),rgba(0,50,10,.85) 80%) !important; }
.t-forest { background:radial-gradient(ellipse at 50% 0%,rgba(0,100,30,.14),var(--bg)) !important; }
.t-gaming .pet-stage-bg { background:radial-gradient(ellipse at 40% 60%,rgba(255,0,120,.25),rgba(0,0,50,.92) 75%) !important; }
.t-gaming { background:linear-gradient(135deg,rgba(100,0,255,.06),rgba(255,0,100,.04),var(--bg)) !important; }
/* ══ EVOLUTION CUTSCENE ══ */
#evolCutscene { position:fixed; inset:0; z-index:9500; display:none; flex-direction:column; align-items:center; justify-content:center; pointer-events:none; }
#evolCutscene.show { display:flex; }
#evolCutscene::before { content:''; position:absolute; inset:0; background:radial-gradient(circle,rgba(0,255,136,.25),rgba(0,0,0,.95)); animation:evolBg 2.8s ease-in-out forwards; }
@keyframes evolBg { 0%{opacity:0;} 20%{opacity:1;} 75%{opacity:1;} 100%{opacity:0;} }
.evol-em { font-size:110px; z-index:1; animation:evolBounce .55s cubic-bezier(.34,1.56,.64,1) infinite alternate, evolFadeIn 2.8s ease-in-out forwards; }
@keyframes evolBounce { from{transform:scale(.88) rotate(-6deg);} to{transform:scale(1.12) rotate(6deg);} }
@keyframes evolFadeIn { 0%{opacity:0;transform:scale(0);} 20%{opacity:1;transform:scale(1);} 75%{opacity:1;} 100%{opacity:0;} }
.evol-title { font-family:var(--ff-head); font-size:30px; font-weight:900; color:var(--green); text-shadow:0 0 50px var(--green); z-index:1; margin-top:18px; animation:evolFadeIn 2.8s ease-in-out .2s forwards; }
.evol-sub { font-size:16px; color:var(--gold); font-weight:800; z-index:1; margin-top:6px; animation:evolFadeIn 2.8s ease-in-out .4s forwards; }
/* ══ FLASH REACTIONS ══ */
.react-strip { display:flex; gap:0; background:rgba(0,0,0,.55); backdrop-filter:blur(10px); border-top:1px solid rgba(255,255,255,.05); }
.react-btn { flex:1; display:flex; flex-direction:column; align-items:center; gap:2px; padding:7px 2px; cursor:pointer; transition:background .1s; border:none; background:none; }
.react-btn:active { background:rgba(255,255,255,.06); }
.react-ico { font-size:19px; transition:transform .15s; }
.react-cnt { font-size:8px; font-weight:800; color:rgba(255,255,255,.5); }
.react-btn.hit .react-ico { transform:scale(1.4); animation:reactPop .3s cubic-bezier(.34,1.56,.64,1); }
@keyframes reactPop { 0%{transform:scale(0);} 60%{transform:scale(1.6);} 100%{transform:scale(1.2);} }
/* ══ EXPLORE FEED ══ */
.explore-grid { display:grid; grid-template-columns:1fr 1fr; gap:2px; padding:2px; }
.explore-tile { position:relative; aspect-ratio:.6; background:rgba(10,4,22,.9); overflow:hidden; cursor:pointer; border-radius:8px; }
.explore-tile-em { position:absolute; inset:0; display:flex; align-items:center; justify-content:center; font-size:55px; opacity:.18; }
.explore-tile-grad { position:absolute; bottom:0; left:0; right:0; padding:8px 7px; background:linear-gradient(transparent,rgba(0,0,0,.9)); }
.explore-tile-user { font-size:10px; font-weight:800; color:#fff; }
.explore-tile-stats { font-size:9px; color:rgba(255,255,255,.5); margin-top:1px; }
.explore-live-badge { position:absolute; top:6px; left:6px; background:var(--red); color:#fff; font-size:8px; font-weight:900; padding:2px 6px; border-radius:5px; animation:liveBlink .8s infinite; }
@keyframes liveBlink { 0%,100%{opacity:1;} 50%{opacity:.5;} }
/* ══ KARMA KATCH ══ */
#katchCanvas { width:100%; height:300px; display:block; border-radius:14px; background:linear-gradient(180deg,#000818,#000); }
.katch-hud { display:flex; justify-content:space-between; padding:10px 14px 6px; background:linear-gradient(180deg,rgba(0,4,22,.96),rgba(0,2,14,.8)); border-radius:16px; border:1px solid rgba(0,220,204,.1); margin-bottom:6px; }
.katch-sv { font-family:var(--ff-head); font-size:22px; font-weight:900; color:var(--teal); }
.katch-sl { font-size:9px; color:var(--t3); font-weight:700; margin-top:1px; }
.katch-wrap { position:relative; border-radius:16px; overflow:hidden; }
.katch-wrap::after { content:''; position:absolute; inset:0; border:1.5px solid rgba(0,220,204,.2); border-radius:16px; pointer-events:none; z-index:6; }
.katch-overlay { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; background:linear-gradient(180deg,rgba(0,4,22,.88),rgba(0,0,0,.82)); backdrop-filter:blur(6px); border-radius:16px; z-index:5; }
/* KATCH overlay inner content */
.katch-overlay-em { font-size:64px; animation:achDrop .5s cubic-bezier(.34,1.56,.64,1); filter:drop-shadow(0 0 20px var(--teal)); }
.katch-overlay-title { font-family:var(--ff-head); font-size:22px; font-weight:900; background:linear-gradient(135deg,var(--teal),var(--blue)); -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text; margin:8px 0 4px; }
.katch-overlay-sub { font-size:11px; color:rgba(255,255,255,.5); text-align:center; margin-bottom:16px; }
/* ══ RUNNER POWERUPS ══ */
.runner-pup-hud { display:flex; gap:5px; padding:2px 14px 5px; min-height:22px; }
.pup-chip { font-size:9px; font-weight:900; padding:2px 7px; border-radius:8px; animation:pupGlow .5s ease-in-out infinite alternate; }
.pup-chip.mag { background:rgba(68,136,255,.2); color:var(--blue); }
.pup-chip.shd { background:rgba(0,255,136,.2); color:var(--green); }
.pup-chip.spd { background:rgba(255,204,0,.2); color:var(--gold); }
@keyframes pupGlow { from{opacity:.6;} to{opacity:1;} }
/* ══ BATTLE ULTRA ══ */
#b2UltraFlash { position:absolute; inset:0; display:none; z-index:30; border-radius:14px; align-items:center; justify-content:center; pointer-events:none; }
#b2UltraFlash.show { display:flex; animation:ultraAnim .7s ease-in-out forwards; }
@keyframes ultraAnim { 0%{background:rgba(255,0,127,.0);} 20%{background:rgba(255,0,127,.35);} 60%{background:rgba(255,0,127,.2);} 100%{background:rgba(255,0,127,.0);} }
#b2UltraTxt { font-family:var(--ff-head); font-size:38px; font-weight:900; color:#FF007F; text-shadow:0 0 40px #FF007F,0 0 80px #FF007F; animation:ultraPop .4s cubic-bezier(.34,1.56,.64,1); }
@keyframes ultraPop { from{transform:scale(0) rotate(-12deg);} to{transform:scale(1);} }

















/* ══ ROUND 100 MEGA MILESTONE ══ */
.r100-overlay { position:fixed;inset:0;z-index:9800;background:radial-gradient(ellipse at 50% 40%,rgba(30,10,80,.98),rgba(0,0,0,.99) 80%);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;opacity:0;pointer-events:none;transition:opacity .6s; }
.r100-overlay.show { opacity:1;pointer-events:all; }
.r100-canvas { position:absolute;inset:0;pointer-events:none; }
.r100-badge { width:120px;height:120px;border-radius:50%;background:linear-gradient(135deg,var(--gold),#fff,var(--gold));display:flex;align-items:center;justify-content:center;font-size:52px;box-shadow:0 0 50px rgba(255,204,0,.6),0 0 100px rgba(255,204,0,.2);animation:r100Pulse 1.5s ease-in-out infinite alternate; }
@keyframes r100Pulse { from{transform:scale(1);box-shadow:0 0 40px rgba(255,204,0,.5)} to{transform:scale(1.06);box-shadow:0 0 70px rgba(255,204,0,.8)} }
.r100-title { font:900 36px/1 var(--ff-head);text-align:center;letter-spacing:.12em;background:linear-gradient(135deg,var(--gold),#fff,var(--gold));-webkit-background-clip:text;-webkit-text-fill-color:transparent; }
.r100-sub { font:700 13px/1 var(--ff-head);color:rgba(255,255,255,.5);letter-spacing:.25em;text-align:center; }
.r100-rewards { display:flex;gap:12px;flex-wrap:wrap;justify-content:center;margin-top:6px; }
.r100-reward-chip { padding:8px 16px;border-radius:20px;font:800 12px/1 var(--ff-head);letter-spacing:.04em;border:1.5px solid; }
.r100-claim-btn { padding:16px 48px;background:linear-gradient(135deg,var(--gold),#ff8844);border:none;border-radius:16px;font:900 16px/1 var(--ff-head);color:#000;cursor:pointer;letter-spacing:.08em;box-shadow:0 0 30px rgba(255,204,0,.5);transition:all .2s;margin-top:8px; }
.r100-claim-btn:active { transform:scale(.96); }
.r100-claim-btn:disabled { opacity:.5;pointer-events:none; }

/* ══ PET CARD SHOWCASE ══ */
.showcase-panel { position:fixed;inset:0;z-index:867;background:#000;transform:translateY(100%);transition:transform .4s cubic-bezier(.32,.72,0,1);overflow:hidden;display:flex;flex-direction:column; }
.showcase-panel.open { transform:translateY(0); }
.showcase-hdr { display:flex;align-items:center;gap:10px;padding:calc(var(--sat)+14px) 16px 12px;border-bottom:1px solid rgba(255,255,255,.08); }
.showcase-scroll { flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;align-items:center;gap:14px;padding-bottom:100px; }
/* the card itself */
.pet-showcase-card { width:100%;max-width:320px;border-radius:22px;padding:22px;position:relative;overflow:hidden;border:2px solid;min-height:440px;display:flex;flex-direction:column;gap:12px; }
.psc-bg-circles { position:absolute;inset:0;pointer-events:none; }
.psc-circle { position:absolute;border-radius:50%;opacity:.08; }
.psc-header { display:flex;align-items:center;justify-content:space-between;z-index:1;position:relative; }
.psc-brand { font:900 9px/1 var(--ff-head);letter-spacing:.2em;opacity:.5; }
.psc-season-chip { padding:3px 10px;border-radius:10px;font:700 9px/1 var(--ff-head);letter-spacing:.06em;border:1px solid;opacity:.7; }
.psc-pet-center { display:flex;flex-direction:column;align-items:center;gap:8px;z-index:1;position:relative;padding:10px 0; }
.psc-pet-ico { font-size:72px;line-height:1;filter:drop-shadow(0 0 24px currentColor); }
.psc-pet-name { font:900 22px/1 var(--ff-head);letter-spacing:.06em; }
.psc-pet-stage { font:700 11px/1 var(--ff-body);opacity:.6;letter-spacing:.08em; }
.psc-stats-grid { display:grid;grid-template-columns:repeat(3,1fr);gap:8px;z-index:1;position:relative; }
.psc-stat { background:rgba(0,0,0,.3);border-radius:10px;padding:8px 6px;display:flex;flex-direction:column;align-items:center;gap:3px;border:1px solid rgba(255,255,255,.1); }
.psc-stat-v { font:800 16px/1 var(--ff-head); }
.psc-stat-l { font:500 8px/1 var(--ff-body);color:rgba(255,255,255,.45);letter-spacing:.05em; }
.psc-bond-section { z-index:1;position:relative; }
.psc-bond-row { display:flex;align-items:center;gap:8px;font:700 11px/1 var(--ff-body); }
.psc-bond-bar { flex:1;height:6px;background:rgba(255,255,255,.1);border-radius:3px;overflow:hidden; }
.psc-bond-fill { height:100%;border-radius:3px;transition:width .4s; }
.psc-footer { display:flex;align-items:center;justify-content:space-between;z-index:1;position:relative;padding-top:6px;border-top:1px solid rgba(255,255,255,.1);font:600 9px/1 var(--ff-body);opacity:.45;letter-spacing:.05em; }
/* style selector */
.showcase-style-row { display:flex;gap:8px;width:100%;max-width:320px;overflow-x:auto;padding-bottom:4px; }
.showcase-style-chip { flex-shrink:0;padding:6px 14px;border-radius:20px;border:1.5px solid rgba(255,255,255,.15);font:700 10px/1 var(--ff-head);color:rgba(255,255,255,.6);cursor:pointer;white-space:nowrap;transition:all .18s; }
.showcase-style-chip.sel { border-color:var(--green);color:var(--green);background:rgba(0,255,136,.06); }

/* ══ GACHA PULL ══ */
.gacha-panel { position:fixed;inset:0;z-index:866;background:radial-gradient(ellipse at 50% 30%,rgba(14,4,40,.99),#000 75%);transform:translateY(100%);transition:transform .4s cubic-bezier(.32,.72,0,1);overflow:hidden;display:flex;flex-direction:column; }
.gacha-panel.open { transform:translateY(0); }
.gacha-hdr { display:flex;align-items:center;gap:10px;padding:calc(var(--sat)+14px) 16px 12px;border-bottom:1px solid rgba(170,102,255,.15); }
.gacha-hdr-title { font:900 18px/1 var(--ff-head);background:linear-gradient(135deg,var(--purple),var(--pink),var(--gold));-webkit-background-clip:text;-webkit-text-fill-color:transparent;letter-spacing:.1em;flex:1; }
.gacha-scroll { flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;align-items:center;gap:14px; }
.gacha-pity-bar-bg { width:100%;max-width:320px;height:8px;background:rgba(255,255,255,.08);border-radius:4px;overflow:hidden; }
.gacha-pity-fill { height:100%;background:linear-gradient(90deg,var(--purple),var(--pink));border-radius:4px;transition:width .4s; }
.gacha-pity-txt { font:600 10px/1 var(--ff-body);color:rgba(255,255,255,.4);text-align:center; }
.gacha-banner { width:100%;max-width:320px;background:linear-gradient(135deg,rgba(30,10,70,.8),rgba(50,10,40,.8));border:1.5px solid rgba(170,102,255,.3);border-radius:16px;padding:16px;display:flex;flex-direction:column;align-items:center;gap:8px; }
.gacha-pool-preview { display:flex;gap:6px;flex-wrap:wrap;justify-content:center; }
.gacha-pool-chip { padding:4px 10px;border-radius:10px;font:700 11px/1 var(--ff-body);border:1px solid; }
.gacha-pull-btns { display:flex;gap:10px;width:100%;max-width:320px; }
.gacha-pull-btn { flex:1;padding:14px 8px;border:none;border-radius:14px;font:800 13px/1.3 var(--ff-head);cursor:pointer;transition:all .18s;display:flex;flex-direction:column;align-items:center;gap:3px; }
.gacha-pull-btn:active { transform:scale(.96); }
.gacha-pull-btn.x1 { background:linear-gradient(135deg,rgba(68,136,255,.3),rgba(170,102,255,.3));border:1.5px solid rgba(170,102,255,.4);color:#fff; }
.gacha-pull-btn.x10 { background:linear-gradient(135deg,rgba(255,51,119,.25),rgba(170,102,255,.35));border:1.5px solid rgba(255,51,119,.5);color:#fff; }
.gacha-pull-btn:disabled { opacity:.4;pointer-events:none; }
/* flip card */
.gacha-reveal-area { position:fixed;inset:0;z-index:9600;background:rgba(0,0,0,.92);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;opacity:0;pointer-events:none;transition:opacity .3s; }
.gacha-reveal-area.show { opacity:1;pointer-events:all; }
.gacha-cards-row { display:flex;gap:8px;flex-wrap:wrap;justify-content:center;max-width:360px; }
.gacha-card { width:76px;height:104px;border-radius:12px;perspective:600px;cursor:pointer; }
.gacha-card-inner { width:100%;height:100%;position:relative;transform-style:preserve-3d;transition:transform .6s cubic-bezier(.4,0,.2,1); }
.gacha-card.flipped .gacha-card-inner { transform:rotateY(180deg); }
.gacha-card-face, .gacha-card-back { position:absolute;inset:0;border-radius:12px;backface-visibility:hidden;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px; }
.gacha-card-face { background:linear-gradient(135deg,rgba(60,20,120,.9),rgba(30,10,60,.9));border:1.5px solid rgba(170,102,255,.4); }
.gacha-card-face-ico { font-size:22px;line-height:1;animation:gachaFacePulse 1.5s ease-in-out infinite alternate; }
@keyframes gachaFacePulse { from{opacity:.5;transform:scale(.95)} to{opacity:1;transform:scale(1.05)} }
.gacha-card-back { transform:rotateY(180deg); }
.gacha-card-back.r-legendary { background:linear-gradient(135deg,rgba(255,204,0,.2),rgba(255,136,0,.3));border:2px solid var(--gold);box-shadow:0 0 20px rgba(255,204,0,.4); }
.gacha-card-back.r-epic { background:linear-gradient(135deg,rgba(170,102,255,.2),rgba(255,51,119,.2));border:2px solid var(--purple);box-shadow:0 0 16px rgba(170,102,255,.4); }
.gacha-card-back.r-rare { background:linear-gradient(135deg,rgba(68,136,255,.2),rgba(0,221,204,.15));border:1.5px solid var(--blue);box-shadow:0 0 10px rgba(68,136,255,.3); }
.gacha-card-back.r-common { background:rgba(255,255,255,.06);border:1.5px solid rgba(255,255,255,.15); }
.gacha-card-back-ico { font-size:26px;line-height:1; }
.gacha-card-back-name { font:700 8px/1.2 var(--ff-head);color:#fff;text-align:center;padding:0 4px; }
.gacha-card-back-val { font:800 9px/1 var(--ff-body);color:var(--green); }
.gacha-pull-result-txt { font:800 14px/1.4 var(--ff-body);color:rgba(255,255,255,.7);text-align:center; }
.gacha-history { width:100%;max-width:320px; }
.gacha-hist-row { display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid rgba(255,255,255,.05);font:500 11px/1 var(--ff-body);color:rgba(255,255,255,.5); }
.gacha-hist-rarity { width:8px;height:8px;border-radius:50%;flex-shrink:0; }

/* ══ EVOLUTION CINEMATIC ══ */
.evol-cine { position:fixed;inset:0;z-index:9500;background:radial-gradient(ellipse at 50% 50%,rgba(170,102,255,.3),rgba(0,0,0,.97) 60%);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;opacity:0;pointer-events:none;transition:opacity .5s; }
.evol-cine.show { opacity:1;pointer-events:all; }
.evol-cine-ring { width:160px;height:160px;border-radius:50%;border:3px solid rgba(170,102,255,.6);display:flex;align-items:center;justify-content:center;position:relative;box-shadow:0 0 40px rgba(170,102,255,.4),inset 0 0 40px rgba(170,102,255,.1); }
.evol-cine-ring::before { content:'';position:absolute;inset:-8px;border-radius:50%;border:2px solid rgba(255,204,0,.3);animation:evolRingPulse 1.2s ease-in-out infinite; }
@keyframes evolRingPulse { 0%,100%{transform:scale(1);opacity:.3} 50%{transform:scale(1.08);opacity:.8} }
.evol-pet-old { font-size:48px;line-height:1;position:absolute;animation:evolFadeOut 1.2s .3s ease-in-out both; }
@keyframes evolFadeOut { 0%{opacity:1;transform:scale(1)} 100%{opacity:0;transform:scale(2) rotate(20deg)} }
.evol-pet-new { font-size:72px;line-height:1;animation:evolBurst 1s 1.2s cubic-bezier(.34,1.56,.64,1) both;filter:drop-shadow(0 0 30px rgba(170,102,255,.8)); }
@keyframes evolBurst { 0%{opacity:0;transform:scale(0) rotate(-20deg)} 100%{opacity:1;transform:scale(1) rotate(0deg)} }
.evol-title { font:900 13px/1 var(--ff-head);color:rgba(255,255,255,.5);letter-spacing:.2em;text-align:center;animation:evolSlideUp .6s 1.8s both; }
.evol-name { font:900 28px/1 var(--ff-head);text-align:center;letter-spacing:.08em;animation:evolSlideUp .6s 2s cubic-bezier(.34,1.56,.64,1) both; }
.evol-level { font:800 14px/1 var(--ff-body);color:rgba(255,255,255,.5);text-align:center;animation:evolSlideUp .5s 2.2s both; }
@keyframes evolSlideUp { 0%{opacity:0;transform:translateY(20px)} 100%{opacity:1;transform:translateY(0)} }
.evol-particles { position:absolute;inset:0;pointer-events:none; }

/* ══ WAVE ARENA ══ */
.wa-panel { padding:8px 12px 80px;display:flex;flex-direction:column;gap:8px; }
.wa-hud { display:grid;grid-template-columns:repeat(4,1fr);gap:6px;padding:4px 0; }
.wa-stat { background:rgba(255,255,255,.04);border-radius:10px;padding:8px 4px;display:flex;flex-direction:column;align-items:center;gap:2px; }
.wa-stat-v { font:800 16px/1 var(--ff-head); }
.wa-stat-l { font:500 9px/1 var(--ff-body);color:rgba(255,255,255,.4);letter-spacing:.04em; }
.wa-enemy-card { background:rgba(255,68,85,.07);border:1.5px solid rgba(255,68,85,.2);border-radius:14px;padding:14px;display:flex;flex-direction:column;gap:8px; }
.wa-enemy-row { display:flex;align-items:center;gap:10px; }
.wa-enemy-ico { font-size:40px;line-height:1;animation:waBob 1.2s ease-in-out infinite alternate; }
@keyframes waBob { from{transform:translateY(-4px)} to{transform:translateY(4px)} }
.wa-enemy-name { font:900 15px/1 var(--ff-head);color:var(--red); }
.wa-enemy-sub { font:600 10px/1 var(--ff-body);color:rgba(255,255,255,.45);margin-top:3px; }
.wa-hp-bg { height:10px;background:rgba(255,255,255,.08);border-radius:5px;overflow:hidden; }
.wa-hp-fill { height:100%;background:linear-gradient(90deg,var(--red),#ff8844);border-radius:5px;transition:width .3s; }
.wa-moves { display:grid;grid-template-columns:1fr 1fr;gap:8px; }
.wa-move { padding:12px 8px;border-radius:12px;border:1.5px solid rgba(255,255,255,.12);font:700 11px/1.3 var(--ff-head);color:#fff;cursor:pointer;text-align:center;transition:all .15s;background:rgba(255,255,255,.04); }
.wa-move:active { transform:scale(.95); }
.wa-move.power { border-color:rgba(255,68,85,.4);background:rgba(255,68,85,.1); }
.wa-move.magic { border-color:rgba(170,102,255,.4);background:rgba(170,102,255,.1); }
.wa-move.heal  { border-color:rgba(0,255,136,.4);background:rgba(0,255,136,.1); }
.wa-move.swift { border-color:rgba(255,204,0,.4);background:rgba(255,204,0,.1); }
.wa-move.disabled { opacity:.35;pointer-events:none; }
.wa-log { background:rgba(0,0,0,.3);border-radius:10px;padding:10px 12px;font:500 11px/1.6 var(--ff-body);color:rgba(255,255,255,.6);min-height:44px; }
.wa-you-hp-row { display:flex;align-items:center;gap:8px;font:700 11px/1 var(--ff-body); }
.wa-you-hp-bg { flex:1;height:8px;background:rgba(255,255,255,.08);border-radius:4px;overflow:hidden; }
.wa-you-hp-fill { height:100%;background:linear-gradient(90deg,var(--green),var(--teal));border-radius:4px;transition:width .3s; }
.wa-wave-badge { display:inline-flex;align-items:center;gap:4px;padding:4px 12px;background:rgba(255,204,0,.15);border:1px solid rgba(255,204,0,.3);border-radius:20px;font:800 12px/1 var(--ff-head);color:var(--gold); }
.wa-result { text-align:center;padding:20px 10px;display:flex;flex-direction:column;align-items:center;gap:8px; }
.wa-result-ico { font-size:56px;line-height:1;animation:waBob 1.2s ease-in-out infinite alternate; }
.wa-result-title { font:900 22px/1 var(--ff-head);background:linear-gradient(135deg,var(--gold),#fff);-webkit-background-clip:text;-webkit-text-fill-color:transparent; }
.wa-result-rewards { font:600 12px/1.8 var(--ff-body);color:rgba(255,255,255,.7); }

/* ══ TROPHY ROOM ══ */
.trophy-shelf { display:grid; grid-template-columns:repeat(4,1fr); gap:8px; padding:0 14px 14px; }
.trophy-item { background:linear-gradient(180deg,rgba(10,4,22,.96),rgba(4,2,12,.94)); border:1.5px solid rgba(255,255,255,.07); border-radius:14px; padding:9px 4px; text-align:center; transition:all .18s; cursor:pointer; box-shadow:0 3px 12px rgba(0,0,0,.4); }
.trophy-item:active { transform:scale(.9); }
.trophy-item.gold { border-color:rgba(255,204,0,.4); background:rgba(20,14,0,.95); box-shadow:0 4px 18px rgba(255,204,0,.1); }
.trophy-item.green { border-color:rgba(0,255,136,.4); background:rgba(0,10,4,.95); box-shadow:0 4px 18px rgba(0,255,136,.1); }
.trophy-item.blue { border-color:rgba(68,136,255,.4); background:rgba(0,4,14,.95); box-shadow:0 4px 18px rgba(68,136,255,.1); }
.trophy-item.locked { opacity:.22; filter:grayscale(1); }
.trophy-em { font-size:22px; display:block; margin-bottom:3px; }
.trophy-lbl { font-size:7.5px; font-weight:800; color:var(--t3); line-height:1.3; }
/* ══ DAILY TOURNAMENT ══ */
.tourn-card { margin:0 14px 14px; background:linear-gradient(135deg,rgba(255,204,0,.07),rgba(255,136,0,.04)); border:1.5px solid rgba(255,204,0,.3); border-radius:18px; padding:14px 14px 8px; }
.tourn-hdr { display:flex; align-items:center; justify-content:space-between; margin-bottom:10px; }
.tourn-title { font-family:var(--ff-head); font-size:14px; font-weight:900; color:var(--gold); }
.tourn-cd { font-size:10px; font-weight:800; color:var(--t2); background:rgba(10,4,22,.8); padding:3px 8px; border-radius:8px; border:1px solid rgba(255,255,255,.07); }
.tourn-row { display:flex; align-items:center; gap:8px; padding:5px 0; border-bottom:1px solid var(--line); }
.tourn-row:last-child { border:none; padding-bottom:0; }
.tourn-rk { font-family:var(--ff-head); font-size:14px; font-weight:900; width:22px; text-align:center; flex-shrink:0; }
.tourn-nm { flex:1; font-size:12px; font-weight:700; }
.tourn-sc { font-size:12px; font-weight:800; color:var(--gold); flex-shrink:0; }
.tourn-kc { font-size:9px; color:var(--pink,#ff3377); font-weight:900; flex-shrink:0; margin-left:4px; }
/* ══ PREMIUM BADGE ══ */
.prem-badge { display:inline-flex; align-items:center; gap:3px; background:linear-gradient(135deg,var(--gold),#ff8c00); color:#000; font-size:8px; font-weight:900; padding:2px 6px; border-radius:7px; vertical-align:middle; margin-left:4px; letter-spacing:.3px; }
/* ══ STEP TRACKER ══ */
.step-card { margin:0 14px 12px; background:linear-gradient(180deg,rgba(0,6,18,.97),rgba(0,2,10,.95)); border:1px solid rgba(0,255,136,.1); border-radius:18px; padding:14px; box-shadow:0 4px 20px rgba(0,0,0,.5); }
.step-hdr { display:flex; align-items:center; justify-content:space-between; margin-bottom:8px; }
.step-ttl { font-family:var(--ff-head); font-size:13px; font-weight:900; }
.step-sync { font-size:10px; color:var(--blue); font-weight:800; cursor:pointer; }
.step-num { font-family:var(--ff-head); font-size:38px; font-weight:900; color:var(--green); text-align:center; line-height:1; text-shadow:0 0 20px rgba(0,255,136,.3); }
.step-goal { font-size:10px; color:var(--t3); text-align:center; margin:2px 0 10px; }
.step-track { height:7px; background:rgba(255,255,255,.06); border-radius:100px; overflow:hidden; margin-bottom:8px; }
.step-fill { height:100%; background:linear-gradient(90deg,var(--green),var(--teal)); border-radius:100px; transition:width .8s cubic-bezier(.34,1.56,.64,1); box-shadow:0 0 8px rgba(0,255,136,.4); }
.step-rwds { display:flex; gap:5px; }
.step-rwd { flex:1; text-align:center; background:rgba(10,4,22,.8); border-radius:9px; padding:5px 3px; font-size:8px; color:var(--t3); font-weight:700; border:1px solid rgba(255,255,255,.06); }
.step-rwd.done { background:rgba(0,255,136,.08); color:var(--green); border:1px solid rgba(0,255,136,.2); }
/* ══ DM ══ */
.dm-item { display:flex; align-items:center; gap:10px; padding:10px 6px; border-bottom:1px solid rgba(255,255,255,.05); cursor:pointer; border-radius:12px; transition:background .12s; }
.dm-item:active { background:rgba(255,255,255,.03); }
.dm-item:last-child { border:none; }
.dm-ava { width:40px; height:40px; border-radius:50%; background:rgba(14,6,30,.8); border:1.5px solid rgba(255,51,119,.2); display:flex; align-items:center; justify-content:center; font-size:22px; flex-shrink:0; }
.dm-info { flex:1; min-width:0; }
.dm-user { font-size:13px; font-weight:800; font-family:var(--ff-head); }
