/* ══ RANDOM ENCOUNTER ══ */
.re-card { position:fixed;bottom:calc(100px + var(--sab));left:14px;right:14px;z-index:600;border-radius:20px;padding:14px 16px;display:flex;align-items:center;gap:12px;transform:translateY(120px);opacity:0;transition:all .45s cubic-bezier(.34,1.56,.64,1);pointer-events:none; }
