/* ══ KARMA RANK SYSTEM ══ */
.rank-badge { display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;font-size:10px;font-weight:900;letter-spacing:.5px;border:1px solid transparent; }
