/* ══ PET BOND SYSTEM ══ */
.bond-section { margin-top:14px;padding:14px;border-radius:16px;background:linear-gradient(160deg,rgba(255,51,119,.06),rgba(170,102,255,.04));border:1.5px solid rgba(255,51,119,.15); }
.bond-hdr { display:flex;align-items:center;justify-content:space-between;margin-bottom:8px; }
.bond-tier-name { font-family:var(--ff-head);font-size:12px;font-weight:900; }
.bond-pts { font-size:9px;font-weight:700;color:rgba(255,255,255,.4); }
.bond-dots { display:flex;gap:5px;margin-bottom:8px; }
.bond-dot { width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,.1);transition:all .3s; }
.bond-dot.filled { background:var(--bond-col,#ff3377);box-shadow:0 0 8px var(--bond-col,#ff3377); }
.bond-bar-bg { height:6px;background:rgba(255,255,255,.07);border-radius:3px;overflow:hidden; }
.bond-bar-fill { height:100%;border-radius:3px;background:linear-gradient(90deg,var(--bond-col,#ff3377),#aa66ff);transition:width .8s cubic-bezier(.34,1.56,.64,1); }
.bond-perk { font-size:9px;color:rgba(255,255,255,.45);margin-top:6px;line-height:1.5; }
.bond-perk span { color:var(--bond-col,#ff3377);font-weight:800; }
/* Bond level up splash */
.bond-splash { position:fixed;inset:0;z-index:902;display:flex;align-items:center;justify-content:center;pointer-events:none;opacity:0;transition:opacity .4s; }
.bond-splash.show { opacity:1;pointer-events:all; }
.bond-splash-canvas { position:absolute;inset:0;width:100%;height:100%; }
.bond-splash-card { position:relative;z-index:1;border-radius:32px;padding:40px 32px;text-align:center;background:linear-gradient(160deg,rgba(36,4,24,.97),rgba(10,2,20,.98));border:2px solid rgba(255,51,119,.3);box-shadow:0 0 80px rgba(255,51,119,.2),0 0 160px rgba(170,102,255,.1);width:82vw;max-width:320px; }
.bond-splash-ico { font-size:56px;display:block;margin-bottom:12px;animation:bondPulse 1.5s ease-in-out infinite; }
@keyframes bondPulse { 0%,100%{transform:scale(1);filter:drop-shadow(0 0 12px rgba(255,51,119,.5))} 50%{transform:scale(1.12);filter:drop-shadow(0 0 24px rgba(255,51,119,.8))} }
