.bond-splash-title { font-family:var(--ff-head);font-size:28px;font-weight:900;margin-bottom:4px; }
.bond-splash-tier { font-family:var(--ff-head);font-size:20px;font-weight:900;margin-bottom:16px; }
.bond-splash-perk { font-size:13px;color:rgba(255,255,255,.7);line-height:1.6;background:rgba(255,51,119,.08);border-radius:14px;padding:12px 16px;border:1px solid rgba(255,51,119,.15);margin-bottom:20px; }
.bond-splash-perk strong { color:#ff3377; }
.bond-splash-btn { background:linear-gradient(135deg,#ff3377,#aa66ff);border:none;border-radius:24px;padding:14px 40px;font-family:var(--ff-head);font-size:14px;font-weight:900;color:#fff;cursor:pointer;width:100%; }

/* ══ COSMIC WEATHER SYSTEM ══ */
.gwx-bar { position:absolute;top:calc(var(--sat)+52px);left:0;right:0;z-index:199;display:flex;align-items:center;justify-content:center;padding:5px 16px;pointer-events:none;transition:opacity .4s; }
.gwx-inner { display:flex;align-items:center;gap:8px;padding:4px 14px 4px 8px;border-radius:20px;background:linear-gradient(135deg,rgba(0,0,0,.72),rgba(8,4,20,.8));border:1px solid rgba(255,255,255,.08);backdrop-filter:blur(8px);transition:all .5s; }
.gwx-inner.pulse { animation:gwxPulse .8s ease-out; }
