.dcb-allclear-sub { font-size:12px;color:rgba(255,255,255,.5); }

/* ══ LIGHTNING REFLEX GAME ══ */
.reflex-wrap { padding:10px 0; }
.reflex-hud { display:flex;justify-content:space-around;align-items:center;padding:10px 16px;background:linear-gradient(135deg,rgba(4,8,28,.92),rgba(2,4,14,.96));border-radius:16px;margin-bottom:10px;border:1.5px solid rgba(68,136,255,.15); }
.rfx-stat { text-align:center; }
.rfx-val { font-family:var(--ff-head);font-size:24px;font-weight:900; }
.rfx-lbl { font-size:9px;font-weight:700;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:.8px;margin-top:2px; }
.reflex-arena { position:relative;width:100%;aspect-ratio:1;background:radial-gradient(ellipse at 50% 50%,rgba(4,8,32,.96),rgba(2,2,14,.99));border-radius:20px;overflow:hidden;border:2px solid rgba(68,136,255,.15);cursor:crosshair;user-select:none; }
.reflex-arena-grid { position:absolute;inset:0;background-image:linear-gradient(rgba(68,136,255,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(68,136,255,.04) 1px,transparent 1px);background-size:40px 40px; }
.reflex-target { position:absolute;border-radius:50%;transform:translate(-50%,-50%) scale(0);transition:transform .12s cubic-bezier(.34,1.56,.64,1);cursor:pointer;display:flex;align-items:center;justify-content:center;touch-action:none; }
.reflex-target.show { transform:translate(-50%,-50%) scale(1); }
.reflex-target.hit { transform:translate(-50%,-50%) scale(1.5);opacity:0;transition:all .18s ease-out; }
.rfx-t-inner { border-radius:50%;animation:rfxPulse 1s ease-in-out infinite; }
@keyframes rfxPulse { 0%,100%{box-shadow:0 0 0 0 currentColor,0 0 16px currentColor} 50%{box-shadow:0 0 0 8px transparent,0 0 32px currentColor} }
.rfx-miss-ripple { position:absolute;border-radius:50%;border:2px solid rgba(255,68,85,.5);transform:translate(-50%,-50%) scale(0);animation:rfxMiss .4s ease-out forwards;pointer-events:none; }
@keyframes rfxMiss { 0%{transform:translate(-50%,-50%) scale(0);opacity:1} 100%{transform:translate(-50%,-50%) scale(3);opacity:0} }
.rfx-hit-num { position:absolute;font-family:var(--ff-head);font-size:18px;font-weight:900;pointer-events:none;animation:rfxNum .5s ease-out forwards; }
@keyframes rfxNum { 0%{transform:translate(-50%,-100%);opacity:1} 100%{transform:translate(-50%,-200%);opacity:0} }
.reflex-countdown { position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-family:var(--ff-head);font-size:80px;font-weight:900;pointer-events:none;animation:rfxCdown .6s cubic-bezier(.17,.67,.3,1.3) both; }
@keyframes rfxCdown { 0%{transform:scale(2);opacity:0} 50%{transform:scale(1);opacity:1} 100%{transform:scale(.8);opacity:0} }
.reflex-timer-bar { height:5px;background:rgba(255,255,255,.06);border-radius:3px;margin-bottom:8px;overflow:hidden; }
.reflex-timer-fill { height:100%;border-radius:3px;background:linear-gradient(90deg,var(--green),var(--blue));transition:width .1s linear; }
.reflex-result { text-align:center;padding:20px 0; }
.rfx-score-big { font-family:var(--ff-head);font-size:56px;font-weight:900;line-height:1; }
.rfx-grade { font-size:28px;font-weight:900;font-family:var(--ff-head);margin-top:8px; }
.rfx-grade-sub { font-size:12px;color:rgba(255,255,255,.5);margin-top:4px; }
.rfx-rewards-row { display:flex;justify-content:center;gap:14px;margin-top:16px; }
.rfx-rew { padding:8px 16px;border-radius:12px;background:rgba(255,255,255,.06);font-size:12px;font-weight:700; }
.rfx-stats-row { display:flex;justify-content:center;gap:20px;margin-top:12px; }
.rfx-rs { text-align:center; }
.rfx-rs-v { font-family:var(--ff-head);font-size:18px;font-weight:900; }
.rfx-rs-l { font-size:9px;color:rgba(255,255,255,.4);margin-top:2px; }
.rfx-daily-cd { font-size:10px;color:rgba(255,255,255,.3);margin-top:10px;text-align:center; }

/* ══ DAILY ACTIVITY HEATMAP ══ */
.act-heatmap-section { margin:0 0 16px;padding:14px;border-radius:20px;background:linear-gradient(160deg,rgba(6,2,16,.92),rgba(2,1,8,.96));border:1.5px solid rgba(255,255,255,.06); }
