/* ══ COMBO SURGE SCREEN ══ */
.combo-surge { position:fixed;inset:0;z-index:9000;pointer-events:none;display:flex;align-items:center;justify-content:center;overflow:hidden; }
.combo-surge-flash { position:absolute;inset:0;opacity:0; }
.combo-surge.fire5  .combo-surge-flash { background:radial-gradient(ellipse at 50% 50%,rgba(255,136,68,.25),transparent 70%); }
.combo-surge.fire10 .combo-surge-flash { background:radial-gradient(ellipse at 50% 50%,rgba(255,204,0,.35),transparent 65%); }
.combo-surge.fire15 .combo-surge-flash { background:radial-gradient(ellipse at 50% 50%,rgba(255,51,119,.4),transparent 60%); }
.combo-surge.fire20 .combo-surge-flash { background:radial-gradient(ellipse at 50% 50%,rgba(170,102,255,.5),transparent 55%); }
.combo-surge.run { animation:surgeFade .7s ease-out forwards; }
.combo-surge.run .combo-surge-flash { animation:surgeFlash .5s ease-out forwards; }
@keyframes surgeFade { 0%{opacity:1} 80%{opacity:1} 100%{opacity:0} }
@keyframes surgeFlash { 0%{opacity:0} 15%{opacity:1} 100%{opacity:0} }
