@keyframes surgeTxt { 0%{transform:scale(0) rotate(-8deg);opacity:0} 30%{transform:scale(1.1) rotate(2deg);opacity:1} 60%{transform:scale(1);opacity:1} 85%{transform:scale(1.05);opacity:1} 100%{transform:scale(0);opacity:0} }
.csn-combo { font-size:72px;line-height:1;display:block; }
.csn-label { font-size:20px;letter-spacing:3px;display:block;margin-top:6px; }
.csn-xtag { font-size:14px;letter-spacing:2px;display:block;margin-top:4px;opacity:.7; }
/* Chromatic aberration via multiple text-shadows */
.combo-surge.fire5  .csn-combo { color:#ff8844;text-shadow:-3px 0 rgba(255,136,68,.5),3px 0 rgba(255,136,68,.3); }
.combo-surge.fire10 .csn-combo { color:#ffcc00;text-shadow:-3px 0 rgba(255,0,0,.4),3px 0 rgba(0,0,255,.4),0 0 30px rgba(255,204,0,.5); }
.combo-surge.fire15 .csn-combo { color:#ff3377;text-shadow:-4px 0 rgba(255,0,0,.5),4px 0 rgba(0,0,255,.5),0 0 40px rgba(255,51,119,.6); }
.combo-surge.fire20 .csn-combo { color:#aa66ff;text-shadow:-5px 0 rgba(255,0,120,.6),5px 0 rgba(0,120,255,.6),0 0 50px rgba(170,102,255,.8),0 0 80px rgba(170,102,255,.4); }

