.craft-section-title { font-size:10px;font-weight:900;color:rgba(255,255,255,.3);text-transform:uppercase;letter-spacing:1.2px;margin:14px 0 8px;display:flex;align-items:center;gap:6px; }
.craft-section-title::after { content:'';flex:1;height:1px;background:rgba(255,255,255,.05); }
.craft-recipe-card { border-radius:20px;padding:16px;margin-bottom:10px;position:relative;overflow:hidden;border:2px solid transparent;transition:all .2s; }
.craft-recipe-card.available { border-color:rgba(255,136,68,.3);background:linear-gradient(160deg,rgba(28,10,0,.9),rgba(14,5,0,.95));box-shadow:0 0 20px rgba(255,136,68,.06); }
.craft-recipe-card.locked { background:rgba(6,2,12,.7);border-color:rgba(255,255,255,.04);opacity:.6; }
.craft-rc-top { display:flex;align-items:center;gap:12px;margin-bottom:12px; }
.craft-rc-ico { font-size:32px; }
.craft-rc-info { flex:1; }
.craft-rc-name { font-size:14px;font-weight:900; }
.craft-rc-desc { font-size:10px;color:rgba(255,255,255,.45);margin-top:3px; }
.craft-rc-effect { font-size:11px;font-weight:700;margin-top:4px; }
.craft-ingredients { display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px; }
.craft-ing { display:flex;align-items:center;gap:4px;padding:4px 8px;border-radius:10px;font-size:10px;font-weight:700; }
.craft-ing.have { background:rgba(0,255,136,.1);border:1px solid rgba(0,255,136,.25);color:var(--green); }
.craft-ing.missing { background:rgba(255,68,85,.08);border:1px solid rgba(255,68,85,.2);color:var(--red); }
.craft-btn { width:100%;border:none;border-radius:14px;padding:11px;font-family:var(--ff-head);font-size:13px;font-weight:900;cursor:pointer;transition:all .18s; }
.craft-btn.can { background:linear-gradient(135deg,#ff8844,#ffcc00);color:#000; }
.craft-btn.cannot { background:rgba(255,255,255,.05);color:rgba(255,255,255,.25);cursor:not-allowed; }
.craft-btn.crafting { animation:craftSpin .6s ease-in-out infinite; }
@keyframes craftSpin { 0%,100%{transform:scale(1)} 50%{transform:scale(.95);filter:brightness(1.3)} }

/* ══ DAILY XP RACE ══ */
.race-panel { padding:12px 16px; }
.race-hdr { display:flex;align-items:center;justify-content:space-between;margin-bottom:16px; }
.race-title-txt { font-family:var(--ff-head);font-size:16px;font-weight:900;background:linear-gradient(135deg,#ffcc00,#ff8844);-webkit-background-clip:text;-webkit-text-fill-color:transparent; }
.race-live-dot { width:7px;height:7px;border-radius:50%;background:var(--green);animation:lbLiveDot 1s ease-in-out infinite; }
.race-refresh { font-size:9px;color:rgba(255,255,255,.3); }
.race-row { display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:16px;margin-bottom:8px;position:relative;overflow:hidden;transition:all .3s; }
.race-row.you { border:2px solid rgba(255,204,0,.3);background:linear-gradient(160deg,rgba(28,20,0,.9),rgba(14,10,0,.95));box-shadow:0 0 20px rgba(255,204,0,.08); }
.race-row.rival { background:linear-gradient(160deg,rgba(10,4,22,.85),rgba(4,2,10,.9));border:1.5px solid rgba(255,255,255,.05); }
.race-row-flash { position:absolute;inset:0;pointer-events:none;opacity:0; }
.race-row.rank-up .race-row-flash { background:rgba(0,255,136,.08);animation:raceFlash .5s ease-out; }
.race-row.rank-dn .race-row-flash { background:rgba(255,68,85,.08);animation:raceFlash .5s ease-out; }
@keyframes raceFlash { 0%{opacity:1} 100%{opacity:0} }
.race-pos { font-family:var(--ff-head);font-size:16px;font-weight:900;min-width:24px;text-align:center; }
.race-pos.p1 { color:#ffcc00; }
.race-pos.p2 { color:#c0c0c0; }
.race-pos.p3 { color:#cd7f32; }
.race-ava { font-size:24px;flex:0 0 28px;text-align:center; }
.race-info { flex:1;min-width:0; }
.race-name { font-size:12px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis; }
.race-xp-bar-bg { height:5px;background:rgba(255,255,255,.06);border-radius:3px;overflow:hidden;margin-top:4px; }
.race-xp-bar-fill { height:100%;border-radius:3px;transition:width .6s cubic-bezier(.34,1.56,.64,1); }
.race-xp-v { font-size:11px;font-weight:900;min-width:60px;text-align:right; }
.race-delta { font-size:11px;font-weight:900;min-width:24px;text-align:right; }
.race-delta.up { color:var(--green); }
.race-delta.dn { color:var(--red); }
.race-delta.same { color:rgba(255,255,255,.3); }
.race-ticker { background:rgba(0,255,136,.06);border:1px solid rgba(0,255,136,.15);border-radius:12px;padding:8px 12px;margin-bottom:12px;font-size:10px;color:var(--green);font-weight:700;overflow:hidden;white-space:nowrap;text-overflow:ellipsis; }

/* ══ VIEW BACKGROUND FX ══ */
.vbg-canvas { position:absolute;inset:0;width:100%;height:100%;z-index:0;pointer-events:none;opacity:.65; }
#view-pet { position:relative; }
#view-games { position:relative; }
#view-lb { position:relative; }
#view-profile { position:relative; }
.fish-collection { padding:10px 0 4px; }
.fish-coll-hdr { font-size:11px; font-weight:800; color:var(--t2); margin-bottom:7px; display:flex; align-items:center; }
.fish-coll-grid { display:grid; grid-template-columns:repeat(7,1fr); gap:5px; }
.fish-coll-item { border-radius:10px; border:1.5px solid rgba(255,255,255,.07); background:rgba(10,4,22,.85); padding:5px 3px; text-align:center; transition:all .2s; box-shadow:0 3px 10px rgba(0,0,0,.4); }
.fish-coll-item.caught { background:rgba(0,0,0,.5); }
.fish-coll-item:active { transform:scale(.88); }

/* ══ RADIO NOW PLAYING ══ */
#radioNowPlaying { position:fixed; bottom:calc(76px + var(--sab)); left:50%; transform:translateX(-50%) translateY(140%); z-index:498; background:rgba(8,8,18,.97); backdrop-filter:blur(20px); border:1px solid rgba(0,255,136,.28); border-radius:24px; padding:9px 14px; display:flex; align-items:center; gap:10px; min-width:240px; max-width:310px; transition:transform .38s cubic-bezier(.32,.72,0,1); }
#radioNowPlaying.show { transform:translateX(-50%) translateY(0); }
.rnp-bars { display:flex; gap:2px; align-items:flex-end; height:20px; flex-shrink:0; }
.rnp-bar { width:3px; border-radius:2px; background:var(--green); box-shadow:0 0 4px var(--green); }
.rnp-bar-a { animation:rnpPulse .35s ease-in-out infinite alternate; }
.rnp-bar-b { animation:rnpPulse .5s .12s ease-in-out infinite alternate; }
.rnp-bar-c { animation:rnpPulse .25s .05s ease-in-out infinite alternate; }
.rnp-bar-d { animation:rnpPulse .42s .18s ease-in-out infinite alternate; }
.rnp-bar-e { animation:rnpPulse .32s .08s ease-in-out infinite alternate; }
@keyframes rnpPulse { from{height:3px} to{height:18px} }
.rnp-info { flex:1; overflow:hidden; }
.rnp-lbl { font-size:8px; color:var(--t3); font-weight:900; letter-spacing:1px; text-transform:uppercase; margin-bottom:1px; }
.rnp-song { font-family:var(--ff-head); font-size:12px; font-weight:900; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; color:var(--green); }
.rnp-next { font-size:8px; color:var(--t3); margin-top:1px; }
.rnp-stop { width:28px; height:28px; border-radius:8px; background:rgba(255,68,85,.12); border:1px solid rgba(255,68,85,.25); display:flex; align-items:center; justify-content:center; cursor:pointer; font-size:12px; flex-shrink:0; }
/* Circles upgrades */
.circ-trending { margin:0 14px 10px; background:rgba(0,0,0,.45); border:1px solid rgba(255,51,119,.14); border-radius:18px; overflow:hidden; }
.circ-trending-hdr { background:linear-gradient(135deg,rgba(255,51,119,.1),rgba(170,102,255,.07)); padding:9px 13px; display:flex; align-items:center; justify-content:space-between; border-bottom:1px solid rgba(255,51,119,.1); font-size:11px; font-weight:900; text-transform:uppercase; letter-spacing:.8px; }
.circ-trending-scroll { display:flex; gap:8px; overflow-x:auto; scrollbar-width:none; padding:8px 12px 10px; }
.circ-trending-scroll::-webkit-scrollbar { display:none; }
.circ-trend-pill { flex-shrink:0; padding:7px 14px; border-radius:14px; border:1.5px solid rgba(255,51,119,.2); background:rgba(255,51,119,.07); font-size:11px; font-weight:800; cursor:pointer; white-space:nowrap; transition:all .12s; color:var(--pink); }
.circ-trend-pill:active { transform:scale(.93); }
.circ-live-row { display:flex; align-items:center; gap:8px; margin:0 14px 8px; padding:8px 12px; font-size:10px; color:var(--t2); font-weight:700; background:rgba(0,255,136,.04); border:1px solid rgba(0,255,136,.12); border-radius:12px; }
.circ-live-dot { width:7px; height:7px; border-radius:50%; background:var(--green); animation:viewPulse 1.4s infinite; flex-shrink:0; }
.circles-hdr { background:linear-gradient(180deg,rgba(255,51,119,.05),transparent); }
.circles-title { background:linear-gradient(135deg,var(--pink),var(--purple)); -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text; font-size:30px; }

/* ══ LUCKY BOX ROUND 33 ══ */
#luckyModal .ms { background:radial-gradient(ellipse at 50% 0%,rgba(255,204,0,.14),rgba(0,0,0,.98) 65%); }
#luckyModal .mt { background:linear-gradient(135deg,rgba(255,204,0,.15),rgba(255,136,0,.1)); justify-content:center; font-family:var(--ff-head); font-size:17px; }
.lucky-box-wrap { position:relative; display:inline-block; margin:8px 0 4px; }
.lucky-box-ring { position:absolute; inset:-10px; border-radius:50%; background:conic-gradient(var(--gold),var(--orange),transparent 40%,var(--gold)); animation:spinRing 3s linear infinite; opacity:.55; pointer-events:none; border-radius:50%; width:calc(100% + 20px); height:calc(100% + 20px); }
@keyframes spinRing { to{transform:rotate(360deg)} }
.lucky-box-tap { font-size:12px; color:var(--t3); margin-bottom:6px; animation:blink 1.2s ease-in-out infinite; }
.lucky-rarity-pill { font-size:10px; font-weight:900; letter-spacing:2px; text-transform:uppercase; padding:4px 14px; border-radius:20px; display:inline-block; margin:8px 0 6px; }
.lucky-reveal { font-size:72px; display:block; text-align:center; animation:revealDrop .5s cubic-bezier(.17,.67,.3,1.3) .1s both; opacity:0; filter:drop-shadow(0 0 30px var(--gold)); }
.lucky-prize-n { font-size:26px; }

/* ══ DNA MIXER ROUND 33 ══ */
#dnaModal .mt { background:linear-gradient(135deg,rgba(0,255,136,.14),rgba(255,0,127,.1)); justify-content:flex-start; }
.dna-lab-bg { background:radial-gradient(ellipse at 50% 0%,rgba(0,255,80,.08),rgba(255,0,127,.06),transparent 70%) !important; }
.dna-strand-deco { text-align:center; font-size:22px; letter-spacing:6px; margin-bottom:10px; opacity:.65; animation:dnaPulse 2s ease-in-out infinite; }
@keyframes dnaPulse { 0%,100%{opacity:.5;letter-spacing:6px} 50%{opacity:.9;letter-spacing:10px} }
.dna-parent { background:rgba(0,0,0,.5); }
.dna-parent.selected { background:rgba(0,255,136,.07); box-shadow:0 0 20px rgba(0,255,136,.2); }
.dna-parent-em { font-size:44px; }
.dna-plus { font-size:32px; animation:dnaPulse 1.8s ease-in-out infinite; }
.dna-result-wrap { background:rgba(0,0,0,.6); border-width:2px; position:relative; overflow:hidden; }
.dna-result-wrap::before { content:''; position:absolute; inset:0; background:radial-gradient(ellipse at 50% 0%,rgba(255,204,0,.12),transparent 70%); pointer-events:none; }
.dna-result-em { font-size:64px; filter:drop-shadow(0 0 20px var(--gold)); }
.dna-splice-btn { letter-spacing:1px; box-shadow:0 6px 30px rgba(0,255,136,.35); }
.dna-splice-btn::after { content:''; position:absolute; top:0; left:-100%; width:60%; height:100%; background:linear-gradient(90deg,transparent,rgba(255,255,255,.15),transparent); animation:shimmerBtn 2.2s ease-in-out infinite; }
@keyframes shimmerBtn { to{left:140%} }

/* ══ ROUND 34 — Game Tabs, Map, Uppdrag ══ */
.gtab[onclick*="'battle'"].on { background:var(--red); border-color:var(--red); box-shadow:0 4px 18px rgba(255,68,85,.45); }
.gtab[onclick*="'speed'"].on { background:var(--gold); border-color:var(--gold); color:#000; box-shadow:0 4px 18px rgba(255,204,0,.45); }
.gtab[onclick*="'memory'"].on { background:var(--purple); border-color:var(--purple); box-shadow:0 4px 18px rgba(170,102,255,.45); }
.gtab[onclick*="'raid'"].on { background:#cc0033; border-color:#cc0033; color:#fff; box-shadow:0 4px 18px rgba(200,0,50,.45); }
.gtab[onclick*="'runner'"].on { background:var(--green); border-color:var(--green); color:#000; box-shadow:0 4px 18px rgba(0,255,136,.45); }
.gtab[onclick*="'katch'"].on { background:var(--teal); border-color:var(--teal); color:#000; box-shadow:0 4px 18px rgba(0,220,200,.45); }
.gtab[onclick*="'fish'"].on { background:var(--blue); border-color:var(--blue); box-shadow:0 4px 18px rgba(68,136,255,.45); }
.gps-bar { background:linear-gradient(180deg,rgba(0,0,0,.4),rgba(0,0,0,.25)); border-top:1px solid rgba(0,255,136,.12); }
.gps-dot.found { box-shadow:0 0 8px rgba(0,255,136,.6); }
.gps-dot.searching { background:var(--gold)!important; animation:gpsPing 1s ease-in-out infinite; }
@keyframes gpsPing { 0%,100%{box-shadow:0 0 0 0 rgba(255,204,0,.4)} 50%{box-shadow:0 0 0 6px rgba(255,204,0,0)} }

/* ══ ROUND 35 — All Game Panels Cinematic ══ */
/* Runner HUD */
.runner-hud { background:linear-gradient(180deg,rgba(0,6,24,.96),rgba(0,3,14,.8)); border-radius:16px; border:1px solid rgba(0,255,136,.1); padding:10px 14px 8px; margin-bottom:6px; }
.runner-stat-v { font-size:22px; }
.runner-stat-l { font-size:9px; color:var(--t3); font-weight:700; margin-top:1px; }
/* Speed/React arena */
.speed-arena { background:linear-gradient(135deg,rgba(0,0,20,.97),rgba(0,4,32,.9)); border-color:rgba(255,204,0,.18); }
.speed-arena-bg { background:radial-gradient(ellipse at 50% 50%,rgba(255,204,0,.07),rgba(0,255,136,.03),transparent 65%); }
/* Memory stats */
.mem-stats { background:linear-gradient(180deg,rgba(0,4,22,.96),rgba(0,2,14,.8)); border-color:rgba(170,102,255,.15); }
.mem-stat-v { color:var(--purple)!important; }
/* Raid game */
.raid-boss-card { background:radial-gradient(ellipse at 50% 0%,rgba(255,34,85,.22) 0%,rgba(0,0,12,.95) 70%) !important; border-color:rgba(255,34,85,.38); }
.raid-you-hp { background:rgba(0,4,14,.65); border:1px solid rgba(0,255,136,.14); border-radius:14px; padding:8px 12px; }
.raid-btn.sp { box-shadow:0 2px 14px rgba(255,34,85,.18); }
.raid-btn.def { box-shadow:0 2px 14px rgba(68,136,255,.18); }
.raid-btn.heal { box-shadow:0 2px 14px rgba(0,255,136,.18); }
.raid-btn.ult { padding:14px 6px; font-size:14px; box-shadow:0 2px 14px rgba(255,204,0,.18); }
/* Battle arena b2 (already has bg from R27, just add more glow) */
.b2-arena-bg::before { background:radial-gradient(ellipse at 50% 50%,rgba(255,34,85,.18) 0%,rgba(0,0,10,.98) 65%) !important; }
.b2-vs { font-family:var(--ff-head); font-size:26px; font-weight:900; color:var(--red); animation:vsFlash 1.8s ease-in-out infinite; }
@keyframes vsFlash { 0%,100%{text-shadow:0 0 10px rgba(255,34,85,.4)} 50%{text-shadow:0 0 30px rgba(255,34,85,.9),0 0 60px rgba(255,34,85,.4)} }
.b2-em { filter:drop-shadow(0 0 20px var(--pet-col,rgba(0,255,136,.6))); }

/* ══ ROUND 36 — Pet Home Screen Cinematic Upgrade ══ */
/* Pet info card */
.pet-info-card { background:linear-gradient(180deg,rgba(0,4,22,.96),rgba(0,2,12,.85)) !important; border-color:rgba(0,255,136,.12) !important; }
.pet-name-big { font-size:24px; background:linear-gradient(135deg,#fff,rgba(255,255,255,.75)); -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text; }
/* Stat boxes colored borders */
.stat-box:nth-child(1) { border-color:rgba(255,68,85,.25)!important; background:rgba(255,68,85,.04)!important; }
.stat-box:nth-child(2) { border-color:rgba(255,204,0,.25)!important; background:rgba(255,204,0,.04)!important; }
.stat-box:nth-child(3) { border-color:rgba(68,136,255,.25)!important; background:rgba(68,136,255,.04)!important; }
.stat-val { font-size:24px; }
/* Pet stage vitals bars — thicker and more visible */
.psv-bar { height:6px; background:rgba(255,255,255,.08); border-radius:4px; }
.psv-fill { box-shadow:0 0 6px currentColor; }
/* Care buttons — subtle colored tint per accent */
.care-btn[data-accent="orange"] { background:rgba(255,136,0,.07)!important; }
.care-btn[data-accent="red"] { background:rgba(255,68,85,.07)!important; }
.care-btn[data-accent="blue"] { background:rgba(68,136,255,.07)!important; }
.care-btn[data-accent="purple"] { background:rgba(170,102,255,.07)!important; }
.care-btn[data-accent="gold"] { background:rgba(255,204,0,.07)!important; }
.care-btn[data-accent="green"] { background:rgba(0,255,136,.07)!important; }
.care-btn[data-accent="pink"] { background:rgba(255,51,119,.07)!important; }
.care-btn[data-accent="teal"] { background:rgba(0,221,204,.07)!important; }
.care-ico { font-size:28px; }
.care-lbl { font-size:10px; }
/* Care section header */
.care-section-hdr { display:flex; align-items:center; justify-content:space-between; padding:6px 14px 8px; }
.care-section-title { font-family:var(--ff-head); font-size:13px; font-weight:900; color:#fff; letter-spacing:.5px; }
/* Pet stage name pill */
.pet-stage-name { font-size:13px; letter-spacing:3px; padding:4px 16px; box-shadow:0 0 16px rgba(0,255,136,.2); }
/* XP bar upgrade */
.xp-track { height:9px; background:rgba(255,255,255,.05); }
.xp-fill { box-shadow:0 0 8px var(--green); }
/* Missions card */
.missions-card { border:1px solid rgba(255,204,0,.18); box-shadow:0 4px 20px rgba(255,204,0,.05); }

/* ══ ROUND 37 — Final Pet View Polish ══ */
/* Step card */
.step-card { background:linear-gradient(180deg,rgba(0,4,22,.96),rgba(0,2,14,.85)) !important; border-color:rgba(68,136,255,.14) !important; }
.step-num { text-shadow:0 0 24px rgba(0,255,136,.4); }
.step-track { background:rgba(255,255,255,.05); }
.step-fill { box-shadow:0 0 8px var(--green); }
/* Global stats boxes */
.gstat-box { background:rgba(0,0,0,.45); border-color:rgba(255,255,255,.06) !important; }
/* Section headers — more visible */
.sh-t { font-size:12px !important; color:rgba(255,255,255,.6) !important; font-weight:800 !important; }
/* Minigame card upgrade */
.minigame-card { background:linear-gradient(180deg,rgba(0,4,22,.96),rgba(0,2,14,.85)) !important; border:1px solid rgba(0,255,136,.1); }
/* Leaderboard rows */
.lb-row { border-bottom-color:rgba(255,255,255,.04) !important; padding:13px 0; }
.lb-av { border-radius:14px; border:1.5px solid rgba(255,255,255,.07); }
.lb-nm { font-size:14px; font-weight:800; }
.lb-vl { font-size:16px; }
/* Friends activity section gap */
#friendsActivity { gap:8px !important; }
/* Theme chips on-state glow */
.theme-chip.on { border-color:var(--pet-col,var(--green)); color:var(--pet-col,var(--green)); background:rgba(0,255,136,.08); box-shadow:0 0 12px rgba(0,255,136,.2); }
/* Room theme section header */
.sh-t { letter-spacing:1px !important; }

/* ══ ROUND 38 — KATCH, Spin, KC Shop ══ */
#kcShopModal .ms { background:radial-gradient(ellipse at 50% 0%,rgba(170,102,255,.1),rgba(0,0,0,.98) 60%); }
#kcShopModal .mt { background:linear-gradient(135deg,rgba(170,102,255,.15),rgba(0,102,255,.08)); font-family:var(--ff-head); font-size:17px; }
.spin-won { font-size:26px; text-shadow:0 0 20px var(--green); }
.spin-outer { filter:drop-shadow(0 0 20px rgba(0,255,136,.2)); }
.katch-stat { text-align:center; }

/* ══ FISH FIGHT & UPGRADES ══ */
#fishFightWrap { display:none; padding:4px 0 6px; }
.fish-fight-lbl { display:flex; justify-content:space-between; font-size:10px; color:var(--t3); font-weight:800; margin-bottom:5px; }
.fish-fight-track { height:52px; background:rgba(255,255,255,.04); border-radius:14px; position:relative; overflow:hidden; border:2px solid rgba(255,100,0,.4); margin-bottom:7px; }
.fish-fight-zone { position:absolute; top:0; height:100%; background:rgba(0,255,136,.28); border-radius:0; }
.fish-fight-fish { position:absolute; top:50%; transform:translateY(-50%); font-size:26px; line-height:1; transition:none; }
.fish-fight-btn { width:100%; padding:14px; border-radius:16px; font-family:var(--ff-head); font-size:15px; font-weight:900; background:linear-gradient(135deg,#ff4455,#ff007f); color:#fff; border:none; cursor:pointer; letter-spacing:1px; box-shadow:0 4px 20px rgba(255,68,85,.5); animation:fightBtnPulse .45s ease-in-out infinite; }
.fish-fight-btn:active { transform:scale(.95); animation:none; }
@keyframes fightBtnPulse { 0%,100%{box-shadow:0 4px 20px rgba(255,68,85,.4)} 50%{box-shadow:0 8px 36px rgba(255,0,127,.8),0 0 20px rgba(255,68,85,.6)} }
.fish-hp-bar { height:7px; border-radius:6px; background:rgba(255,255,255,.07); margin-bottom:3px; overflow:hidden; }
.fish-hp-fill { height:100%; border-radius:6px; background:linear-gradient(90deg,var(--green),var(--teal)); transition:width .15s; }
.fish-streak-row { display:flex; align-items:center; justify-content:space-between; padding:3px 2px 2px; min-height:24px; }
.fish-streak-badge { font-family:var(--ff-head); font-size:11px; font-weight:900; padding:2px 9px; border-radius:10px; background:linear-gradient(135deg,var(--gold),#ff8800); color:#000; animation:streakPop .3s ease; }
@keyframes streakPop { 0%{transform:scale(0) rotate(-10deg)} 70%{transform:scale(1.2)} 100%{transform:scale(1)} }
#fishWeatherRow { font-size:11px; color:var(--t3); font-weight:700; }
.fish-hotspot-ring { position:absolute; border-radius:50%; pointer-events:none; }

/* ══ FISHING ROUND 32 — Cinematic Overhaul ══ */
.fish-scene-wrap { position:relative; border-radius:20px; overflow:hidden; margin-bottom:4px; box-shadow:0 6px 40px rgba(0,10,60,.9); }
.fish-scene-wrap::after { content:''; position:absolute; inset:0; border-radius:20px; border:1.5px solid rgba(68,136,255,.3); pointer-events:none; z-index:3; }
#fishCanvas { width:100%; height:240px; border-radius:0; }
.fish-hud { background:linear-gradient(180deg,rgba(0,4,22,.96),rgba(0,2,14,.8)); border-radius:16px; padding:10px 14px 8px; margin-bottom:6px; border:1px solid rgba(68,136,255,.1); }
.fish-stat-v { font-size:22px; }
/* Catch flash overlay */
#fishCatchFlash { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; opacity:0; pointer-events:none; z-index:10; background:rgba(0,0,0,.82); backdrop-filter:blur(6px); border-radius:0; transition:opacity .2s; }
#fishCatchFlash.show { opacity:1; pointer-events:auto; }
.fcf-em { font-size:88px; display:block; animation:achDrop .55s cubic-bezier(.34,1.56,.64,1) both; line-height:1; }
.fcf-name { font-family:var(--ff-head); font-size:22px; font-weight:900; color:#fff; margin-top:10px; text-align:center; }
.fcf-rarity { font-size:9px; font-weight:900; letter-spacing:3px; text-transform:uppercase; margin-top:6px; padding:4px 14px; border-radius:20px; }
.fcf-gains { font-size:14px; font-weight:800; color:var(--green); margin-top:8px; }
.fcf-tap { font-size:10px; color:rgba(255,255,255,.4); margin-top:18px; animation:blink 1.2s ease-in-out infinite; }
@keyframes blink { 0%,100%{opacity:.4} 50%{opacity:1} }
/* Collection upgrade */
.fish-collection { background:linear-gradient(180deg,rgba(0,4,22,.95),rgba(0,2,12,.8)); border:1px solid rgba(68,136,255,.15); border-radius:18px; padding:12px 12px 8px; }
.fish-coll-hdr { font-family:var(--ff-head); font-size:13px; font-weight:900; color:#fff; margin-bottom:10px; }
.fish-coll-grid { grid-template-columns:repeat(5,1fr); gap:7px; }
.fish-coll-item { border-radius:12px; padding:8px 4px 6px; }
.fish-coll-item.caught.rc-rare { border-color:var(--blue)!important; box-shadow:0 0 8px rgba(68,136,255,.35); }
.fish-coll-item.caught.rc-epic { border-color:var(--purple)!important; box-shadow:0 0 12px rgba(170,102,255,.4); }
.fish-coll-item.caught.rc-legendary { border-color:var(--gold)!important; box-shadow:0 0 16px rgba(255,204,0,.45); }
.fish-coll-item.caught.rc-mythic { border-color:var(--pink)!important; box-shadow:0 0 20px rgba(255,51,119,.55); animation:mythicGlow 2s ease-in-out infinite; }
@keyframes mythicGlow { 0%,100%{box-shadow:0 0 20px rgba(255,51,119,.55)} 50%{box-shadow:0 0 36px rgba(255,51,119,.9)} }
.fish-depth-opt { padding:8px 6px; border-radius:12px; font-size:10px; }
.fish-depth-opt.on { box-shadow:0 0 14px rgba(68,136,255,.25); }
.fish-cast-btn.cast { background:linear-gradient(135deg,#0033cc,var(--blue),var(--teal)); box-shadow:0 6px 30px rgba(68,136,255,.55); }
#fishFightWrap { background:rgba(255,40,0,.05); border:1px solid rgba(255,80,0,.18); border-radius:16px; padding:10px; }

/* ══ MAP FIX ══ */
.map-canvas { flex:1; position:relative; min-height:260px; overflow:hidden; }
#realMap { position:absolute; inset:0; width:100%; height:100%; }

/* ══ SPIN WHEEL CANVAS ══ */
#spinCanvas { display:block; margin:0 auto; }
.spin-canvas { display:none !important; }

/* ══ GAME TABS SCROLLABLE ══ */
.game-tabs { overflow-x:auto; scrollbar-width:none; flex-wrap:nowrap; }
.game-tabs::-webkit-scrollbar { display:none; }
.gtab { white-space:nowrap; flex-shrink:0; }

/* ══ HAMBURGER SCROLLABLE ══ */
.dd { max-height:calc(100svh - 75px); overflow-y:auto; scrollbar-width:none; }
.dd::-webkit-scrollbar { display:none; }

/* ══ VIDEO FEED FIX ══ */
.video-card { scroll-snap-align:start; min-height:100svh; overflow:hidden; }

/* ══════════════════════════════════════
   ROUND 31 — Missions, Friends, Care
══════════════════════════════════════ */

/* ── MISSION CARD UPGRADE ── */
.missions-card {
  background:linear-gradient(135deg,rgba(255,204,0,.04),rgba(0,255,136,.02)) !important;
  border-color:rgba(255,204,0,.18) !important;
}
.missions-hdr {
  background:linear-gradient(90deg,rgba(255,204,0,.06),transparent);
  border-bottom:1px solid rgba(255,204,0,.12);
}
.missions-title { color:var(--gold) !important; }
.m-prog-wrap { height:5px !important; border-radius:3px !important; }
.m-prog { border-radius:3px !important; }
.mission-row {
  transition:background .12s,border-left-color .3s;
  border-left:3px solid transparent; padding-left:13px !important;
}
.mission-row:not(.done):hover { background:rgba(255,255,255,.02); }
.mission-row[data-type="feed"]     { border-left-color:var(--orange); }
.mission-row[data-type="battle"]   { border-left-color:var(--red); }
.mission-row[data-type="flash"]    { border-left-color:var(--pink); }
.mission-row[data-type="uppdrag"]  { border-left-color:var(--gold); }
.mission-row[data-type="social"]   { border-left-color:var(--blue); }
.mission-row[data-type="runner"]   { border-left-color:var(--green); }
.m-done-chip {
  display:inline-flex; align-items:center; gap:3px;
  background:rgba(0,255,136,.12); color:var(--green);
  font-size:9px; font-weight:900; padding:3px 8px; border-radius:10px;
  border:1px solid rgba(0,255,136,.25);
}
.m-rwd-chip {
  background:rgba(255,204,0,.1); border:1px solid rgba(255,204,0,.25);
  color:var(--gold); font-size:11px; font-weight:900;
  padding:4px 9px; border-radius:10px;
}
.missions-complete-bar {
  height:3px; overflow:hidden;
  background:rgba(255,255,255,.05);
  border-radius:0 0 20px 20px;
}
.missions-complete-fill {
  height:100%; background:linear-gradient(90deg,var(--gold),var(--green));
  transition:width .6s ease;
}

/* ── FRIENDS ACTIVITY UPGRADE ── */
.friend-act-card {
  display:flex; align-items:center; gap:10px;
  padding:10px 12px;
  background:linear-gradient(180deg,rgba(8,4,18,.95),rgba(4,2,10,.9)); border:1px solid rgba(255,255,255,.06);
  border-radius:14px; transition:background .12s;
}
.friend-act-card:active { background:rgba(255,255,255,.03); }
.fac-ava {
  width:36px; height:36px; border-radius:50%;
  background:rgba(14,6,30,.8); border:2px solid rgba(255,255,255,.1);
  display:flex; align-items:center; justify-content:center;
  font-size:18px; flex-shrink:0;
}
.fac-info { flex:1; min-width:0; }
.fac-user { font-weight:800; font-size:12px; }
.fac-action { font-size:11px; color:var(--t2); margin-top:1px; }
.fac-xp {
  background:rgba(0,255,136,.1); border:1px solid rgba(0,255,136,.2);
  color:var(--green); font-size:10px; font-weight:900;
  padding:3px 8px; border-radius:10px; flex-shrink:0;
}
.fac-time { font-size:9px; color:var(--t3); margin-top:2px; }

/* ── CARE GRID SPIN BADGE ── */
.care-spin-badge {
  position:absolute; top:-5px; right:-5px;
  background:var(--gold); color:#000;
  font-size:7px; font-weight:900; padding:2px 5px; border-radius:8px;
  pointer-events:none; z-index:10;
}

/* ══════════════════════════════════════
   ROUND 30 — Level-up, Splashes, Ach
══════════════════════════════════════ */

/* ── LEVEL-UP SPLASH UPGRADE ── */
#lvlSplash {
  background:radial-gradient(ellipse at 50% 30%,rgba(0,255,136,.18) 0%,rgba(0,0,0,.98) 65%) !important;
}
#lvlSplash .sp-title {
  font-size:62px !important; line-height:1; margin-bottom:4px;
  text-shadow:0 0 40px rgba(0,255,136,.6),0 0 80px rgba(0,255,136,.2);
}
.lvl-badge {
  display:inline-flex; align-items:center; gap:6px;
  background:linear-gradient(135deg,var(--green),var(--teal));
  color:#000; font-family:var(--ff-head); font-size:11px; font-weight:900;
  padding:5px 16px; border-radius:20px; letter-spacing:2px;
  margin-bottom:10px;
  animation:bonusPop .4s .2s cubic-bezier(.34,1.56,.64,1) both;
}
.lvl-stars {
  display:flex; gap:4px; justify-content:center; margin:12px 0;
  animation:bonusPop .4s .5s cubic-bezier(.34,1.56,.64,1) both;
}
.lvl-star {
  font-size:22px;
  animation:starSpin 1s ease-in-out infinite;
}
.lvl-star:nth-child(2) { animation-delay:.15s; font-size:28px; }
.lvl-star:nth-child(3) { animation-delay:.3s; }
@keyframes starSpin {
  0%,100% { transform:scale(1) rotate(0); }
  50% { transform:scale(1.3) rotate(20deg); }
}
.lvl-next-xp {
  font-size:12px; color:rgba(255,255,255,.4); margin-top:8px;
  animation:fadeInUp .4s .8s ease both;
}

/* ── STREAK SPLASH UPGRADE ── */
#streakSplash {
  background:radial-gradient(ellipse at 50% 30%,rgba(255,68,85,.15) 0%,rgba(0,0,0,.97) 65%) !important;
}
#streakSplash .sp-title { text-shadow:0 0 30px rgba(255,68,85,.5); }

/* ── ACHIEVEMENT UPGRADE ── */
.ach-big {
  position:relative;
}
.ach-big::before {
  content:''; position:absolute; inset:-20px;
  border-radius:50%;
  background:conic-gradient(var(--gold) 0%,var(--orange) 25%,var(--gold) 50%,#fff 75%,var(--gold) 100%);
  z-index:-1; opacity:.15;
  animation:achRing 3s linear infinite;
}
@keyframes achRing { to{transform:rotate(360deg)} }
#achieveOverlay {
  background:radial-gradient(ellipse at 50% 30%,rgba(255,204,0,.1) 0%,rgba(0,0,0,.95) 65%) !important;
}

/* ── REWARD SPLASH UPGRADE ── */
.sp-r {
  background:rgba(0,255,136,.06) !important;
  border:1.5px solid rgba(0,255,136,.2) !important;
  transition:transform .2s;
}
.sp-r:active { transform:scale(.93); }
.sp-rv { color:var(--green) !important; }

/* ══════════════════════════════════════
   ROUND 29 — Onboarding, Runner, LB
══════════════════════════════════════ */

/* ── ONBOARDING DRAMATIC UPGRADE ── */
/* .ob styles moved to intro v2 block above */
/* ob v2 overrides handled above */

/* ── RUNNER OVERLAY UPGRADE ── */
.runner-start-overlay {
  background:linear-gradient(180deg,rgba(0,0,18,.9),rgba(0,0,0,.75)) !important;
}
.runner-best-dsp {
  background:rgba(255,204,0,.08); border:1px solid rgba(255,204,0,.25);
  border-radius:14px; padding:10px 24px; margin-bottom:14px; text-align:center;
}
.rbd-val {
  font-family:var(--ff-head); font-size:38px; font-weight:900; color:var(--gold); line-height:1;
}
.rbd-lbl { font-size:9px; color:var(--t3); text-transform:uppercase; letter-spacing:1.5px; margin-top:2px; }

/* ── LEADERBOARD HEADER UPGRADE ── */
.lb-title {
  background:linear-gradient(120deg,var(--gold),var(--green));
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
  padding-bottom:4px !important;
}
.lb-live-strip {
  display:flex; align-items:center; gap:8px;
  padding:2px 16px 10px; font-size:11px; color:var(--t3);
}
.lb-live-dot { width:6px;height:6px;border-radius:50%;background:var(--green);animation:viewPulse 1.5s infinite;flex-shrink:0; }
.lb-season-chip {
  margin-left:auto;
  background:linear-gradient(135deg,var(--gold),var(--orange));
  color:#000; font-size:9px; font-weight:900; padding:3px 10px; border-radius:20px;
}

/* ── KATCH OVERLAY UPGRADE ── */
.katch-overlay {
  background:linear-gradient(180deg,rgba(0,0,28,.92),rgba(0,0,0,.8)) !important;
}

/* ══════════════════════════════════════
   ROUND 28 — Profile, Uppdrag, Tabs
══════════════════════════════════════ */

/* ── PROFILE COVER UPGRADE ── */
.prof-cover {
  height:148px !important;
}
.prof-cover-float {
  position:absolute; inset:0; pointer-events:none; overflow:hidden;
}
.pcf-em {
  position:absolute; font-size:18px; opacity:.12;
  animation:pcfFloat var(--d,5s) var(--delay,0s) ease-in-out infinite;
}
@keyframes pcfFloat {
  0%   { transform:translateY(0)   rotate(0deg); opacity:.08; }
  50%  { transform:translateY(-35px) rotate(10deg); opacity:.18; }
  100% { transform:translateY(0)   rotate(0deg); opacity:.08; }
}
.prof-ava {
  border:4px solid var(--bg) !important;
  box-shadow:0 0 0 2.5px var(--pet-col,var(--green)),0 8px 28px rgba(0,0,0,.6) !important;
}

/* ── UPPDRAG FILL BAR ── */
.uc-fill-track {
  height:3px; background:rgba(255,255,255,.07); border-radius:0 0 20px 20px; overflow:hidden;
}
.uc-fill-inner {
  height:100%; border-radius:2px;
  background:linear-gradient(90deg,var(--green),var(--teal));
  transition:width .6s ease;
}
.uc-fill-inner.hot { background:linear-gradient(90deg,var(--red),var(--orange)); }
.uc-foot { flex-wrap:wrap; gap:4px; }

/* ── FLASH TAB COUNTS ── */
.ftab-cnt {
  display:inline-block; background:rgba(255,255,255,.12); color:rgba(255,255,255,.6);
  font-size:9px; font-weight:900; padding:0 5px; border-radius:8px;
  margin-left:4px; line-height:1.5;
}
.ftab.on .ftab-cnt { background:rgba(255,255,255,.25); color:#fff; }

/* ── PROFILE STAT COLORS ── */
.ps:nth-child(1) .ps-v { color:var(--pink) !important; }
.ps:nth-child(2) .ps-v { color:var(--gold) !important; }
.ps:nth-child(3) .ps-v { color:var(--green) !important; }
.ps:nth-child(4) .ps-v { color:var(--blue) !important; }
.ps:nth-child(5) .ps-v { color:var(--red) !important; }
.ps:nth-child(6) .ps-v { color:var(--teal) !important; }
.ps:nth-child(7) .ps-v { color:var(--purple) !important; }
.ps:nth-child(8) .ps-v { color:var(--orange) !important; }

/* ── CARE GRID SPIN PULSE ── */
.care-btn[data-accent="gold"] {
  animation:careWarn 2s ease-in-out infinite;
}
.care-btn[data-accent="gold"]::before {
  background:rgba(255,204,0,.18) !important;
}

/* ══════════════════════════════════════
   ROUND 27 — Shop, Battle, Leaderboard
══════════════════════════════════════ */

/* ── SHOP WINDOW HEADER ── */
.shop-win-hdr {
  padding:calc(var(--sat)+12px) 16px 0; flex-shrink:0;
  background:linear-gradient(160deg,rgba(255,204,0,.08),rgba(170,102,255,.06));
  position:relative; overflow:hidden;
}
.shop-win-hdr::after {
  content:''; position:absolute; bottom:0; left:0; right:0; height:1px;
  background:linear-gradient(90deg,transparent,rgba(255,204,0,.3),transparent);
}
.swh-top { display:flex; align-items:center; gap:10px; padding-bottom:14px; }
.swh-title {
  font-family:var(--ff-head); font-size:26px; font-weight:900;
  background:linear-gradient(120deg,var(--gold),var(--orange));
  -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text;
  flex:1;
}
.swh-coins {
  background:rgba(255,204,0,.12); border:1px solid rgba(255,204,0,.3);
  border-radius:20px; padding:6px 12px;
  font-size:13px; font-weight:900; color:var(--gold);
}
.shop-hot-deal {
  display:flex; align-items:center; gap:10px;
  margin-bottom:14px; padding:10px 12px;
  background:linear-gradient(135deg,rgba(255,68,34,.12),rgba(255,136,68,.08));
  border:1.5px solid rgba(255,68,34,.35); border-radius:14px;
  cursor:pointer;
}
.shd-badge {
  font-size:8px; font-weight:900; letter-spacing:1.5px; color:var(--red);
  text-transform:uppercase; background:rgba(255,68,34,.15); padding:2px 7px;
  border-radius:6px; margin-bottom:3px;
}
.shd-name { font-family:var(--ff-head); font-size:14px; font-weight:900; }
.shd-desc { font-size:10px; color:var(--t3); }
.shd-price {
  font-family:var(--ff-head); font-size:20px; font-weight:900;
  color:var(--gold); margin-left:auto; flex-shrink:0;
}

/* ── SHOP THEME CARD UPGRADED ── */
.shop-theme-card {
  background:linear-gradient(160deg,rgba(14,6,30,.9),rgba(6,2,14,.95)); border:2px solid rgba(255,255,255,.08);
  border-radius:16px; padding:12px 8px; cursor:pointer;
  transition:all .18s; position:relative; text-align:center; overflow:hidden;
}
.shop-theme-card:active { transform:scale(.94); }
.shop-theme-card.owned { border-color:rgba(0,255,136,.4); }
.shop-theme-card.equip { border-color:var(--gold); background:rgba(255,204,0,.06); }
.stc-swatch {
  width:100%; height:40px; border-radius:10px; margin-bottom:8px;
}
.stc-name { font-size:11px; font-weight:800; margin-bottom:2px; }
.stc-price { font-size:10px; color:var(--t2); }
.stc-badge {
  position:absolute; top:-5px; right:-5px; background:var(--green);
  color:#000; font-size:8px; font-weight:900; padding:2px 6px; border-radius:8px;
}
.stc-badge.eq { background:var(--gold); }

/* ── BATTLE ARENA BG ── */
.b2-arena-bg {
  position:absolute; inset:0; pointer-events:none; z-index:0; overflow:hidden;
}
.b2-arena-bg::before {
  content:''; position:absolute; inset:0;
  background:radial-gradient(ellipse at 50% 30%,rgba(255,51,119,.06) 0%,transparent 70%),
             radial-gradient(ellipse at 50% 70%,rgba(68,136,255,.06) 0%,transparent 70%);
}
.b2-arena-bg::after {
  content:''; position:absolute;
  left:50%; top:30%; width:180px; height:180px;
  transform:translate(-50%,-50%);
  background:radial-gradient(circle,rgba(255,0,0,.04),transparent 70%);
  animation:arenaPulse 2.5s ease-in-out infinite;
}
@keyframes arenaPulse {
  0%,100% { opacity:.5; transform:translate(-50%,-50%) scale(1); }
  50%      { opacity:1; transform:translate(-50%,-50%) scale(1.3); }
}
.battle2-wrap { position:relative; z-index:1; }

/* ── BATTLE FIGHTER ── */
.b2-em { font-size:52px !important; }
.b2-vs {
  font-size:28px !important; letter-spacing:-1px;
  text-shadow:0 0 20px var(--red), 0 0 40px rgba(255,68,85,.4) !important;
  animation:vsPulse 1.5s ease-in-out infinite;
}
@keyframes vsPulse { 0%,100%{text-shadow:0 0 20px var(--red),0 0 40px rgba(255,68,85,.4)} 50%{text-shadow:0 0 30px var(--red),0 0 60px rgba(255,68,85,.6)} }
.b2-hp-track { height:10px !important; border-radius:5px !important; }
.b2-hp-fill { height:100% !important; }
.b2-log {
  font-size:15px !important; background:rgba(10,4,22,.88) !important;
  border:1px solid rgba(255,255,255,.07) !important;
  border-radius:12px !important; padding:10px 14px !important;
  margin:8px 0 !important;
}
.b2-turn-badge {
  display:inline-block; background:linear-gradient(135deg,var(--green),var(--teal));
  color:#000; font-size:9px; font-weight:900; padding:3px 10px;
  border-radius:20px; letter-spacing:.5px;
  animation:turnBlink .9s ease-in-out infinite;
}
@keyframes turnBlink { 0%,100%{opacity:1} 50%{opacity:.6} }
