/* ── INTRO SPLASH ── */
#introSplash {
  position:fixed;inset:0;z-index:9999;background:#000;
  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;
}
#introSplash.out { animation:iSplOut .6s cubic-bezier(.4,0,1,1) forwards; pointer-events:none; }
@keyframes iSplOut { 0%{opacity:1;transform:scale(1)} 100%{opacity:0;transform:scale(1.08)} }
.ispl-ring {
  width:96px;height:96px;border-radius:50%;
  background:linear-gradient(#000,#000) padding-box,
             conic-gradient(var(--green) 0%,var(--blue) 35%,var(--pink) 70%,var(--green) 100%) border-box;
  border:3px solid transparent;
  display:flex;align-items:center;justify-content:center;
  font-size:46px;animation:iRingSpin 1.8s linear infinite,iPop .65s cubic-bezier(.2,1.5,.4,1) both;
}
@keyframes iRingSpin { to{filter:hue-rotate(360deg)} }
@keyframes iPop { from{opacity:0;transform:scale(.15)} to{opacity:1;transform:scale(1)} }
.ispl-logo {
  font-family:var(--ff-head);font-size:42px;font-weight:900;letter-spacing:-2px;margin-top:6px;
  background:linear-gradient(120deg,var(--green),var(--blue),var(--pink));
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
  animation:iFadeUp .5s .35s ease both;
}
.ispl-sub {
  font-size:10px;letter-spacing:4px;color:var(--t3);text-transform:uppercase;
  animation:iFadeUp .5s .5s ease both;
}
.ispl-bar {
  width:130px;height:2px;border-radius:1px;background:rgba(255,255,255,.08);
  margin-top:26px;overflow:hidden;animation:iFadeUp .5s .55s ease both;
}
.ispl-fill {
  height:100%;border-radius:1px;width:0%;
  background:linear-gradient(90deg,var(--green),var(--blue),var(--pink));
  animation:iLoad 1.35s .65s cubic-bezier(.4,0,.2,1) forwards;
}
@keyframes iLoad { to{width:100%} }
@keyframes iFadeUp { from{opacity:0;transform:translateY(14px)} to{opacity:1;transform:translateY(0)} }

/* ── BNAV SLIDING INDICATOR ── */
#nbIndicator {
  position:absolute;bottom:calc(var(--sab)+2px);left:0;
  width:30px;height:3px;border-radius:2px;
  background:var(--green);box-shadow:0 0 10px var(--green);
  transition:left .22s cubic-bezier(.4,0,.2,1),background .2s,box-shadow .2s;
  pointer-events:none;
}
.nb.on .ni { animation:navBounce .3s cubic-bezier(.15,1.5,.4,1); }
@keyframes navBounce { 50%{transform:scale(1.45) translateY(-3px)} 100%{transform:scale(1.2)} }

/* ── FLASH CARD GRADIENT BACKGROUNDS ── */
.vc-grad-0{background:radial-gradient(ellipse 80% 80% at 30% 20%,#1a0a40,#04020e 65%)!important}
.vc-grad-1{background:radial-gradient(ellipse 80% 80% at 70% 30%,#042010,#010508 65%)!important}
.vc-grad-2{background:radial-gradient(ellipse 80% 80% at 50% 70%,#300808,#0e0202 65%)!important}
.vc-grad-3{background:radial-gradient(ellipse 80% 80% at 20% 60%,#081c2a,#020609 65%)!important}
.vc-grad-4{background:radial-gradient(ellipse 80% 80% at 60% 40%,#200a30,#060108 65%)!important}

/* ── FLASH CARD PROGRESS BAR ── */
.vc-progress {
  position:absolute;top:0;left:0;right:0;height:3px;z-index:20;
}
.vc-prog-fill {
  height:100%;width:0%;
  background:linear-gradient(90deg,var(--pink),var(--purple),var(--blue));
  animation:vcProg 8s linear forwards;
}
@keyframes vcProg { to{width:100%} }

/* ── FLASH CARD MUSIC STRIP ── */
.vc-music {
  display:flex;align-items:center;gap:7px;margin-top:7px;
  font-size:11px;color:rgba(255,255,255,.75);overflow:hidden;
}
.vc-music-disc {
  width:22px;height:22px;border-radius:50%;flex-shrink:0;
