  animation:discSpin 4s linear infinite;
}
@keyframes discSpin { to{transform:rotate(360deg)} }
.vc-music-txt { overflow:hidden;white-space:nowrap;flex:1; }
.vc-music-scroll { display:inline-block;animation:musicMarquee 9s linear infinite; }
@keyframes musicMarquee { 0%{transform:translateX(0)} 100%{transform:translateX(-55%)} }

