}
@keyframes navUnderline {
  from { opacity:0; transform:scaleX(0); }
  to   { opacity:1; transform:scaleX(1); }
}

/* ── EPIC: Pet stage - smaller, tighter ── */
.pet-stage {
  height: 220px !important;
