}

/* ── EPIC: 3D orbital rings ── */
.pet-aura {
  width: 200px !important; height: 200px !important;
  top: 50% !important; left: 50% !important;
  margin: -100px 0 0 -100px !important;
  border-radius: 50% !important;
  border: 1.5px solid rgba(0,240,255,.8) !important;
  box-shadow: 0 0 15px rgba(0,240,255,.6), 0 0 30px rgba(0,240,255,.2), inset 0 0 15px rgba(0,240,255,.08) !important;
  background: transparent !important;
  animation: ring1Orbit 3.5s linear infinite !important;
}
@keyframes ring1Orbit {
  from { transform: rotateX(72deg) rotateZ(0deg); }
  to   { transform: rotateX(72deg) rotateZ(360deg); }
}
.pet-aura::before {
  content: '';
  position: absolute;
  inset: 16px;
  border-radius: 50%;
  border: 1px solid rgba(160,80,255,.7);
  box-shadow: 0 0 12px rgba(160,80,255,.4);
  animation: ring2Orbit 5s linear infinite reverse;
}
@keyframes ring2Orbit {
  from { transform: rotateX(72deg) rotateZ(0deg); }
  to   { transform: rotateX(72deg) rotateZ(360deg); }
}
.pet-aura::after {
  content: '';
  position: absolute;
  inset: 32px;
  border-radius: 50%;
  border: 1px solid rgba(255,50,150,.5);
  box-shadow: 0 0 8px rgba(255,50,150,.3);
  animation: ring3Orbit 7s linear infinite;
}
@keyframes ring3Orbit {
  from { transform: rotateX(18deg) rotateZ(0deg); }
  to   { transform: rotateX(18deg) rotateZ(360deg); }
}

/* ── EPIC: Holographic platform ── */
