/* ── Global card ── */
.card, .ms, .sh-card, .quest-card {
  background: rgba(8,6,28,.88) !important;
  border: 1px solid rgba(60,50,140,.3) !important;
  border-radius: 16px !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
}

/* ── All interactive elements — zero dead zones ── */
button, [onclick]:not(script), .care-btn, .nb, .nb-center,
.ddr, [class*="-btn"], [class*="-close"], [data-v], .pill {
  touch-action: manipulation !important;
  -webkit-tap-highlight-color: transparent !important;
  cursor: pointer !important;
  -webkit-user-select: none !important;
  user-select: none !important;
}

/* ── Decorative elements — NO pointer events ── */
.pet-aura, .pet-aura::before, .pet-aura::after,
.pet-stage-bg, .pet-stage::before, .pet-stage::after,
.pet-particles, .vbg-canvas, .pet-stage-xp-ring {
  pointer-events: none !important;
}
.pet-emoji-big {
  pointer-events: auto !important;
  touch-action: manipulation !important;
  cursor: pointer !important;
  position: relative !important;
  z-index: 20 !important;
}

/* ══ CRITICAL NAV FIX: pet view must hide when switching tabs ══ */
/* Our earlier #view-pet { display:flex !important } broke tab switching */
#view-pet:not(.active),
#view-flash:not(.active),
#view-games:not(.active),
#view-profile:not(.active) { display: none !important; }

