/* ── Color tokens ── */
:root {
  --c-bg:       #010108;
  --c-bg2:      #080618;
  --c-bg3:      #0d0a22;
  --c-glass:    rgba(10,7,30,.85);
  --c-glass2:   rgba(14,10,38,.78);
  --c-border:   rgba(80,60,200,.22);
  --c-border2:  rgba(0,200,255,.18);
  --c-cyan:     #00f0ff;
  --c-purple:   #7b2fff;
  --c-pink:     #ff2d78;
  --c-gold:     #ffd700;
  --c-green:    #00ff88;
  --c-blue:     #4488ff;
  --c-orange:   #ff8800;
  --c-red:      #ff3344;
  --shadow-glow-c: 0 0 20px rgba(0,240,255,.25);
  --shadow-glow-p: 0 0 20px rgba(123,47,255,.3);
  --shadow-glow-k: 0 0 20px rgba(255,45,120,.3);
  --r-card: 20px;
  --r-btn:  14px;
  --blur:   blur(20px) saturate(1.8);
}

/* ── Deep space global background ── */
body, #app {
  background:
    radial-gradient(ellipse 200% 80% at 10% 0%,   rgba(80,20,255,.18) 0%, transparent 50%),
    radial-gradient(ellipse 150% 60% at 90% 100%,  rgba(0,180,255,.14) 0%, transparent 45%),
    radial-gradient(ellipse 100% 100% at 50% 50%, rgba(255,20,100,.05) 0%, transparent 60%),
    #010108 !important;
}

/* ── TOPBAR ── */
.topbar {
  position: fixed !important;
  top: 0 !important; left: 0 !important; right: 0 !important;
  height: calc(54px + var(--sat,0px)) !important;
  padding-top: var(--sat,0px) !important;
  background: rgba(4,2,16,.92) !important;
  border-bottom: 1px solid rgba(0,200,255,.1) !important;
  backdrop-filter: var(--blur) !important;
  -webkit-backdrop-filter: var(--blur) !important;
  z-index: 500 !important;
  box-shadow: 0 2px 30px rgba(0,0,0,.6), 0 1px 0 rgba(0,200,255,.08) !important;
}

/* Fix main so it starts below fixed topbar */
.main {
  margin-top: calc(54px + var(--sat,0px)) !important;
}

/* ── Animated KARMA logo ── */
.logo {
  font-size: 24px !important;
  letter-spacing: 1px !important;
  font-weight: 900 !important;
}
.logo span {
  background: linear-gradient(90deg, #00f0ff, #7b2fff, #ff2d78, #00f0ff) !important;
  background-size: 300% !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
  animation: logoRainbow 4s linear infinite !important;
}
@keyframes logoRainbow {
  0%   { background-position: 0% 50%; }
  100% { background-position: 300% 50%; }
}

/* ── Currency pills ── */
.pill {
  background: rgba(8,5,24,.88) !important;
  border: 1px solid rgba(80,60,200,.3) !important;
  border-radius: 20px !important;
  box-shadow: 0 2px 12px rgba(0,0,0,.4) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  padding: 5px 12px !important;
  font-size: 12px !important;
