/* ── BOTTOM NAV — ultra premium ── */
.bnav {
  position: fixed !important;
  bottom: 0 !important; left: 0 !important; right: 0 !important;
  z-index: 1000 !important;
  display: flex !important;
  align-items: center !important;
  padding: 6px 0 calc(6px + var(--sab,0px)) !important;
  background: rgba(4,2,16,.96) !important;
  border-top: 1px solid rgba(0,200,255,.1) !important;
  backdrop-filter: blur(32px) saturate(2) !important;
  -webkit-backdrop-filter: blur(32px) saturate(2) !important;
  box-shadow: 0 -4px 30px rgba(0,0,0,.5) !important;
}
.bnav::before {
  background: linear-gradient(90deg,
    rgba(0,255,136,0) 0%,
    rgba(0,240,255,.5) 25%,
    rgba(123,47,255,.5) 50%,
    rgba(255,45,120,.4) 75%,
    rgba(0,255,136,0) 100%) !important;
  height: 1.5px !important;
  animation: navRainbow 6s linear infinite !important;
  background-size: 200% !important;
}
@keyframes navRainbow {
  0%   { background-position: 0% 50%; }
  100% { background-position: 200% 50%; }
}

/* Nav button base */
.nb {
  flex: 1 !important;
  background: none !important;
  border: none !important;
  cursor: pointer !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  gap: 3px !important;
  padding: 4px 0 !important;
  touch-action: manipulation !important;
  -webkit-tap-highlight-color: transparent !important;
  -webkit-user-select: none !important;
  user-select: none !important;
  transition: transform .15s ease !important;
  position: relative !important;
}
.nb:active { transform: scale(.88) !important; }
.nb .ni {
  font-size: 22px !important;
  transition: transform .2s ease, filter .2s ease !important;
  filter: grayscale(.4) brightness(.75) !important;
}
.nb .nl {
  font-size: 9px !important;
  font-weight: 800 !important;
  letter-spacing: .8px !important;
  color: rgba(160,150,210,.5) !important;
  transition: color .2s ease !important;
}

/* Active tab states — each with unique color */
.nb[data-v="pet"].on .ni    { filter: drop-shadow(0 0 8px #00f0ff) brightness(1.2) !important; transform: scale(1.18) translateY(-1px) !important; }
.nb[data-v="pet"].on .nl    { color: #00f0ff !important; text-shadow: 0 0 8px rgba(0,240,255,.6) !important; }
.nb[data-v="flash"].on .ni  { filter: drop-shadow(0 0 8px #ff2d78) brightness(1.2) !important; transform: scale(1.18) translateY(-1px) !important; }
.nb[data-v="flash"].on .nl  { color: #ff2d78 !important; text-shadow: 0 0 8px rgba(255,45,120,.6) !important; }
.nb[data-v="games"].on .ni  { filter: drop-shadow(0 0 8px #4488ff) brightness(1.2) !important; transform: scale(1.18) translateY(-1px) !important; }
.nb[data-v="games"].on .nl  { color: #4488ff !important; text-shadow: 0 0 8px rgba(68,136,255,.6) !important; }
.nb[data-v="profile"].on .ni { filter: drop-shadow(0 0 8px #ffd700) brightness(1.2) !important; transform: scale(1.18) translateY(-1px) !important; }
.nb[data-v="profile"].on .nl { color: #ffd700 !important; text-shadow: 0 0 8px rgba(255,215,0,.6) !important; }

/* Active indicator dot under active tab */
.nb::after {
  content: '' !important;
  position: absolute !important;
  bottom: 0 !important;
  width: 20px !important; height: 2px !important;
  border-radius: 99px !important;
  background: transparent !important;
  transition: background .2s, box-shadow .2s !important;
}
.nb[data-v="pet"].on::after    { background: #00f0ff !important; box-shadow: 0 0 8px #00f0ff !important; }
.nb[data-v="flash"].on::after  { background: #ff2d78 !important; box-shadow: 0 0 8px #ff2d78 !important; }
.nb[data-v="games"].on::after  { background: #4488ff !important; box-shadow: 0 0 8px #4488ff !important; }
.nb[data-v="profile"].on::after { background: #ffd700 !important; box-shadow: 0 0 8px #ffd700 !important; }

/* Center SKAPA button */
.nb-center {
  flex: 1 !important;
  background: none !important;
  border: none !important;
  cursor: pointer !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  gap: 2px !important;
  touch-action: manipulation !important;
