.nb-center:active .nb-center-ico { transform: scale(.85) !important; }
.nb-center .nl { font-size: 9px !important; font-weight: 800 !important; color: rgba(255,100,200,.8) !important; letter-spacing: .8px !important; }

/* ── Views: clip above nav ── */
.view {
  top: calc(54px + var(--sat,0px)) !important;
