/* Pet stage hero */
.pet-stage {
  height: clamp(210px, 42vh, 290px) !important;
  position: relative !important;
  overflow: visible !important;
  flex-shrink: 0 !important;
  background:
    radial-gradient(ellipse 110% 70% at 50% 40%,
      rgba(0,200,255,.1) 0%,
      rgba(100,30,255,.07) 50%,
      transparent 80%) !important;
