.sp-card { background: rgba(8,5,24,.88) !important; border: 1px solid rgba(123,47,255,.3) !important; border-radius: var(--r-card) !important; margin: 0 12px 12px !important; overflow: hidden !important; }

/* ════════════════════════════════════
   GLOBAL CARDS + BUTTONS
   ════════════════════════════════════ */
.card, .ms, .sh-card, .quest-card, .game-panel, .tourn-card {
  background: rgba(8,5,24,.88) !important;
  border: 1px solid rgba(60,45,160,.22) !important;
  border-radius: var(--r-card) !important;
  backdrop-filter: var(--blur) !important;
  -webkit-backdrop-filter: var(--blur) !important;
  box-shadow: 0 3px 18px rgba(0,0,0,.45) !important;
}

/* Buttons system */
.btn {
  border-radius: var(--r-btn) !important;
  font-weight: 800 !important;
  letter-spacing: .5px !important;
  transition: transform .12s, box-shadow .12s, opacity .12s !important;
  cursor: pointer !important;
  touch-action: manipulation !important;
  -webkit-tap-highlight-color: transparent !important;
  -webkit-user-select: none !important;
  border: none !important;
}
.btn:active { transform: scale(.88) !important; opacity: .85 !important; }
.btn-g { background: linear-gradient(135deg, #00cc66, #008844) !important; color: #fff !important; box-shadow: 0 4px 16px rgba(0,180,80,.4) !important; }
