.btn-ghost { background: rgba(80,60,200,.15) !important; border: 1px solid rgba(80,60,200,.3) !important; color: rgba(200,190,255,.9) !important; }

/* Tags/chips */
.tag { border-radius: 8px !important; font-size: 9px !important; font-weight: 900 !important; letter-spacing: 1px !important; padding: 3px 8px !important; }
.tg { background: rgba(80,60,200,.2) !important; border: 1px solid rgba(80,60,200,.3) !important; color: rgba(180,165,255,.9) !important; }

