.lr-fill { stroke: url(#lvGrad,#00f0ff) !important; transition: stroke-dashoffset .5s ease !important; }
.lv-n { font-size: 14px !important; font-weight: 900 !important; color: #fff !important; }
.lv-l { font-size: 7px !important; color: rgba(160,150,220,.7) !important; }

/* Float bubble */
#floatBubble, .float-bubble {
  background: rgba(8,5,24,.96) !important;
  border: 1.5px solid rgba(0,200,255,.4) !important;
  border-radius: 16px !important;
  box-shadow: 0 8px 30px rgba(0,0,0,.6), 0 0 20px rgba(0,200,255,.2) !important;
  backdrop-filter: var(--blur) !important;
  -webkit-backdrop-filter: var(--blur) !important;
  font-size: 13px !important;
  font-weight: 800 !important;
  letter-spacing: .5px !important;
}

/* XP ring inside stage */
.psr-bg { stroke: rgba(255,255,255,.05) !important; }
.psr-fill { stroke: #00f0ff !important; filter: drop-shadow(0 0 4px #00f0ff) !important; transition: stroke-dashoffset .6s ease !important; }

/* Aura ring */
.pet-aura {
  border-color: rgba(0,220,255,.75) !important;
  box-shadow: 0 0 20px rgba(0,200,255,.5), 0 0 40px rgba(0,200,255,.15), inset 0 0 20px rgba(0,200,255,.06) !important;
}

/* Trending card in profile */
.tourn-card { padding: 14px !important; }
.tourn-hdr { display: flex !important; align-items: center !important; justify-content: space-between !important; margin-bottom: 10px !important; }
.tourn-title { font-size: 14px !important; font-weight: 900 !important; letter-spacing: .5px !important; }
.tourn-cd { font-size: 12px !important; color: var(--c-gold) !important; font-weight: 800 !important; text-shadow: 0 0 8px rgba(255,215,0,.4) !important; }

/* Modals - glass */
.modal-inner, .modal-content, [id$="Modal"] > div {
  background: rgba(8,5,24,.96) !important;
  border: 1px solid rgba(80,60,200,.25) !important;
  border-radius: 24px !important;
  backdrop-filter: var(--blur) !important;
  -webkit-backdrop-filter: var(--blur) !important;
  box-shadow: 0 20px 60px rgba(0,0,0,.8) !important;
}

/* All interactive zero dead zones */
button, [onclick]:not(script), .care-btn, .nb, .nb-center,
.ddr, .ftab, .gtab, .uf, [class*="-btn"], [class*="-close"],
[data-v], .pill, .follow-stat, .feat-game-card {
  touch-action: manipulation !important;
  -webkit-tap-highlight-color: transparent !important;
  cursor: pointer !important;
