.cm-star-bar { width: 100%; height: 2px; background: rgba(255,255,255,.08); border-radius: 99px; overflow: hidden; }
.cm-star-fill { height: 100%; border-radius: 99px; background: linear-gradient(90deg, #ffd700, #ff8800); transition: width .5s ease; }

/* ── Neural Games HUD ── */
#neuralHUD {
