  to   { transform: rotateX(72deg) rotateZ(360deg); }
}

/* ── Scan effect on pet tap ── */
@keyframes petScan {
  0%   { top: -100%; opacity: 0; }
  10%  { opacity: .8; }
  90%  { opacity: .6; }
  100% { top: 100%; opacity: 0; }
}
#petScanLine {
  position: absolute;
