}
.ap-top { font-size: 8px; font-weight: 900; letter-spacing: 2.5px; color: rgba(255,215,0,.8); margin-bottom: 4px; }
.ap-main { display: flex; align-items: center; gap: 12px; }
.ap-ico { font-size: 34px; }
