.ap-desc { font-size: 10px; color: rgba(180,170,230,.75); margin-top: 2px; }

/* ── Pet mood ring (dynamic bg color) ── */
.pet-mood-glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  transition: background 2s ease;
  border-radius: inherit;
}

