.pc-title { font-size: 15px; font-weight: 900; color: #c87aff; flex: 1; }
.pc-count { font-size: 12px; color: rgba(255,255,255,0.45); }
.pc-body { padding: 12px 14px; }
.pc-grid { display: grid; grid-template-columns: repeat(5,1fr); gap: 8px; margin-bottom: 12px; }
.pc-pet-slot {
  aspect-ratio: 1; border-radius: 14px;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 2px; cursor: pointer; transition: all 0.25s; position: relative;
  border: 1px solid rgba(200,150,255,0.15);
}
.pc-pet-slot.owned {
  background: rgba(200,150,255,0.1);
  border-color: rgba(200,150,255,0.4);
}
.pc-pet-slot.locked {
  background: rgba(255,255,255,0.03);
  filter: grayscale(0.7) opacity(0.4);
}
.pc-pet-slot.active {
  border-color: #c87aff;
  box-shadow: 0 0 16px rgba(200,120,255,0.4);
  background: rgba(200,120,255,0.15);
}
.pc-pet-em { font-size: 24px; }
.pc-pet-lbl { font-size: 8px; color: rgba(255,255,255,0.4); text-align: center; }
.pc-pet-slot.active .pc-pet-lbl { color: #c87aff; }
.pc-star { position: absolute; top: 4px; right: 5px; font-size: 8px; color: #ffd700; }
.pc-summon-btn {
  width: 100%;
  background: linear-gradient(135deg, rgba(200,120,255,0.25), rgba(100,50,200,0.2));
  border: 1px solid rgba(200,120,255,0.4);
  border-radius: 12px; color: #c87aff; font-size: 14px; font-weight: 700; padding: 11px;
  cursor: pointer; transition: all 0.2s;
}
.pc-summon-btn:active { transform: scale(0.97); }

/* ─── KARMA STOCK MARKET ─── */
#karmaStockMarket {
  margin: 0 14px 12px;
  border-radius: 20px; overflow: hidden;
  border: 1px solid rgba(0,240,120,0.25);
  background: rgba(0,0,20,0.95);
  display: none;
}
#karmaStockMarket.visible { display: block; }
.ksm-header {
  background: linear-gradient(135deg, rgba(0,200,100,0.2), rgba(0,80,160,0.15));
  padding: 12px 14px; display: flex; align-items: center; gap: 10px;
}
.ksm-title { font-size: 15px; font-weight: 700; color: #00f078; flex: 1; }
.ksm-portfolio { font-size: 12px; color: rgba(255,255,255,0.5); }
.ksm-portfolio span { color: #00f078; font-weight: 700; }
.ksm-list { padding: 0 14px 4px; }
.ksm-stock {
  display: flex; align-items: center; gap: 10px; padding: 10px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.ksm-stock:last-child { border-bottom: none; }
.ksm-stock-icon { font-size: 24px; flex-shrink: 0; }
.ksm-stock-info { flex: 1; }
.ksm-stock-name { font-size: 13px; font-weight: 700; color: #fff; }
.ksm-stock-ticker { font-size: 10px; color: rgba(255,255,255,0.35); }
.ksm-stock-chart { width: 60px; height: 28px; }
.ksm-stock-price { text-align: right; }
.ksm-price-val { font-size: 14px; font-weight: 700; color: #fff; }
.ksm-price-change { font-size: 11px; font-weight: 600; }
.ksm-price-change.up { color: #00f078; }
.ksm-price-change.down { color: #ff4040; }
.ksm-actions { display: flex; gap: 8px; padding: 0 14px 12px; }
.ksm-trade-btn {
  flex: 1; border-radius: 10px; font-size: 13px; font-weight: 700; padding: 10px;
  cursor: pointer; transition: all 0.2s; border: 1px solid;
}
.ksm-trade-btn.buy { background: rgba(0,240,120,0.12); border-color: rgba(0,240,120,0.4); color: #00f078; }
.ksm-trade-btn.sell { background: rgba(255,80,80,0.12); border-color: rgba(255,80,80,0.4); color: #ff8080; }
.ksm-trade-btn:active { transform: scale(0.96); }

/* ─── HOLOGRAPHIC CONCERT ─── */
#concertOverlay {
  display: none; position: fixed; inset: 0; z-index: 9200;
  background: #000;
  flex-direction: column; align-items: center; justify-content: center;
}
#concertOverlay.open { display: flex; }
#concertCanvas { width: 100vw; max-width: 400px; }
.concert-info {
  color: #fff; text-align: center; padding: 10px 20px; z-index: 1;
  background: rgba(0,0,0,0.6);
}
.concert-title { font-size: 20px; font-weight: 900; letter-spacing: 3px; }
.concert-artist { font-size: 13px; color: rgba(255,255,255,0.5); margin-top: 4px; }
.concert-controls { display: flex; gap: 10px; margin-top: 12px; }
.concert-btn {
  background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.2);
  border-radius: 20px; color: #fff; font-size: 14px; padding: 10px 20px; cursor: pointer;
}
.concert-close-btn {
  position: absolute; top: 20px; right: 20px;
  background: rgba(255,255,255,0.1); border: none; color: #fff;
  border-radius: 50%; width: 36px; height: 36px; font-size: 16px; cursor: pointer;
}

/* ─── MASTER CONTROL PANEL ─── */
#masterControlPanel {
  margin: 0 14px 12px;
  background: rgba(0,0,20,0.95);
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: 20px; padding: 14px;
  display: none;
}
#masterControlPanel.visible { display: block; }
.mcp-title {
  font-size: 14px; font-weight: 700; color: rgba(255,255,255,0.8);
  text-transform: uppercase; letter-spacing: 2px; margin-bottom: 14px;
  text-align: center;
}
.mcp-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 10px; }
.mcp-control {
  background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.08);
  border-radius: 12px; padding: 10px;
}
.mcp-ctrl-label { font-size: 10px; color: rgba(255,255,255,0.4); margin-bottom: 6px; text-transform: uppercase; }
.mcp-toggle-row { display: flex; align-items: center; justify-content: space-between; }
.mcp-toggle-name { font-size: 12px; color: rgba(255,255,255,0.7); }
.mcp-toggle {
  width: 36px; height: 20px; border-radius: 10px;
  background: rgba(255,255,255,0.12); position: relative; cursor: pointer; transition: all 0.3s;
  flex-shrink: 0;
}
.mcp-toggle.on { background: rgba(0,240,120,0.5); }
.mcp-toggle::after {
  content: ''; position: absolute; top: 3px; left: 3px;
  width: 14px; height: 14px; border-radius: 50%; background: #fff;
  transition: all 0.3s;
}
.mcp-toggle.on::after { left: 19px; }
.mcp-slider-wrap { margin-top: 6px; }
.mcp-slider { width: 100%; -webkit-appearance: none; height: 4px; border-radius: 2px; background: rgba(255,255,255,0.15); outline: none; cursor: pointer; }
.mcp-slider::-webkit-slider-thumb { -webkit-appearance: none; width: 16px; height: 16px; border-radius: 50%; background: #00f0ff; cursor: pointer; }
.mcp-slider-val { font-size: 11px; color: #00f0ff; margin-top: 4px; text-align: right; }
.mcp-big-btn {
  width: 100%; background: linear-gradient(135deg,rgba(0,200,255,0.15),rgba(0,100,255,0.1));
  border: 1px solid rgba(0,200,255,0.3); border-radius: 12px;
  color: #00c8ff; font-size: 13px; font-weight: 700; padding: 12px;
  cursor: pointer; margin-bottom: 8px; transition: all 0.2s;
}
.mcp-big-btn:active { transform: scale(0.97); }
.mcp-reset-btn {
  width: 100%; background: rgba(255,80,80,0.1); border: 1px solid rgba(255,80,80,0.3);
  border-radius: 12px; color: #ff8080; font-size: 13px; font-weight: 700; padding: 12px;
  cursor: pointer; transition: all 0.2s;
}

/* === REACT COMPAT ADDITIONS (no visual changes) === */
#app { display: flex !important; }
.view { padding-top: calc(52px + var(--sat, 0px)); }
.view.active { display: flex; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes ambientFloat {
  0%   { opacity: 0; transform: translateY(0) rotate(0deg); }
  10%  { opacity: .5; }
  90%  { opacity: .4; }
  100% { opacity: 0; transform: translateY(-100vh) rotate(20deg); }
}

/* Live ticker positioning */
#liveTicker {
  position: fixed;
  bottom: calc(56px + var(--sab, 0px));
  left: 0; right: 0;
  max-width: 430px;
  margin: 0 auto;
  z-index: 150;
}
